    const WARDROBE_OVERHEAD_FULL_PNG_BASE64 = "";
    const WARDROBE_OVERHEAD_FULL_PNG = `data:image/png;base64,${WARDROBE_OVERHEAD_FULL_PNG_BASE64}`;
    const WARDROBE_OVERHEAD_EMPTY_ZONE_BASE64 = "";
