    function initHookBackend() {
        const sdk = window.bcModSdk || window.bcModSDK;
        if (!sdk || typeof sdk.registerMod !== "function") {
            hookBackend = "direct";
            return;
        }

        try {
            modApi = sdk.registerMod({
                name: MOD_NAME,
                fullName: DISPLAY_NAME,
                version: VERSION,
                repository: "https://github.com/marvelous-bc/subby-plushies",
            });
            hookBackend = "SDK";
        } catch (e) {
            modApi = null;
            hookBackend = "direct";
            warn("Hook registration was unavailable; using local wrappers instead:", e);
        }
    }

    function installHook(functionName, priority, handler) {
        if (installedHooks.has(functionName)) return true;
        const original = window[functionName];
        if (typeof original !== "function") return false;

        if (modApi && typeof modApi.hookFunction === "function") {
            modApi.hookFunction(functionName, priority, (args, next) => handler(args, next));
            installedHooks.add(functionName);
            return true;
        }

        if (original[CUSTOM_HOOK_MARK]) {
            installedHooks.add(functionName);
            return true;
        }

        const wrapped = function (...args) {
            const next = nextArgs => original.apply(this, Array.isArray(nextArgs) ? nextArgs : args);
            return handler(args, next);
        };

        try {
            Object.defineProperty(wrapped, CUSTOM_HOOK_MARK, { value: true });
        } catch (_) {}

        window[functionName] = wrapped;
        installedHooks.add(functionName);
        return true;
    }

    function dogsLockAssetName(lock) {
        if (typeof lock === "string") return lock;
        return lock?.Asset?.Name || lock?.Name || null;
    }

    function dogsAddonDetected() {
        try {
            if (typeof window.AssetGet === "function" &&
                window.AssetGet(FAMILY, "ItemMisc", DOGS_DEVIOUS_PADLOCK_NAME)) return true;
        } catch (_) {}

        try {
            const sdk = window.bcModSdk || window.bcModSDK;
            const mods = typeof sdk?.getModsInfo === "function" ? sdk.getModsInfo() : null;
            if (Array.isArray(mods) && mods.some(info => {
                const name = String(info?.name || "").trim();
                const fullName = String(info?.fullName || "").trim();
                return name.toUpperCase() === "DOGS" || /Devious\s+Obligate\s+Great\s+Stuff/i.test(fullName);
            })) return true;
        } catch (_) {}

        try {
            if (window.Player?.DOGS) return true;
            if (Array.isArray(window.ChatRoomCharacter) && window.ChatRoomCharacter.some(C => !!C?.DOGS)) return true;
        } catch (_) {}
        return false;
    }

    function dogsInventoryLockCompatibilityHandler(args, next) {
        const C = args?.[0];
        const itemOrGroup = args?.[1];
        const lock = args?.[2];
        if (dogsLockAssetName(lock) !== DOGS_DEVIOUS_PADLOCK_NAME) return next(args);

        const groupName = typeof itemOrGroup === "string"
            ? itemOrGroup
            : itemOrGroup?.Asset?.Group?.Name;
        if (!PLUSH_GROUPS.includes(groupName)) return next(args);

        const item = typeof itemOrGroup === "string"
            ? getInventoryItem(C, groupName)
            : itemOrGroup;
        if (!isOurs(item)) return next(args);

        const forwarded = Array.isArray(args) ? args.slice() : Array.from(args || []);
        const convertedGroupToItem = typeof itemOrGroup === "string";
        if (convertedGroupToItem) forwarded[1] = item;

        const result = next(forwarded);
        const property = getProperty(item);
        let markerRestored = false;

        if (property && itemHasActiveLock(item) && property.Name !== DOGS_DEVIOUS_PADLOCK_NAME) {
            property.Name = DOGS_DEVIOUS_PADLOCK_NAME;
            markerRestored = true;
        }

        dogsCompatibilityFixCount++;
        lastDogsCompatibilityFix = {
            groupName,
            convertedGroupToItem,
            markerRestored,
            lockedBy: property?.LockedBy || null,
            lockMemberNumber: property?.LockMemberNumber ?? null,
            at: new Date().toISOString(),
        };

        if (markerRestored && C === window.Player && window.CurrentScreen === "ChatRoom") {
            window.setTimeout(() => {
                try {
                    const current = getInventoryItem(window.Player, groupName);
                    if (isOurs(current) && current?.Property?.Name === DOGS_DEVIOUS_PADLOCK_NAME &&
                        typeof window.ChatRoomCharacterUpdate === "function") {
                        window.ChatRoomCharacterUpdate(window.Player);
                    }
                } catch (_) {}
            }, 0);
        }

        return result;
    }

    function installDogsCompatibilitySdkHook(api, label = "SDK") {
        if (dogsCompatibilitySdkHookInstalled || !api || typeof api.hookFunction !== "function") return false;
        try {
            api.hookFunction("InventoryLock", DOGS_COMPAT_HOOK_PRIORITY, (args, next) =>
                dogsInventoryLockCompatibilityHandler(args, next));
            dogsCompatibilitySdkHookInstalled = true;
            dogsCompatibilityHookInstalled = true;
            dogsCompatibilityBackend = label;
            installedHooks.add("InventoryLock");
            log(`DOGS Devious Padlock compatibility installed (${label}).`);
            return true;
        } catch (e) {
            warn("DOGS compatibility SDK hook could not be installed:", e);
            return false;
        }
    }

    function scheduleLateDogsCompatibilitySdkUpgrade(attempt = 0) {
        if (dogsCompatibilitySdkHookInstalled || modApi || attempt >= DOGS_COMPAT_SDK_RETRY_DELAYS_MS.length) return false;
        if (dogsCompatibilityRetryTimer != null) return true;

        dogsCompatibilityRetryTimer = window.setTimeout(() => {
            dogsCompatibilityRetryTimer = null;
            if (dogsCompatibilitySdkHookInstalled || modApi) return;

            const sdk = window.bcModSdk || window.bcModSDK;
            if (sdk && typeof sdk.registerMod === "function") {
                try {
                    dogsCompatibilityLateModApi = sdk.registerMod({
                        name: `${MOD_NAME}DOGSCompat`,
                        fullName: `${DISPLAY_NAME} — DOGS compatibility`,
                        version: VERSION,
                        repository: "https://github.com/marvelous-bc/subby-plushies",
                    });
                    if (installDogsCompatibilitySdkHook(
                        dogsCompatibilityLateModApi,
                        "late SDK high-priority bridge"
                    )) return;
                } catch (_) {
                    if (modApi && installDogsCompatibilitySdkHook(modApi, "main SDK high-priority bridge")) return;
                }
            }
            scheduleLateDogsCompatibilitySdkUpgrade(attempt + 1);
        }, DOGS_COMPAT_SDK_RETRY_DELAYS_MS[attempt]);
        return true;
    }

    function installDogsCompatibilityBridge() {
        if (modApi && typeof modApi.hookFunction === "function") {
            return installDogsCompatibilitySdkHook(modApi, "SDK high-priority bridge");
        }

        const directInstalled = installHook(
            "InventoryLock",
            DOGS_COMPAT_HOOK_PRIORITY,
            dogsInventoryLockCompatibilityHandler
        );
        dogsCompatibilityHookInstalled = directInstalled;
        dogsCompatibilityBackend = directInstalled
            ? "direct wrapper + late SDK upgrade"
            : "unavailable";
        scheduleLateDogsCompatibilitySdkUpgrade();
        return directInstalled;
    }

    function dogsCompatibilityDebugSnapshot() {
        const equipped = getEquippedPlushItems(window.Player).map(item => ({
            group: item?.Asset?.Group?.Name || null,
            marker: item?.Property?.Name || null,
            lockedBy: item?.Property?.LockedBy || null,
            lockMemberNumber: item?.Property?.LockMemberNumber ?? null,
            hasLockEffect: Array.isArray(item?.Property?.Effect) && item.Property.Effect.includes("Lock"),
        }));
        return {
            detected: dogsAddonDetected(),
            deviousPadlockAsset: (() => {
                try { return !!window.AssetGet?.(FAMILY, "ItemMisc", DOGS_DEVIOUS_PADLOCK_NAME); } catch (_) { return false; }
            })(),
            hookInstalled: dogsCompatibilityHookInstalled,
            sdkPriorityHookInstalled: dogsCompatibilitySdkHookInstalled,
            backend: dogsCompatibilityBackend,
            hookPriority: DOGS_COMPAT_HOOK_PRIORITY,
            fixCount: dogsCompatibilityFixCount,
            lastFix: lastDogsCompatibilityFix,
            equipped,
        };
    }

    function readLocalJSON(key, fallback) {
        try {
            const raw = window.localStorage?.getItem(key);
            if (!raw) return fallback;
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === "object" ? parsed : fallback;
        } catch (_) {
            return fallback;
        }
    }

    function writeLocalJSON(key, value) {
        try {
            window.localStorage?.setItem(key, JSON.stringify(value));
            return true;
        } catch (_) {
            return false;
        }
    }

    function getFeatureSettings() {
        if (featureSettingsState) return featureSettingsState;
        const stored = readLocalJSON(FEATURE_SETTINGS_STORAGE_KEY, {});
        const storedBoolean = key => Object.prototype.hasOwnProperty.call(stored, key)
            ? !!stored[key]
            : !!FEATURE_DEFAULTS[key];
        featureSettingsState = {
            protectMe: storedBoolean("protectMe"),
            jealousPlushie: storedBoolean("jealousPlushie"),
            showRoomMascot: storedBoolean("showRoomMascot"),
            autoUpdateChecks: storedBoolean("autoUpdateChecks"),
            idleAnimations: storedBoolean("idleAnimations"),
            speechBubbles: storedBoolean("speechBubbles"),
            showDragButton: storedBoolean("showDragButton"),
            extraActions: storedBoolean("extraActions"),
            sharedEmoteChains: storedBoolean("sharedEmoteChains"),
            expressionReactions: storedBoolean("expressionReactions"),
            ignorePoseChangingEmotes: storedBoolean("ignorePoseChangingEmotes"),
            highlightMyName: Object.prototype.hasOwnProperty.call(stored, "highlightMyName") ? !!stored.highlightMyName : false,
            performanceMode: String(stored.performanceMode || "normal").toLowerCase() === "low" ? "low" : "normal",
        };
        return featureSettingsState;
    }

    function setFeatureSetting(key, enabled) {
        const settings = getFeatureSettings();
        if (!Object.prototype.hasOwnProperty.call(settings, key) || key === "performanceMode") return false;
        settings[key] = !!enabled;
        writeLocalJSON(FEATURE_SETTINGS_STORAGE_KEY, settings);
        if (key === "idleAnimations") {
            if (settings[key] && !isLowCpuMode()) scheduleNextIdleAnimation(1200);
            else cancelIdleAnimation(false);
        }
        if (key === "speechBubbles" && !settings[key]) removeSpeechBubble();
        if (key === "highlightMyName") {
            if (settings[key]) highlightMyNameInVisibleChat();
            else clearMyNameHighlights();
        }
        if (key === "showDragButton") {
            if (settings[key]) refreshDragToggleButton();
            else removeDragToggleButton();
        }
        if (key === "extraActions") {
            syncExtraActionsAvailability("setting toggle");
        }
        if (key === "ignorePoseChangingEmotes" && settings[key]) {
            for (const [sessionKey, session] of [...extraRaisedArmSessions.entries()]) {
                if (session?.timer != null) window.clearTimeout(session.timer);
                extraRaisedArmSessions.delete(sessionKey);
                if (session?.character) {
                    forceRestoreTemporaryArmPose(session.character, session.beforeState, "pose-safety enabled");
                }
            }
        }
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        return settings[key];
    }

    function isLowCpuMode() {
        return getFeatureSettings().performanceMode === "low";
    }

    function performanceInterval(normalMs, lowCpuMs) {
        return isLowCpuMode() ? lowCpuMs : normalMs;
    }

    function restartPerformanceSensitiveMonitors() {
        if (plushStatusIconTimer != null) {
            window.clearTimeout(plushStatusIconTimer);
            plushStatusIconTimer = null;
        }
        startPlushStatusIconMonitor();

        if (roomRosterWatchdog != null) {
            window.clearInterval(roomRosterWatchdog);
            roomRosterWatchdog = window.setInterval(
                () => checkRoomRosterChange(isLowCpuMode() ? "10-minute watchdog" : "5-minute watchdog"),
                performanceInterval(ROOM_ROSTER_WATCHDOG_INTERVAL_MS, ROOM_ROSTER_WATCHDOG_INTERVAL_MS * 2)
            );
        }

        if (hugTightlyActivityMonitor != null) {
            window.clearTimeout(hugTightlyActivityMonitor);
            hugTightlyActivityMonitor = null;
            scheduleActivityIntegrityCheck();
        }

        return true;
    }

    function setPerformanceMode(mode) {
        const normalized = String(mode || "").trim().toLowerCase();
        const next = normalized === "low" || normalized === "low cpu" || normalized === "lowcpu" ? "low" : "normal";
        const settings = getFeatureSettings();
        settings.performanceMode = next;
        writeLocalJSON(FEATURE_SETTINGS_STORAGE_KEY, settings);
        cancelIdleAnimation(false);
        if (next === "normal" && settings.idleAnimations) scheduleNextIdleAnimation(1200);
        restartPerformanceSensitiveMonitors();
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        emitPluginApiEvent("performance", { mode: next });
        return next;
    }

    function toggleFeatureSetting(key) {
        const settings = getFeatureSettings();
        return setFeatureSetting(key, !settings[key]);
    }

    function sanitizeInterfaceColor(value, fallback) {
        const normalized = String(value || "").trim();
        return /^#[0-9a-f]{6}$/i.test(normalized) ? normalized.toUpperCase() : fallback;
    }

    function normalizeInterfacePalette(value) {
        const source = value && typeof value === "object" ? value : {};
        const palette = {};
        for (const key of INTERFACE_COLOR_KEYS) {
            palette[key] = sanitizeInterfaceColor(source[key], LOFI_MENU_STYLE[key]);
        }
        return palette;
    }

    function getLayoutSettings() {
        if (layoutSettingsState) return layoutSettingsState;
        const stored = readLocalJSON(LAYOUT_SETTINGS_STORAGE_KEY, {});
        layoutSettingsState = {
            useMenuDensity: stored.useMenuDensity === "compact" ? "compact" : LAYOUT_DEFAULTS.useMenuDensity,
            showHoverPreview: Object.prototype.hasOwnProperty.call(stored, "showHoverPreview") ? !!stored.showHoverPreview : LAYOUT_DEFAULTS.showHoverPreview,
            extensionsDensity: stored.extensionsDensity === "compact" ? "compact" : LAYOUT_DEFAULTS.extensionsDensity,
            loreListSide: stored.loreListSide === "right" ? "right" : LAYOUT_DEFAULTS.loreListSide,
            useMenuColors: normalizeInterfacePalette(stored.useMenuColors),
            extensionsColors: normalizeInterfacePalette(stored.extensionsColors),
        };
        return layoutSettingsState;
    }

    function getUseMenuStyle() {
        return getLayoutSettings().useMenuColors;
    }

    function getExtensionsStyle() {
        return getLayoutSettings().extensionsColors;
    }

    function setLayoutSetting(key, value) {
        const settings = getLayoutSettings();
        if (!Object.prototype.hasOwnProperty.call(settings, key)) return false;
        if (key === "useMenuDensity" || key === "extensionsDensity") value = value === "compact" ? "compact" : "cozy";
        else if (key === "loreListSide") value = value === "right" ? "right" : "left";
        else if (key === "useMenuColors" || key === "extensionsColors") value = normalizeInterfacePalette(value);
        else value = !!value;
        settings[key] = value;
        writeLocalJSON(LAYOUT_SETTINGS_STORAGE_KEY, settings);
        plushMenuListPage = 0;
        refreshPlushSearchInput();
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        return value;
    }

    function setInterfaceColor(scope, key, value) {
        if (!INTERFACE_COLOR_KEYS.includes(key)) return false;
        const settings = getLayoutSettings();
        const settingsKey = scope === "extensions" ? "extensionsColors" : "useMenuColors";
        const palette = normalizeInterfacePalette(settings[settingsKey]);
        palette[key] = sanitizeInterfaceColor(value, LOFI_MENU_STYLE[key]);
        settings[settingsKey] = palette;
        writeLocalJSON(LAYOUT_SETTINGS_STORAGE_KEY, settings);
        if (scope === "use") refreshPlushSearchInput();
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        return palette[key];
    }

    function applyInterfacePalette(scope, palette) {
        const settings = getLayoutSettings();
        const settingsKey = scope === "extensions" ? "extensionsColors" : "useMenuColors";
        settings[settingsKey] = normalizeInterfacePalette(palette);
        writeLocalJSON(LAYOUT_SETTINGS_STORAGE_KEY, settings);
        if (scope === "use") refreshPlushSearchInput();
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        return { ...settings[settingsKey] };
    }

    function resetInterfacePalette(scope) {
        return applyInterfacePalette(scope, LOFI_MENU_STYLE);
    }

    function copyInterfacePalette(fromScope, toScope) {
        const source = fromScope === "extensions" ? getExtensionsStyle() : getUseMenuStyle();
        return applyInterfacePalette(toScope, source);
    }

    function applySharedInterfaceTheme(palette) {
        const settings = getLayoutSettings();
        const normalized = normalizeInterfacePalette(palette);
        settings.useMenuColors = { ...normalized };
        settings.extensionsColors = { ...normalized };
        writeLocalJSON(LAYOUT_SETTINGS_STORAGE_KEY, settings);
        refreshPlushSearchInput();
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        return { ...normalized };
    }

    function resetLayoutSettings() {
        layoutSettingsState = {
            ...LAYOUT_DEFAULTS,
            useMenuColors: normalizeInterfacePalette(LOFI_MENU_STYLE),
            extensionsColors: normalizeInterfacePalette(LOFI_MENU_STYLE),
        };
        writeLocalJSON(LAYOUT_SETTINGS_STORAGE_KEY, layoutSettingsState);
        plushMenuListPage = 0;
        refreshPlushSearchInput();
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        return {
            ...layoutSettingsState,
            useMenuColors: { ...layoutSettingsState.useMenuColors },
            extensionsColors: { ...layoutSettingsState.extensionsColors },
        };
    }

    function useMenuLayoutMetrics() {
        const compact = getLayoutSettings().useMenuDensity === "compact";
        return compact
            ? { startY: 162, rowGap: 66, buttonH: 50, subStartY: 176, subRowGap: 90, searchTop: 105, searchHeight: 26, searchWidth: 340 }
            : { startY: 164, rowGap: 70, buttonH: 58, subStartY: 182, subRowGap: 106, searchTop: 104, searchHeight: 28, searchWidth: 350 };
    }

    function extensionsLayoutMetrics() {
        const compact = getLayoutSettings().extensionsDensity === "compact";
        return compact
            ? { buttonMinHeight: 32, buttonPadding: "4px 9px", sectionPadding: 10, sectionGap: 9, headingSize: 17, fontSize: 14, rowPadding: "5px 2px" }
            : { buttonMinHeight: 38, buttonPadding: "6px 11px", sectionPadding: 13, sectionGap: 12, headingSize: 19, fontSize: 15, rowPadding: "7px 2px" };
    }

    function currentWirePlushOption() {
        const option = canonicalWirePlushOption(getItemPlushOption(getHeld(window.Player)));
        return validPlushOption(option) ? option : SUBBYCAT_WIRE_OPTION;
    }

    function currentPlushName() {
        return PLUSH_NAMES[currentWirePlushOption()] || "Subbycat";
    }

    function publicPlushName(option) {
        const numeric = Number(option);
        if (!validPublicPlushOption(numeric)) return null;
        const wire = publicToWirePlushOption(numeric);
        return PLUSH_NAMES[wire] || null;
    }

    function publicOptionForPlushName(name) {
        const wanted = normalizeLoreLookupKey(name);
        if (!wanted) return -1;
        for (let option = 0; option < PUBLIC_PLUSH_COUNT; option++) {
            if (normalizeLoreLookupKey(publicPlushName(option)) === wanted) return option;
        }
        return -1;
    }

    function clonePluginApiPayload(value) {
        try {
            if (typeof structuredClone === "function") return structuredClone(value);
        } catch (_) {}
        try { return JSON.parse(JSON.stringify(value)); } catch (_) { return value; }
    }

    function emitPluginApiEvent(eventName, payload = {}) {
        const key = String(eventName || "").trim().toLowerCase();
        if (!key) return false;
        const listeners = pluginApiListeners.get(key);
        if (!listeners?.size) return false;
        const eventPayload = Object.freeze({
            event: key,
            at: new Date().toISOString(),
            ...clonePluginApiPayload(payload),
        });
        for (const listener of [...listeners]) {
            try { listener(eventPayload); } catch (e) { warn(`Extension API listener failed for ${key}:`, e); }
        }
        return true;
    }

    function onPluginApiEvent(eventName, listener) {
        const key = String(eventName || "").trim().toLowerCase();
        if (!key || typeof listener !== "function") return () => false;
        let listeners = pluginApiListeners.get(key);
        if (!listeners) { listeners = new Set(); pluginApiListeners.set(key, listeners); }
        listeners.add(listener);
        return () => offPluginApiEvent(key, listener);
    }

    function offPluginApiEvent(eventName, listener) {
        const key = String(eventName || "").trim().toLowerCase();
        const listeners = pluginApiListeners.get(key);
        if (!listeners) return false;
        const removed = listeners.delete(listener);
        if (!listeners.size) pluginApiListeners.delete(key);
        return removed;
    }

    function oncePluginApiEvent(eventName, listener) {
        if (typeof listener !== "function") return () => false;
        let unsubscribe = null;
        const wrapped = payload => {
            try { listener(payload); } finally { unsubscribe?.(); }
        };
        unsubscribe = onPluginApiEvent(eventName, wrapped);
        return unsubscribe;
    }

    function moodReasonLabel(reason) {
        const key = String(reason || "interaction").trim();
        const map = {
            rubFace: "Rub Against Face", cuddleChest: "Cuddle", nuzzle: "Nuzzle", pat: "Pat", pet: "Pet",
            hideBehind: "Hide Behind", kissPlushie: "Kiss", kissWith: "Kiss With Plushie", bonk: "Bonk",
            balanceHead: "Balance on Head", show: "Show Plushie", whisper: "Whisper", squeezeCheeks: "Squeeze Cheeks",
            noseBoop: "Nose Boop", cheekRest: "Rest Cheek", foreheadBump: "Forehead Bump", snugglePlushie: "Snuggle",
            wave: "Wave", hugTightly: "Hug Tightly", "hug tightly": "Hug Tightly", "room mascot": "Room Mascot",
            "idle decay": "Idle decay",
        };
        if (map[key]) return map[key];
        if (key.startsWith("jealous:")) return "Jealous";
        if (key.startsWith("protect me:")) return "Protect Me";
        return key.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/^./, char => char.toUpperCase());
    }

    function currentAccountMemberNumber() {
        const member = Number(window.Player?.MemberNumber);
        return Number.isFinite(member) && member > 0 ? Math.trunc(member) : null;
    }

    function accountStorageKey(prefix) {
        const member = currentAccountMemberNumber();
        return member == null ? null : `${prefix}${member}`;
    }

    function getBattleStatsStore() {
        const member = currentAccountMemberNumber();
        if (battleStatsState && battleStatsStateMember === member) return battleStatsState;
        const key = accountStorageKey(BATTLE_STATS_STORAGE_KEY_PREFIX);
        const stored = key ? readLocalJSON(key, {}) : {};
        battleStatsStateMember = member;
        battleStatsState = {
            played: Math.max(0, Number(stored.played) || 0),
            wins: Math.max(0, Number(stored.wins) || 0),
            losses: Math.max(0, Number(stored.losses) || 0),
            draws: Math.max(0, Number(stored.draws) || 0),
        };
        return battleStatsState;
    }

    function saveBattleStatsStore() {
        const key = accountStorageKey(BATTLE_STATS_STORAGE_KEY_PREFIX);
        return key ? writeLocalJSON(key, getBattleStatsStore()) : false;
    }

    function getBattleHistoryStore() {
        const member = currentAccountMemberNumber();
        if (battleHistoryState && battleHistoryStateMember === member) return battleHistoryState;
        const key = accountStorageKey(BATTLE_HISTORY_STORAGE_KEY_PREFIX);
        const stored = key ? readLocalJSON(key, { entries: [] }) : { entries: [] };
        const entries = Array.isArray(stored?.entries) ? stored.entries.slice(-20) : [];
        battleHistoryStateMember = member;
        battleHistoryState = { entries };
        return battleHistoryState;
    }

    function battleHistory(limit = 20) {
        return getBattleHistoryStore().entries.slice(-Math.max(1, Math.min(20, Number(limit) || 20))).map(entry => ({ ...entry }));
    }

    function recordBattleHistory(entry) {
        const store = getBattleHistoryStore();
        const normalized = {
            at: Number(entry?.at) || Date.now(),
            opponent: String(entry?.opponent || "Unknown"),
            opponentMember: Number(entry?.opponentMember) || 0,
            plush: String(entry?.plush || currentPlushName()),
            opponentPlush: String(entry?.opponentPlush || "Unknown"),
            score: Math.max(0, Number(entry?.score) || 0),
            opponentScore: Math.max(0, Number(entry?.opponentScore) || 0),
            result: ["win", "loss", "draw"].includes(entry?.result) ? entry.result : "draw",
        };
        store.entries.push(normalized);
        store.entries = store.entries.slice(-20);
        const key = accountStorageKey(BATTLE_HISTORY_STORAGE_KEY_PREFIX);
        if (key) writeLocalJSON(key, store);
        return { ...normalized };
    }

    function getRelationshipStore() {
        if (relationshipState) return relationshipState;
        const stored = readLocalJSON(RELATIONSHIP_STORAGE_KEY, {});
        relationshipState = stored && typeof stored === "object" ? stored : {};
        return relationshipState;
    }

    function relationshipLevelForInteractions(interactions) {
        const count = Math.max(0, Math.floor(Number(interactions) || 0));
        let level = RELATIONSHIP_LEVELS[0] || { name: "Stranger", minInteractions: 0 };
        for (const candidate of RELATIONSHIP_LEVELS) {
            if (count >= candidate.minInteractions) level = candidate;
            else break;
        }
        return level;
    }

    function getPlushRelationshipRecord(name = currentPlushName()) {
        const plushName = String(name || currentPlushName() || "Subbycat");
        const store = getRelationshipStore();
        let record = store[plushName];
        const now = Date.now();
        if (!record || typeof record !== "object") {
            record = { interactions: 0, lastInteractionAt: now, updatedAt: now };
            store[plushName] = record;
            scheduleRelationshipStoreSave();
            return record;
        }
        record.interactions = Math.max(0, Math.floor(Number(record.interactions) || 0));
        record.lastInteractionAt = Number(record.lastInteractionAt) || now;
        record.updatedAt = Number(record.updatedAt) || record.lastInteractionAt;
        return record;
    }

    function relationshipStatus(name = currentPlushName()) {
        const record = getPlushRelationshipRecord(name);
        const level = relationshipLevelForInteractions(record.interactions);
        const currentIndex = Math.max(0, RELATIONSHIP_LEVELS.findIndex(entry => entry.name === level.name));
        const next = RELATIONSHIP_LEVELS[currentIndex + 1] || null;
        return {
            name: String(name || currentPlushName()),
            interactions: record.interactions,
            level: level.name,
            nextLevel: next?.name || null,
            nextAt: next?.minInteractions ?? null,
            remaining: next ? Math.max(0, next.minInteractions - record.interactions) : 0,
            lastInteractionAt: record.lastInteractionAt,
        };
    }

    function maxRelationshipInteractions() {
        let best = 0;
        for (const record of Object.values(getRelationshipStore())) {
            best = Math.max(best, Math.max(0, Number(record?.interactions) || 0));
        }
        return best;
    }

    function showRelationshipMilestone(plushName, levelName) {
        if (!levelName || levelName === "Stranger") return false;
        const symbols = { Familiar: "♡", Friend: "♥", Bestie: "♥♥", Bonded: "✦♥✦" };
        const symbol = symbols[levelName] || "♥";
        showSpeechBubble(`${symbol} ${levelName}! ${symbol}`, { force: true, durationMs: 5200 });
        return true;
    }

    function touchPlushRelationship(name = currentPlushName(), { increment = 0, wake = true } = {}) {
        const plushName = String(name || currentPlushName() || "Subbycat");
        const store = getRelationshipStore();
        const record = getPlushRelationshipRecord(plushName);
        const before = relationshipLevelForInteractions(record.interactions).name;
        const amount = Math.max(0, Math.floor(Number(increment) || 0));
        if (amount) record.interactions += amount;
        if (wake) record.lastInteractionAt = Date.now();
        record.updatedAt = Date.now();
        store[plushName] = record;
        scheduleRelationshipStoreSave();
        const status = relationshipStatus(plushName);
        const milestone = amount > 0 && status.level !== before ? status.level : null;
        if (milestone) scheduleAchievementCheck(true);
        if (milestone) showRelationshipMilestone(plushName, milestone);
        refreshPlushStatusIcon();
        if (amount) emitPluginApiEvent("relationship", { plushName, ...status, milestone });
        return { ...status, milestone };
    }

    function isPlushSleepy(name = currentPlushName()) {
        const record = getPlushRelationshipRecord(name);
        return Date.now() - (Number(record.lastInteractionAt) || Date.now()) >= SLEEPY_AFTER_MS;
    }

    function getFavoritesStore() {
        if (favoritesState) return favoritesState;
        const stored = readLocalJSON(FAVORITES_STORAGE_KEY, {});
        const raw = Array.isArray(stored?.names) ? stored.names : [];
        const names = [];
        for (const value of raw) {
            const option = publicOptionForPlushName(value);
            const canonical = option >= 0 ? publicPlushName(option) : null;
            if (canonical && !names.some(entry => normalizeLoreLookupKey(entry) === normalizeLoreLookupKey(canonical))) names.push(canonical);
        }
        favoritesState = { names };
        return favoritesState;
    }

    function favoritePlushNames() {
        return [...getFavoritesStore().names];
    }

    function isFavoritePlush(name) {
        const wanted = normalizeLoreLookupKey(name);
        return !!wanted && getFavoritesStore().names.some(entry => normalizeLoreLookupKey(entry) === wanted);
    }

    function toggleFavoritePlush(name) {
        const option = publicOptionForPlushName(name);
        if (option < 0) return false;
        const canonical = publicPlushName(option);
        const store = getFavoritesStore();
        const wanted = normalizeLoreLookupKey(canonical);
        const index = store.names.findIndex(entry => normalizeLoreLookupKey(entry) === wanted);
        let enabled = false;
        if (index >= 0) store.names.splice(index, 1);
        else { store.names.push(canonical); enabled = true; }
        writeLocalJSON(FAVORITES_STORAGE_KEY, store);
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        emitPluginApiEvent("favorite", { plushName: canonical, favorite: enabled });
        return enabled;
    }

    function favoriteMenuEntries() {
        return favoritePlushNames()
            .map(name => ({ label: name, option: publicOptionForPlushName(name) }))
            .filter(entry => entry.option >= 0);
    }

    function sanitizeSavedPoseTransform(value) {
        const source = value && typeof value === "object" ? value : {};
        const finite = (key, fallback, min, max) => {
            const number = Number(source[key]);
            return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
        };
        return {
            TranslationX: finite("TranslationX", 0, -2000, 2000),
            TranslationY: finite("TranslationY", 0, -2000, 2000),
            ScaleX: finite("ScaleX", 1, 0.05, 8),
            ScaleY: finite("ScaleY", 1, 0.05, 8),
            Rotation: finite("Rotation", 0, -1080, 1080),
        };
    }

    function getSavedPosesStore() {
        if (savedPosesState) return savedPosesState;
        const stored = readLocalJSON(SAVED_POSES_STORAGE_KEY, {});
        savedPosesState = stored && typeof stored === "object" ? stored : {};
        return savedPosesState;
    }

    function getSavedPose(slot, name = currentPlushName()) {
        const numericSlot = Number(slot);
        if (!SAVED_POSE_SLOTS.includes(numericSlot)) return null;
        const raw = getSavedPosesStore()?.[name]?.[String(numericSlot)];
        return raw && typeof raw === "object" ? sanitizeSavedPoseTransform(raw) : null;
    }

    function saveCurrentPose(slot) {
        const numericSlot = Number(slot);
        if (!SAVED_POSE_SLOTS.includes(numericSlot)) return null;
        const item = getHeld(window.Player);
        if (!isOurs(item)) return null;
        const transform = readActivePlushLayerTransform(item);
        if (!transform) return null;
        const name = currentPlushName();
        const store = getSavedPosesStore();
        if (!store[name] || typeof store[name] !== "object") store[name] = {};
        const pose = sanitizeSavedPoseTransform(transform);
        store[name][String(numericSlot)] = pose;
        writeLocalJSON(SAVED_POSES_STORAGE_KEY, store);
        emitPluginApiEvent("pose", { action: "save", plushName: name, slot: numericSlot, pose });
        return { ...pose };
    }

    function applySavedPose(slot) {
        const numericSlot = Number(slot);
        const pose = getSavedPose(numericSlot);
        const item = getHeld(window.Player);
        const layerName = getActivePlushLayerName(item);
        if (!pose || !isOurs(item) || !layerName) return false;
        if (activeBalanceHeadSession) restoreActiveBalanceHead("saved pose");
        if (activeHideBehindSession) restoreActiveHideBehind("saved pose");
        if (activeProtectSession) restoreActiveProtect("saved pose");
        setPlushLayerTransform(item, layerName, pose);
        compactPlushLayerTransformsToActive(item, pose);
        resetGenericNativeTransform(item);
        rememberCharacterPlushState(window.Player, item);
        rebuildCharacterCanvas(window.Player, `saved pose ${numericSlot}`);
        try { if (typeof ChatRoomCharacterUpdate === "function") ChatRoomCharacterUpdate(window.Player); } catch (_) {}
        positionSpeechBubble();
        positionPlushStatusIcon();
        emitPluginApiEvent("pose", { action: "apply", plushName: currentPlushName(), slot: numericSlot, pose });
        return true;
    }

    function clearSavedPose(slot, name = currentPlushName()) {
        const numericSlot = Number(slot);
        if (!SAVED_POSE_SLOTS.includes(numericSlot)) return false;
        const store = getSavedPosesStore();
        if (!store?.[name] || !Object.prototype.hasOwnProperty.call(store[name], String(numericSlot))) return false;
        delete store[name][String(numericSlot)];
        if (!Object.keys(store[name]).length) delete store[name];
        writeLocalJSON(SAVED_POSES_STORAGE_KEY, store);
        emitPluginApiEvent("pose", { action: "clear", plushName: name, slot: numericSlot });
        return true;
    }

    function cloneBackupValue(value) {
        try { return JSON.parse(JSON.stringify(value ?? {})); } catch (_) { return {}; }
    }

    function stableBackupStringify(value) {
        if (Array.isArray(value)) return `[${value.map(stableBackupStringify).join(",")}]`;
        if (value && typeof value === "object") {
            return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${stableBackupStringify(value[key])}`).join(",")}}`;
        }
        return JSON.stringify(value);
    }

    async function sealBackupProgress(progress) {
        const payload = `${BACKUP_PROGRESS_SEAL_VERSION}|${BACKUP_PROGRESS_SEAL_KEY}|${stableBackupStringify(progress)}`;
        if (!window.crypto?.subtle || typeof TextEncoder !== "function") {
            let hash = 2166136261;
            for (let i = 0; i < payload.length; i++) {
                hash ^= payload.charCodeAt(i);
                hash = Math.imul(hash, 16777619);
            }
            return `fnv1a:${(hash >>> 0).toString(16).padStart(8, "0")}`;
        }
        const digest = await window.crypto.subtle.digest("SHA-256", new TextEncoder().encode(payload));
        return `sha256:${Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, "0")).join("")}`;
    }

    async function createBackupPayload() {
        const stats = cloneBackupValue(getStatsStore());
        delete stats.battles;
        const layout = cloneBackupValue(getLayoutSettings());
        const memberNumber = currentAccountMemberNumber();
        const progress = {
            stats,
            achievements: cloneBackupValue(stats.achievements || {}),
            relationships: cloneBackupValue(getRelationshipStore()),
        };
        const progressSeal = await sealBackupProgress(progress);
        return {
            schemaVersion: BACKUP_SCHEMA_VERSION,
            plugin: MOD_NAME,
            version: VERSION,
            exportedAt: new Date().toISOString(),
            account: { memberNumber },
            data: {
                progress,
                progressSeal,
                accountBattle: {
                    memberNumber,
                    stats: cloneBackupValue(getBattleStatsStore()),
                    history: cloneBackupValue(getBattleHistoryStore()),
                },
                moods: cloneBackupValue(getMoodStore()),
                favorites: cloneBackupValue(getFavoritesStore()),
                layouts: layout,
                themes: {
                    useMenuColors: cloneBackupValue(layout.useMenuColors || {}),
                    extensionsColors: cloneBackupValue(layout.extensionsColors || {}),
                },
                featureSettings: cloneBackupValue(getFeatureSettings()),
                nicknames: cloneBackupValue(readLocalJSON(NICKNAME_STORAGE_KEY, {})),
                savedPoses: cloneBackupValue(getSavedPosesStore()),
            },
        };
    }

    async function exportPlushBackup() {
        const payload = await createBackupPayload();
        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement("a");
        anchor.href = url;
        anchor.download = `SubbysPlushies-backup-${new Date().toISOString().slice(0, 10)}.json`;
        anchor.style.display = "none";
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
        window.setTimeout(() => URL.revokeObjectURL(url), 1000);
        return payload;
    }

    async function restorePlushBackup(payload) {
        if (!payload || typeof payload !== "object" || Number(payload.schemaVersion) !== BACKUP_SCHEMA_VERSION || !payload.data || typeof payload.data !== "object") {
            throw new Error("Unsupported Subby's Plushies backup file. This build only accepts the current backup format.");
        }
        cancelPendingStatsWork();
        const data = payload.data;
        const safeObject = value => value && typeof value === "object" && !Array.isArray(value) ? cloneBackupValue(value) : null;
        const layout = safeObject(data.layouts) || {};
        if (safeObject(data.themes?.useMenuColors)) layout.useMenuColors = normalizeInterfacePalette(data.themes.useMenuColors);
        if (safeObject(data.themes?.extensionsColors)) layout.extensionsColors = normalizeInterfacePalette(data.themes.extensionsColors);

        const progress = safeObject(data.progress);
        const suppliedSeal = typeof data.progressSeal === "string" ? data.progressSeal : "";
        const expectedSeal = progress ? await sealBackupProgress(progress) : "";
        const progressVerified = !!progress && !!suppliedSeal && suppliedSeal === expectedSeal;

        const writes = [
            [MOOD_STORAGE_KEY, safeObject(data.moods)],
            [FAVORITES_STORAGE_KEY, safeObject(data.favorites)],
            [LAYOUT_SETTINGS_STORAGE_KEY, layout],
            [FEATURE_SETTINGS_STORAGE_KEY, safeObject(data.featureSettings)],
            [NICKNAME_STORAGE_KEY, safeObject(data.nicknames)],
            [SAVED_POSES_STORAGE_KEY, safeObject(data.savedPoses)],
        ];
        if (progressVerified) {
            const stats = safeObject(progress.stats) || {};
            delete stats.battles;
            if (safeObject(progress.achievements)) stats.achievements = cloneBackupValue(progress.achievements);
            writes.unshift(
                [STATS_STORAGE_KEY, stats],
                [RELATIONSHIP_STORAGE_KEY, safeObject(progress.relationships)]
            );
        }

        for (const [key, value] of writes) {
            if (value) writeLocalJSON(key, value);
        }

        const battle = safeObject(data.accountBattle);
        const backupBattleMember = Number(battle?.memberNumber ?? payload.account?.memberNumber);
        const currentMember = currentAccountMemberNumber();
        const battleMatchesAccount = Number.isFinite(backupBattleMember) && currentMember != null && backupBattleMember === currentMember;
        let battleRestored = false;
        if (battleMatchesAccount && battle) {
            const battleStats = safeObject(battle.stats) || { played: 0, wins: 0, losses: 0, draws: 0 };
            const battleHistoryData = safeObject(battle.history) || { entries: [] };
            const statsKey = accountStorageKey(BATTLE_STATS_STORAGE_KEY_PREFIX);
            const historyKey = accountStorageKey(BATTLE_HISTORY_STORAGE_KEY_PREFIX);
            if (statsKey) writeLocalJSON(statsKey, battleStats);
            if (historyKey) writeLocalJSON(historyKey, battleHistoryData);
            battleRestored = !!statsKey && !!historyKey;
        }

        featureSettingsState = null;
        layoutSettingsState = null;
        moodState = null;
        battleHistoryState = null;
        battleHistoryStateMember = null;
        battleStatsState = null;
        battleStatsStateMember = null;
        relationshipState = null;
        favoritesState = null;
        savedPosesState = null;
        statsState = null;
        refreshPlushSearchInput();
        refreshPlushStatusIcon();
        restartPerformanceSensitiveMonitors();
        scheduleNextIdleAnimation(1000);
        checkAchievements(false);
        if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
        return {
            payload: await createBackupPayload(),
            progressVerified,
            battleRestored,
            battleMatchesAccount,
            backupBattleMember: Number.isFinite(backupBattleMember) ? backupBattleMember : null,
            currentMember,
        };
    }

    function importPlushBackupFromFile() {
        if (!backupImportInput?.isConnected) {
            const input = document.createElement("input");
            input.type = "file";
            input.accept = "application/json,.json";
            input.style.display = "none";
            input.addEventListener("change", async () => {
                const file = input.files?.[0];
                input.value = "";
                if (!file) return;
                try {
                    const payload = JSON.parse(await file.text());
                    if (typeof window.confirm === "function" && !window.confirm("Restore this Subby's Plushies backup? Current local plush settings will be replaced. Progress is restored only when its integrity seal is valid.")) return;
                    const result = await restorePlushBackup(payload);
                    appendLocalInfoBox("Backup restored", [
                        "Preferences, moods/history, favorites, layouts/themes, nicknames, and saved poses were restored.",
                        result.progressVerified
                            ? "Progress seal verified: stats, achievements, and relationships were restored."
                            : "Progress seal did not verify: stats, achievements, and relationships were left unchanged.",
                        result.battleRestored
                            ? `Battle stats/history restored for account #${result.currentMember}.`
                            : `Battle stats/history were not restored${result.backupBattleMember != null ? ` because this backup belongs to account #${result.backupBattleMember}` : " because the backup has no matching account battle data"}.`,
                    ]);
                } catch (e) {
                    appendLocalInfoBox("Backup restore failed", [String(e?.message || e)]);
                }
            });
            document.body.appendChild(input);
            backupImportInput = input;
        }
        backupImportInput.click();
        return true;
    }

    function getMoodStore() {
        if (moodState) return moodState;
        const stored = readLocalJSON(MOOD_STORAGE_KEY, {});
        moodState = stored && typeof stored === "object" ? stored : {};
        return moodState;
    }

    function clampMood(value) {
        return Math.max(MOOD_MIN_SCORE, Math.min(MOOD_MAX_SCORE, Math.round(Number(value) || 0)));
    }

    function moodLabel(score) {
        const numeric = clampMood(score);
        for (const entry of MOOD_LABELS) {
            if (numeric <= entry.maxScore) return entry.label;
        }
        return MOOD_LABELS.at?.(-1)?.label || "Adoring";
    }

    function isPlushNameEquippedLocally(name) {
        const wanted = normalizeLoreLookupKey(name);
        if (!wanted) return false;
        return getEquippedPlushItems(window.Player).some(item =>
            normalizeLoreLookupKey(plushNameForItem(item)) === wanted
        );
    }

    function getPlushMoodRecord(name = currentPlushName()) {
        const store = getMoodStore();
        const now = Date.now();
        let record = store[name];
        if (!record || typeof record !== "object") {
            record = { score: MOOD_DEFAULT_SCORE, interactions: 0, updatedAt: now, decayBaseScore: MOOD_DEFAULT_SCORE };
            store[name] = record;
            scheduleMoodStoreSave();
            return record;
        }

        record.score = clampMood(Number.isFinite(Number(record.score)) ? Number(record.score) : MOOD_DEFAULT_SCORE);
        record.interactions = Math.max(0, Math.floor(Number(record.interactions) || 0));
        if (!Number.isFinite(Number(record.decayBaseScore))) record.decayBaseScore = record.score;
        record.decayBaseScore = clampMood(record.decayBaseScore);
        const last = Number(record.updatedAt) || now;

        if (isPlushNameEquippedLocally(name)) {
            if (now - last >= MOOD_HELD_CLOCK_WRITE_MS) {
                record.updatedAt = now;
                store[name] = record;
                scheduleMoodStoreSave();
            }
            return record;
        }

        const steps = Math.floor(Math.max(0, now - last) / MOOD_DRIFT_EVERY_MS);
        if (steps > 0) {
            const beforeScore = record.score;
            if (record.score > MOOD_DRIFT_TARGET) {
                record.score = clampMood(Math.max(MOOD_DRIFT_TARGET, record.score - steps * MOOD_DRIFT_STEP));
            }
            record.updatedAt = last + steps * MOOD_DRIFT_EVERY_MS;
            store[name] = record;
            scheduleMoodStoreSave();
            const appliedDelta = record.score - beforeScore;
            if (appliedDelta) {
                lastMoodChange = { name, delta: appliedDelta, reason: "idle decay", score: record.score, at: new Date(now).toISOString() };
                emitPluginApiEvent("mood", { plushName: name, delta: appliedDelta, reason: "Idle decay", score: record.score });
            }
        }
        return record;
    }

    function roomMascotAffectionModifier(name, delta, reason = "interaction") {
        if (!(Number(delta) > 0)) return 0;
        if (String(reason || "").toLowerCase() === "room mascot") return 0;
        const mascotName = String(roomMascotState?.name || "");
        if (!mascotName || normalizeLoreLookupKey(mascotName) !== normalizeLoreLookupKey(name)) return 0;
        const shared = Number(roomMascotState?.affectionModifier);
        return Number.isFinite(shared) ? shared : ROOM_MASCOT_AFFECTION_MODIFIER;
    }

    function adjustCurrentPlushMood(delta, reason = "interaction") {
        if (!Number.isFinite(delta) || delta === 0) return getPlushMoodRecord();
        const name = currentPlushName();
        const store = getMoodStore();
        const record = getPlushMoodRecord(name);
        const beforeScore = Number(record.score) || 0;
        const mascotModifier = roomMascotAffectionModifier(name, delta, reason);
        const effectiveDelta = delta + mascotModifier;
        record.score = clampMood(record.score + effectiveDelta);
        record.interactions = Math.max(0, Math.floor(Number(record.interactions) || 0)) + 1;
        record.decayBaseScore = record.score;
        record.updatedAt = Date.now();
        store[name] = record;
        scheduleMoodStoreSave();
        lastMoodChange = { name, delta: effectiveDelta, baseDelta: delta, mascotModifier, reason, score: record.score, at: new Date().toISOString() };
        refreshPlushStatusIcon();
        emitPluginApiEvent("mood", { plushName: name, delta: effectiveDelta, baseDelta: delta, mascotModifier, reason: moodReasonLabel(reason), score: record.score });
        trackMoodAchievementTransition(name, beforeScore, record.score);
        return record;
    }

    function appendLocalInfoBox(title, lines, options = null) {
        const normalizedLines = Array.isArray(lines) ? lines.map(v => String(v)) : [String(lines ?? "")];
        log(title, ...normalizedLines);

        if (typeof window.ChatRoomAppendChat !== "function") return false;
        try {
            const row = document.createElement("div");
            row.className = "ChatMessage SubbysPlushiesLocalInfo";
            Object.assign(row.style, {
                boxSizing: "border-box",
                width: "calc(100% - 8px)",
                margin: options?.compact ? "2px 4px" : "6px 4px",
                padding: options?.compact ? "4px 6px" : "8px 10px",
                border: "1px solid currentColor",
                borderRadius: options?.compact ? "5px" : "8px",
                lineHeight: options?.compact ? "1.2" : "1.35",
                fontSize: "13px",
            });
            const heading = document.createElement("strong");
            heading.textContent = title;
            row.appendChild(heading);
            for (const line of normalizedLines) {
                const div = document.createElement("div");
                div.textContent = line;
                row.appendChild(div);
            }
            if (options?.fixedBattleText) applyBattleTextZoomCompensation(row);
            window.ChatRoomAppendChat(row);
            row.removeAttribute("data-time");
            row.removeAttribute("data-sender");
            return true;
        } catch (_) {
            return false;
        }
    }

    function getStatsStore() {
        if (!statsState) {
            const stored = readLocalJSON(STATS_STORAGE_KEY, {});
            statsState = {
                totalInteractions: Math.max(0, Number(stored.totalInteractions) || 0),
                actions: stored.actions && typeof stored.actions === "object" ? stored.actions : {},
                plushesUsed: stored.plushesUsed && typeof stored.plushesUsed === "object" ? stored.plushesUsed : {},
                speechBubbles: Math.max(0, Number(stored.speechBubbles) || 0),
                idleAnimations: Math.max(0, Number(stored.idleAnimations) || 0),
                mascotSets: Math.max(0, Number(stored.mascotSets) || 0),
                drags: Math.max(0, Number(stored.drags) || 0),
                offers: Math.max(0, Number(stored.offers) || 0),
                progress: stored.progress && typeof stored.progress === "object" ? stored.progress : {},
                achievements: stored.achievements && typeof stored.achievements === "object" ? stored.achievements : {},
            };
        }
        statsState.battles = getBattleStatsStore();
        return statsState;
    }

    function saveGeneralStatsStore() {
        const stats = getStatsStore();
        const portable = { ...stats };
        delete portable.battles;
        return writeLocalJSON(STATS_STORAGE_KEY, portable);
    }

    function flushMoodStoreSave() {
        if (moodStoreSaveTimer != null) { window.clearTimeout(moodStoreSaveTimer); moodStoreSaveTimer = null; }
        return moodState ? writeLocalJSON(MOOD_STORAGE_KEY, moodState) : true;
    }

    function scheduleMoodStoreSave(delayMs = 80) {
        if (moodStoreSaveTimer != null) return false;
        moodStoreSaveTimer = window.setTimeout(() => { moodStoreSaveTimer = null; if (moodState) writeLocalJSON(MOOD_STORAGE_KEY, moodState); }, Math.max(0, Number(delayMs) || 0));
        return true;
    }

    function flushRelationshipStoreSave() {
        if (relationshipStoreSaveTimer != null) { window.clearTimeout(relationshipStoreSaveTimer); relationshipStoreSaveTimer = null; }
        return relationshipState ? writeLocalJSON(RELATIONSHIP_STORAGE_KEY, relationshipState) : true;
    }

    function scheduleRelationshipStoreSave(delayMs = 80) {
        if (relationshipStoreSaveTimer != null) return false;
        relationshipStoreSaveTimer = window.setTimeout(() => { relationshipStoreSaveTimer = null; if (relationshipState) writeLocalJSON(RELATIONSHIP_STORAGE_KEY, relationshipState); }, Math.max(0, Number(delayMs) || 0));
        return true;
    }

    function flushGeneralStatsSave() {
        if (generalStatsSaveTimer != null) {
            window.clearTimeout(generalStatsSaveTimer);
            generalStatsSaveTimer = null;
        }
        return saveGeneralStatsStore();
    }

    function scheduleGeneralStatsSave(delayMs = 80) {
        if (generalStatsSaveTimer != null) return false;
        generalStatsSaveTimer = window.setTimeout(() => {
            generalStatsSaveTimer = null;
            saveGeneralStatsStore();
        }, Math.max(0, Number(delayMs) || 0));
        return true;
    }

    function scheduleAchievementCheck(showNew = true, delayMs = 25) {
        achievementCheckShowNew = achievementCheckShowNew || !!showNew;
        if (achievementCheckTimer != null) return false;
        achievementCheckTimer = window.setTimeout(() => {
            achievementCheckTimer = null;
            const notify = achievementCheckShowNew;
            achievementCheckShowNew = false;
            checkAchievements(notify);
        }, Math.max(0, Number(delayMs) || 0));
        return true;
    }

    function queueStatsAchievementFlush(showNew = true) {
        scheduleGeneralStatsSave();
        scheduleAchievementCheck(showNew);
        return true;
    }

    function cancelPendingStatsWork() {
        if (generalStatsSaveTimer != null) window.clearTimeout(generalStatsSaveTimer);
        if (moodStoreSaveTimer != null) window.clearTimeout(moodStoreSaveTimer);
        if (relationshipStoreSaveTimer != null) window.clearTimeout(relationshipStoreSaveTimer);
        if (achievementCheckTimer != null) window.clearTimeout(achievementCheckTimer);
        generalStatsSaveTimer = null;
        moodStoreSaveTimer = null;
        relationshipStoreSaveTimer = null;
        achievementCheckTimer = null;
        achievementCheckShowNew = false;
    }

    function flushDeferredProgressStores() {
        flushMoodStoreSave();
        flushRelationshipStoreSave();
        flushGeneralStatsSave();
    }

    function cachedAchievementMetric(key, compute) {
        if (!(achievementMetricCache instanceof Map)) return compute();
        if (achievementMetricCache.has(key)) return achievementMetricCache.get(key);
        const value = compute();
        achievementMetricCache.set(key, value);
        return value;
    }

    function getAchievementProgress(stats = getStatsStore()) {
        if (!stats.progress || typeof stats.progress !== "object" || Array.isArray(stats.progress)) stats.progress = {};
        const p = stats.progress;
        for (const key of ["roomsVisited", "playersInteracted", "interactionDays", "bonkedPlushies", "pendingForgiveness"]) {
            if (!p[key] || typeof p[key] !== "object" || Array.isArray(p[key])) p[key] = {};
        }
        for (const key of [
            "baseCuddleSubbycat", "professionalPlushieWrangler", "actuallyThisOne", "plushieHoarder", "doubleTrouble",
            "plushieTherapist", "committed", "forgiven", "personalSpace", "overprotective", "roomCelebrity",
            "successfulOffers", "bestBattleWinStreak", "currentBattleWinStreak", "photoFinishWins", "tinyPlushie", "absoluteUnit",
            "fashionablyEarly", "royalAudience", "protectTriggers", "balanceBestSeconds"
        ]) p[key] = Math.max(0, Number(p[key]) || 0);
        return p;
    }

    function progressMetric(stats, key) {
        return Math.max(0, Number(getAchievementProgress(stats)?.[key]) || 0);
    }

    function objectKeyCount(value) {
        return value && typeof value === "object" ? Object.keys(value).length : 0;
    }

    function allAvailablePlushNames() {
        if (allAvailablePlushNamesCache) return allAvailablePlushNamesCache;
        const names = [];
        const seen = new Set();
        for (let option = 0; option < PUBLIC_PLUSH_COUNT; option++) {
            const name = publicPlushName(option);
            const key = normalizeLoreLookupKey(name);
            if (name && key && !seen.has(key)) { seen.add(key); names.push(name); }
        }
        allAvailablePlushNamesCache = Object.freeze(names);
        return allAvailablePlushNamesCache;
    }

    function relationshipRank(name) {
        return Math.max(0, RELATIONSHIP_LEVELS.findIndex(entry => entry.name === name));
    }

    function countPlushiesAtRelationship(levelName) {
        return cachedAchievementMetric(`relationship:${levelName}`, () => {
            const wanted = relationshipRank(levelName);
            const store = getRelationshipStore();
            let count = 0;
            for (const name of allAvailablePlushNames()) {
                const interactions = Math.max(0, Number(store?.[name]?.interactions) || 0);
                if (relationshipRank(relationshipLevelForInteractions(interactions).name) >= wanted) count++;
            }
            return count;
        });
    }

    function allAvailablePlushiesAtRelationship(levelName) {
        const names = allAvailablePlushNames();
        return names.length > 0 && countPlushiesAtRelationship(levelName) >= names.length;
    }

    function maxPlushMoodScore() {
        return cachedAchievementMetric("maxMoodScore", () => {
            const store = getMoodStore();
            let best = MOOD_DEFAULT_SCORE;
            for (const name of allAvailablePlushNames()) {
                const raw = Number(store?.[name]?.score);
                best = Math.max(best, Number.isFinite(raw) ? clampMood(raw) : MOOD_DEFAULT_SCORE);
            }
            return best;
        });
    }

    function interactionDayDifference(previousDay, nextDay) {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(String(previousDay || "")) || !/^\d{4}-\d{2}-\d{2}$/.test(String(nextDay || ""))) return null;
        const previous = Date.parse(`${previousDay}T00:00:00Z`);
        const next = Date.parse(`${nextDay}T00:00:00Z`);
        if (!Number.isFinite(previous) || !Number.isFinite(next)) return null;
        return Math.round((next - previous) / 86400000);
    }

    function interactionDayRecord(value) {
        if (!value || typeof value !== "object" || Array.isArray(value)) {
            return { count: 0, lastDay: "", currentStreak: 0, longestStreak: 0 };
        }

        const count = Math.max(0, Math.floor(Number(value.count) || 0));
        const lastDay = /^\d{4}-\d{2}-\d{2}$/.test(String(value.lastDay || ""))
            ? String(value.lastDay)
            : "";
        const currentStreak = Math.max(0, Math.floor(Number(value.currentStreak) || 0));
        const longestStreak = Math.max(currentStreak, Math.floor(Number(value.longestStreak) || 0));

        return { count, lastDay, currentStreak, longestStreak };
    }

    function maxInteractionDaysForOnePlush(stats = getStatsStore()) {
        return cachedAchievementMetric("maxInteractionDays", () => {
            const days = getAchievementProgress(stats).interactionDays;
            let best = 0;
            for (const entry of Object.values(days)) best = Math.max(best, interactionDayRecord(entry).count);
            return best;
        });
    }

    function maxInteractionStreakForOnePlush(stats = getStatsStore()) {
        return cachedAchievementMetric("maxInteractionStreak", () => {
            const days = getAchievementProgress(stats).interactionDays;
            let best = 0;
            for (const entry of Object.values(days)) best = Math.max(best, interactionDayRecord(entry).longestStreak);
            return best;
        });
    }

    function markProgress(key, value = 1, { mode = "max", check = true } = {}) {
        const stats = getStatsStore();
        const p = getAchievementProgress(stats);
        const numeric = Math.max(0, Number(value) || 0);
        const before = Math.max(0, Number(p[key]) || 0);
        const next = mode === "add" ? before + numeric : mode === "set" ? numeric : Math.max(before, numeric);
        if (next === before) return before;
        p[key] = next;
        scheduleGeneralStatsSave();
        if (check) scheduleAchievementCheck(true);
        return next;
    }

    function currentAchievementInteractionItem() {
        const selected = getDragTargetItem();
        if (isOurs(selected)) return selected;
        return getHeld(window.Player);
    }

    function trackDualEquippedAchievement() {
        const hand = getInventoryItem(window.Player, GROUP);
        const addon = getInventoryItem(window.Player, ADDON_GROUP);
        if (isOurs(hand) && isOurs(addon)) markProgress("plushieHoarder", 1);
    }

    function trackSelectionAchievements(name, groupName = null) {
        const now = Date.now();
        const normalizedName = String(name || "Plushie");
        achievementSession.selectedPlushes.add(normalizedName);
        if (achievementSession.selectedPlushes.size >= 10) markProgress("professionalPlushieWrangler", 1);
        achievementSession.selectionHistory.push({ name: normalizedName, at: now });
        achievementSession.selectionHistory = achievementSession.selectionHistory.filter(entry => now - entry.at <= 120000).slice(-32);
        const same = achievementSession.selectionHistory.filter(entry => normalizeLoreLookupKey(entry.name) === normalizeLoreLookupKey(normalizedName));
        if (same.length >= 5) markProgress("actuallyThisOne", 1);
        if (groupName && PLUSH_GROUPS.includes(groupName)) achievementSession.equipSinceByGroup.set(groupName, { name: normalizedName, at: now });
        trackDualEquippedAchievement();
    }

    const PERSONAL_SPACE_ACTIONS = Object.freeze(["rubFace", "noseBoop", "foreheadBump", "cheekRest"]);
    const PERSONAL_SPACE_ACTION_SET = new Set(PERSONAL_SPACE_ACTIONS);

    function trackInteractionAchievements(actionKey, plushName) {
        const stats = getStatsStore();
        const p = getAchievementProgress(stats);
        const today = new Date().toISOString().slice(0, 10);
        const storedDayRecord = p.interactionDays[plushName];
        const dayRecord = interactionDayRecord(storedDayRecord);
        if (dayRecord.lastDay !== today) {
            const dayDifference = interactionDayDifference(dayRecord.lastDay, today);
            dayRecord.count += 1;
            dayRecord.currentStreak = dayDifference === 1 ? Math.max(1, dayRecord.currentStreak + 1) : 1;
            dayRecord.longestStreak = Math.max(dayRecord.longestStreak, dayRecord.currentStreak);
            dayRecord.lastDay = today;
            p.interactionDays[plushName] = dayRecord;
        }
        if (actionKey === "bonk") {
            p.bonkedPlushies[plushName] = 1;
            p.pendingForgiveness[plushName] = 1;
        }
        if (PERSONAL_SPACE_ACTION_SET.has(actionKey)) {
            let seen = achievementSession.personalSpaceByPlush.get(plushName);
            if (!seen) { seen = new Set(); achievementSession.personalSpaceByPlush.set(plushName, seen); }
            seen.add(actionKey);
            if (!p.personalSpace && PERSONAL_SPACE_ACTIONS.every(key => seen.has(key))) p.personalSpace = 1;
        }
        const item = currentAchievementInteractionItem();
        const group = item?.Asset?.Group?.Name;
        if (isOurs(item) && PLUSH_GROUPS.includes(group)) {
            const now = Date.now();
            achievementSession.interactionByGroup.set(group, { at: now, name: plushNameForItem(item) });
            const hand = achievementSession.interactionByGroup.get(GROUP);
            const addon = achievementSession.interactionByGroup.get(ADDON_GROUP);
            if (!p.doubleTrouble && hand && addon && now - hand.at <= 30000 && now - addon.at <= 30000 && normalizeLoreLookupKey(hand.name) !== normalizeLoreLookupKey(addon.name)) p.doubleTrouble = 1;
        }
    }

    function trackMoodAchievementTransition(plushName, beforeScore, afterScore) {
        const stats = getStatsStore();
        const p = getAchievementProgress(stats);
        let changed = false;
        if (beforeScore <= 18 || afterScore <= 18) achievementSession.grumpySeen.add(plushName);
        if (!p.plushieTherapist && achievementSession.grumpySeen.has(plushName) && afterScore >= 93) { p.plushieTherapist = 1; changed = true; }
        if (p.pendingForgiveness?.[plushName] && afterScore >= 93) {
            p.forgiven = 1;
            delete p.pendingForgiveness[plushName];
            changed = true;
        }
        if (changed) scheduleGeneralStatsSave();
        if (changed || (beforeScore < 100 && afterScore >= 100)) scheduleAchievementCheck(true);
    }

    function trackCommittedAchievement() {
        const now = Date.now();
        for (const groupName of PLUSH_GROUPS) {
            const item = getInventoryItem(window.Player, groupName);
            if (!isOurs(item)) { achievementSession.equipSinceByGroup.delete(groupName); continue; }
            const name = plushNameForItem(item);
            const current = achievementSession.equipSinceByGroup.get(groupName);
            if (!current || normalizeLoreLookupKey(current.name) !== normalizeLoreLookupKey(name)) {
                achievementSession.equipSinceByGroup.set(groupName, { name, at: now });
                continue;
            }
            if (now - current.at >= 8 * 60 * 60 * 1000) markProgress("committed", 1);
        }
    }

    function roomAchievementKey() {
        const name = currentChatRoomName();
        return name ? name.toLowerCase().replace(/\s+/g, " ").trim() : "";
    }

    function trackRoomAchievements() {
        if (window.CurrentScreen !== "ChatRoom") return false;
        const stats = getStatsStore();
        const p = getAchievementProgress(stats);
        let changed = false;
        const room = roomAchievementKey();
        if (room && !p.roomsVisited[room]) { p.roomsVisited[room] = 1; changed = true; }
        const queenPresent = cuddleQueenEncounterValue() >= 1 && Number(window.Player?.MemberNumber) !== CUDDLE_QUEEN_MEMBER_NUMBER;
        if (cuddleRoomJoinedValue()) {
            if (!queenPresent && !p.fashionablyEarly) { p.fashionablyEarly = 1; changed = true; }
            const held = getHeld(window.Player);
            if (!p.royalAudience && queenPresent && isOurs(held) && relationshipRank(relationshipStatus(plushNameForItem(held)).level) >= relationshipRank("Bonded")) { p.royalAudience = 1; changed = true; }
        }
        if (!p.roomCelebrity && roomMascotState?.name && getEquippedPlushItems(window.Player).some(item => normalizeLoreLookupKey(plushNameForItem(item)) === normalizeLoreLookupKey(roomMascotState.name))) { p.roomCelebrity = 1; changed = true; }
        if (changed) scheduleGeneralStatsSave();
        scheduleAchievementCheck(true);
        return true;
    }

    function trackSocialPlayer(memberNumber) {
        const member = Number(memberNumber);
        if (!Number.isFinite(member) || member === Number(window.Player?.MemberNumber)) return false;
        const stats = getStatsStore();
        const players = getAchievementProgress(stats).playersInteracted;
        const key = String(member);
        if (players[key]) return false;
        players[key] = 1;
        queueStatsAchievementFlush(true);
        return true;
    }

    function trackProtectAchievement() {
        achievementSession.protectCountInRoom++;
        const stats = getStatsStore();
        const p = getAchievementProgress(stats);
        p.protectTriggers = Math.max(0, Number(p.protectTriggers) || 0) + 1;
        if (achievementSession.protectCountInRoom >= 5) p.overprotective = 1;
        queueStatsAchievementFlush(true);
    }

    function trackBattleAchievement(result, ownScore, opponentScore) {
        const stats = getStatsStore();
        const p = getAchievementProgress(stats);
        if (result === "win") {
            p.currentBattleWinStreak = Math.max(0, Number(p.currentBattleWinStreak) || 0) + 1;
            p.bestBattleWinStreak = Math.max(Number(p.bestBattleWinStreak) || 0, p.currentBattleWinStreak);
            if (Math.abs(Number(ownScore) - Number(opponentScore)) === 1) p.photoFinishWins = Math.max(0, Number(p.photoFinishWins) || 0) + 1;
        } else {
            p.currentBattleWinStreak = 0;
        }
        queueStatsAchievementFlush(true);
    }

    function trackResizeAchievement(item, transform) {
        if (!isOurs(item) || item !== getInventoryItem(window.Player, item?.Asset?.Group?.Name)) return false;
        const p = getAchievementProgress();
        if (p.tinyPlushie && p.absoluteUnit) return true;
        const sx = Math.abs(Number(transform?.ScaleX));
        const sy = Math.abs(Number(transform?.ScaleY));
        if (Number.isFinite(sx) && Number.isFinite(sy)) {
            const minScale = Math.min(sx, sy), maxScale = Math.max(sx, sy);
            if (!p.tinyPlushie && minScale <= 0.35) markProgress("tinyPlushie", 1);
            if (!p.absoluteUnit && maxScale >= 2) markProgress("absoluteUnit", 1);
        }
        return true;
    }

    function actionLooksLikeBaseCuddle(data) {
        if (!isChatAction(data)) return false;
        const strings = [data.Content, data.Name, data.ActivityName, data.Activity?.Name, data.Activity?.ActivityName];
        if (Array.isArray(data.Dictionary)) {
            for (const entry of data.Dictionary.slice(0, 32)) {
                if (typeof entry?.Tag === "string") strings.push(entry.Tag);
                if (typeof entry?.Text === "string") strings.push(entry.Text);
            }
        }
        return strings.some(value => typeof value === "string" && /(^|[^a-z])cuddle([^a-z]|$)/i.test(value) && !/SubbysPlushiesCuddle/i.test(value));
    }

    function maybeTrackBaseCuddleAchievement(data) {
        if (getStatsStore().achievements?.royal_cuddle) return false;
        if (!actionLooksLikeBaseCuddle(data)) return false;
        const context = getActionCharacterContext(data);
        const playerMember = Number(window.Player?.MemberNumber);
        const sourceIsPlayer = Number(data?.Sender) === playerMember || context.sourceMember === playerMember;
        const targetIsQueen = context.targetMember === CUDDLE_QUEEN_MEMBER_NUMBER;
        if (!sourceIsPlayer || !targetIsQueen) return false;
        markProgress("baseCuddleSubbycat", 1);
        return true;
    }

    function browserZoomEstimate() {
        const outer = Number(window.outerWidth), inner = Number(window.innerWidth);
        if (Number.isFinite(outer) && Number.isFinite(inner) && inner > 0) {
            const ratio = outer / inner;
            if (ratio >= 0.55 && ratio <= 3) return Math.abs(ratio - 1) < 0.08 ? 1 : ratio;
        }
        return 1;
    }

    function applyBattleTextZoomCompensation(row) {
        if (!row?.style) return row;
        const zoom = browserZoomEstimate();
        row.style.fontSize = `${Math.max(8, Math.min(18, 13 / zoom))}px`;
        row.style.lineHeight = "1.25";
        row.dataset.subbysPlushiesFixedBattleText = "true";
        return row;
    }

    function statAffectionCount(stats = getStatsStore()) {
        return AFFECTION_ACTION_KEYS.reduce((sum, key) => sum + (Number(stats.actions?.[key]) || 0), 0);
    }

    function checkAchievements(showNew = true) {
        const stats = getStatsStore();
        const unlocked = [];
        achievementMetricCache = new Map();
        try {
            for (const achievement of ACHIEVEMENTS) {
                if (stats.achievements[achievement.id]) continue;
                let passed = false;
                try { passed = !!achievement.test(stats); } catch (_) {}
                if (!passed) continue;
                stats.achievements[achievement.id] = Date.now();
                unlocked.push(achievement);
            }
        } finally {
            achievementMetricCache = null;
        }
        if (unlocked.length) {
            flushGeneralStatsSave();
            if (showNew) {
                for (const achievement of unlocked) {
                    appendLocalInfoBox(`Achievement unlocked: ${achievement.name}`, [achievement.description]);
                }
            }
        }
        return unlocked;
    }

    function recordStat(kind, amount = 1, detail = null) {
        const stats = getStatsStore();
        const value = Math.max(0, Number(amount) || 0);
        if (!value) return stats;
        if (kind === "interaction") {
            stats.totalInteractions += value;
            const key = String(detail?.action || "other");
            stats.actions[key] = (Number(stats.actions[key]) || 0) + value;
        } else if (kind === "speech") stats.speechBubbles += value;
        else if (kind === "idle") stats.idleAnimations += value;
        else if (kind === "mascot") stats.mascotSets += value;
        else if (kind === "drag") stats.drags += value;
        else if (kind === "offer") stats.offers += value;
        else if (kind === "battlePlayed") stats.battles.played += value;
        else if (kind === "battleWin") stats.battles.wins += value;
        else if (kind === "battleLoss") stats.battles.losses += value;
        else if (kind === "battleDraw") stats.battles.draws += value;
        const plushName = detail?.plushName || currentPlushName();
        if (plushName) stats.plushesUsed[plushName] = (Number(stats.plushesUsed[plushName]) || 0) + (kind === "select" ? value : 0);
        if (kind.startsWith("battle")) saveBattleStatsStore();
        else scheduleGeneralStatsSave();
        scheduleAchievementCheck(true);
        return stats;
    }

    function recordPlushSelection(name = currentPlushName(), groupName = null) {
        const stats = getStatsStore();
        stats.plushesUsed[name] = (Number(stats.plushesUsed[name]) || 0) + 1;
        trackSelectionAchievements(name, groupName);
        queueStatsAchievementFlush(true);
    }

    function showStats() {
        const s = getStatsStore();
        appendLocalInfoBox("Plushie stats", [
            `Interactions: ${s.totalInteractions} • affectionate: ${statAffectionCount(s)}`,
            `Battles: ${s.battles.played} • wins ${s.battles.wins} • losses ${s.battles.losses} • draws ${s.battles.draws}`,
            `Speech bubbles: ${s.speechBubbles} • idle wiggles: ${s.idleAnimations} • drags: ${s.drags}`,
            `Offers started: ${s.offers} • successful offers: ${progressMetric(s, "successfulOffers")} • room mascots set: ${s.mascotSets}`,
            `Different plushies used: ${Object.keys(s.plushesUsed).length} • rooms: ${objectKeyCount(getAchievementProgress(s).roomsVisited)} • players: ${objectKeyCount(getAchievementProgress(s).playersInteracted)}`,
            `Best battle win streak: ${progressMetric(s, "bestBattleWinStreak")} • longest plushie streak: ${maxInteractionStreakForOnePlush(s)} days • best balance: ${progressMetric(s, "balanceBestSeconds")}s`,
        ]);
        return { ...s };
    }

    function showAchievements() {
        const stats = getStatsStore();
        checkAchievements(false);
        const lines = ACHIEVEMENTS.map(a => {
            const unlocked = !!stats.achievements[a.id];
            if (a.hidden && !unlocked) return "○ ??? — Hidden achievement";
            return `${unlocked ? "✓" : "○"} ${a.name} — ${a.description}`;
        });
        appendLocalInfoBox(`Achievements (${Object.keys(stats.achievements).length}/${ACHIEVEMENTS.length})`, lines);
        return ACHIEVEMENTS.map(a => ({ ...a, unlocked: !!stats.achievements[a.id] }));
    }

    function randomPlushSpeech() {
        const score = getPlushMoodRecord().score;
        const bucket = score <= 38 ? PLUSH_SPEECH.grumpy : score <= 65 ? PLUSH_SPEECH.calm : score <= 92 ? PLUSH_SPEECH.happy : PLUSH_SPEECH.adoring;
        const moodLines = Array.isArray(bucket) && bucket.length ? bucket : ["Hi!"];
        const relationship = relationshipStatus();
        const relationshipLines = RELATIONSHIP_SPEECH?.[relationship.level];
        if (Array.isArray(relationshipLines) && relationshipLines.length && Math.random() < 0.28) {
            return relationshipLines[Math.floor(Math.random() * relationshipLines.length)] || moodLines[0] || "Hi!";
        }
        return moodLines[Math.floor(Math.random() * moodLines.length)] || "Hi!";
    }

    function removeSpeechBubble() {
        if (speechBubbleTimer != null) window.clearTimeout(speechBubbleTimer);
        speechBubbleTimer = null;
        try { speechBubbleElement?.remove?.(); } catch (_) {}
        speechBubbleElement = null;
        speechBubbleGroupName = null;
        localOverlayPositionSignature = null;
    }

    function characterChatRoomDraw(C) {
        if (!C) return null;
        const playerMember = Number(window.Player?.MemberNumber);
        const member = Number(C?.MemberNumber);
        if (C === window.Player || (Number.isFinite(playerMember) && member === playerMember)) return lastPlayerChatRoomDraw;
        return Number.isFinite(member) ? lastCharacterChatRoomDraw.get(member) || null : null;
    }

    function currentCanvasTransformSnapshot() {
        const ctx = window.MainCanvas;
        if (!ctx || typeof ctx.getTransform !== "function") return null;
        try {
            const matrix = ctx.getTransform();
            const values = [matrix?.a, matrix?.b, matrix?.c, matrix?.d, matrix?.e, matrix?.f].map(Number);
            if (!values.every(Number.isFinite)) return null;
            return { a: values[0], b: values[1], c: values[2], d: values[3], e: values[4], f: values[5] };
        } catch (_) {
            return null;
        }
    }

    function applyDrawMatrix(draw, x, y) {
        const matrix = draw?.matrix;
        if (!matrix) return { x, y };
        return {
            x: matrix.a * x + matrix.c * y + matrix.e,
            y: matrix.b * x + matrix.d * y + matrix.f,
        };
    }

    function invertDrawMatrix(draw, x, y) {
        const matrix = draw?.matrix;
        if (!matrix) return { x, y };
        const det = matrix.a * matrix.d - matrix.b * matrix.c;
        if (!Number.isFinite(det) || Math.abs(det) < 1e-8) return null;
        const px = x - matrix.e;
        const py = y - matrix.f;
        return {
            x: (matrix.d * px - matrix.c * py) / det,
            y: (-matrix.b * px + matrix.a * py) / det,
        };
    }

    function characterDrawMetrics(C, draw) {
        if (!draw || !Number.isFinite(draw.x) || !Number.isFinite(draw.y) || !Number.isFinite(draw.zoom)) return null;
        let heightRatio = Number(C?.HeightRatio);
        if (!Number.isFinite(heightRatio) || heightRatio <= 0) heightRatio = 1;

        let xOffset = 0;
        let yOffset = 0;
        try {
            if (typeof CharacterAppearanceXOffset === "function") xOffset = Number(CharacterAppearanceXOffset(C, heightRatio)) || 0;
            else xOffset = 500 * (1 - heightRatio) / 2;
        } catch (_) {
            xOffset = 500 * (1 - heightRatio) / 2;
        }
        try {
            if (typeof CharacterAppearanceYOffset === "function") {
                yOffset = Number(CharacterAppearanceYOffset(C, heightRatio)) || 0;
            } else {
                const proportion = Number.isFinite(Number(C?.HeightRatioProportion)) ? Number(C.HeightRatioProportion) : 1;
                const modifier = Number(C?.HeightModifier) || 0;
                yOffset = 1000 * (1 - heightRatio) * proportion - modifier * heightRatio;
            }
        } catch (_) {
            yOffset = 0;
        }

        const scale = draw.zoom * heightRatio;
        if (!Number.isFinite(scale) || Math.abs(scale) < 1e-8) return null;
        return { heightRatio, xOffset, yOffset, scale };
    }

    function characterPointToMainCanvas(C, characterX, characterY) {
        const draw = characterChatRoomDraw(C);
        let mainX = Number(characterX);
        let mainY = Number(characterY);
        if (!Number.isFinite(mainX) || !Number.isFinite(mainY)) return null;
        const metrics = characterDrawMetrics(C, draw);
        if (metrics) {
            mainX = draw.x + draw.zoom * metrics.xOffset + mainX * metrics.scale;
            mainY = draw.y + draw.zoom * metrics.yOffset + mainY * metrics.scale;
        }
        const transformed = applyDrawMatrix(draw, mainX, mainY);
        if (!Number.isFinite(transformed.x) || !Number.isFinite(transformed.y)) return null;
        return transformed;
    }

    function characterPointToScreen(C, characterX, characterY) {
        const canvas = document.getElementById("MainCanvas") || document.querySelector("canvas");
        const rect = canvas?.getBoundingClientRect?.();
        if (!canvas || !rect || rect.width <= 0 || rect.height <= 0) return null;
        const logicalWidth = Number(canvas.width) || 2000;
        const logicalHeight = Number(canvas.height) || 1000;
        const point = characterPointToMainCanvas(C, characterX, characterY);
        if (!point) return null;
        return {
            x: rect.left + (point.x / logicalWidth) * rect.width,
            y: rect.top + (point.y / logicalHeight) * rect.height,
        };
    }

    function characterCanvasCoordinates(C, event) {
        const canvas = document.getElementById("MainCanvas") || document.querySelector("canvas");
        if (!canvas || event?.target !== canvas) return null;
        const rect = canvas.getBoundingClientRect?.();
        if (!rect || rect.width <= 0 || rect.height <= 0) return null;
        const logicalWidth = Number(canvas.width) || 2000;
        const logicalHeight = Number(canvas.height) || 1000;
        const mainX = (event.clientX - rect.left) * logicalWidth / rect.width;
        const mainY = (event.clientY - rect.top) * logicalHeight / rect.height;

        const draw = characterChatRoomDraw(C);
        const untransformed = invertDrawMatrix(draw, mainX, mainY);
        if (!untransformed) return null;
        const metrics = characterDrawMetrics(C, draw);
        if (!metrics) return { canvas, x: untransformed.x, y: untransformed.y, mainX, mainY };
        return {
            canvas,
            x: (untransformed.x - draw.x - draw.zoom * metrics.xOffset) / metrics.scale,
            y: (untransformed.y - draw.y - draw.zoom * metrics.yOffset) / metrics.scale,
            mainX,
            mainY,
        };
    }

    function petSuitOverlayKey(C) {
        const member = Number(C?.MemberNumber);
        if (Number.isFinite(member)) return `member:${member}`;
        if (C === window.Player) return "player";
        return `character:${String(C?.ID ?? C?.Name ?? "unknown")}`;
    }

    function characterPetSuitItem(C) {
        const appearance = Array.isArray(C?.Appearance) ? C.Appearance : [];
        return appearance.find(item => item?.Asset?.Group?.Name === "ItemArms") || null;
    }

    function clearPetSuitPlushOverlays() {
        petSuitRenderStates.clear();
        manualPlushMainBounds.clear();
    }

    function schedulePetSuitNativeRestore(C, key) {
        const state = petSuitRenderStates.get(key) || {};
        if (state.restorePending) return false;
        state.restorePending = true;
        state.character = C;
        petSuitRenderStates.set(key, state);
        window.setTimeout(() => {
            const current = petSuitRenderStates.get(key);
            if (current) current.restorePending = false;
            if (window.CurrentScreen !== "ChatRoom" || characterPetSuitItem(C)) return;
            const item = getHandheldItem(C);
            if (!isOurs(item)) return;
            try {
                if (typeof CharacterLoadCanvas === "function") CharacterLoadCanvas(C);
                else if (typeof CharacterRefresh === "function") CharacterRefresh(C);
            } catch (e) {
                warn("Could not restore plush render after restraint pose ended:", e);
            }
            if (C === window.Player) scheduleLocalOverlayReposition();
        }, 0);
        return true;
    }

    function petSuitPlushOverlaySource(item) {
        if (!isOurs(item)) return null;
        const option = canonicalWirePlushOption(getItemPlushOption(item));
        if (!validPlushOption(option)) return null;
        return uiPlushImageSource(option) || null;
    }

    function syncPetSuitPlushOverlay(C) {
        if (!C) return false;
        const key = petSuitOverlayKey(C);
        const item = getHandheldItem(C);
        const previous = petSuitRenderStates.get(key);
        if (!isOurs(item)) {
            if (previous?.active) previous.active = false;
            return false;
        }
        const suitActive = !!characterPetSuitItem(C);
        const renderState = previous || { active: false, restorePending: false };
        const wasActive = !!renderState.active;
        renderState.active = suitActive;
        renderState.character = C;
        renderState.group = GROUP;
        renderState.option = canonicalWirePlushOption(getItemPlushOption(item));
        renderState.lastSeenAt = Date.now();
        petSuitRenderStates.set(key, renderState);
        if (window.CurrentScreen === "ChatRoom" && wasActive && !suitActive) schedulePetSuitNativeRestore(C, key);
        return window.CurrentScreen === "ChatRoom" && suitActive;
    }

    function getCanvasOverlayImage(source, onReady = null) {
        if (typeof source !== "string" || !source) return null;
        try {
            if (typeof window.DrawGetImage === "function") {
                const image = window.DrawGetImage(source);
                if (image?.complete && (Number(image.naturalWidth) > 0 || Number(image.width) > 0)) return image;
            }
        } catch (_) {}
        let image = canvasOverlayImageCache.get(source);
        if (!image) {
            image = new Image();
            canvasOverlayImageCache.set(source, image);
            image.src = source;
        }
        const ready = image.complete && (Number(image.naturalWidth) > 0 || Number(image.width) > 0);
        if (!ready && typeof onReady === "function" && !image.__SubbysPlushiesReadyHooked) {
            image.__SubbysPlushiesReadyHooked = true;
            image.addEventListener("load", () => {
                image.__SubbysPlushiesReadyHooked = false;
                try { onReady(); } catch (_) {}
            }, { once: true });
        }
        return ready ? image : null;
    }

    function drawPetSuitPlushCanvasOverlay(C) {
        if (!syncPetSuitPlushOverlay(C)) return false;
        const item = getHandheldItem(C);
        const source = petSuitPlushOverlaySource(item);
        const image = getCanvasOverlayImage(source, () => {
            if (window.CurrentScreen === "ChatRoom" && characterPetSuitItem(C) && isOurs(getHandheldItem(C))) {
                rebuildCharacterCanvas(C, "arm-restraint handheld plush overlay ready");
            }
        });
        const transform = readActivePlushLayerTransform(item);
        const ctx = window.MainCanvas;
        if (!image || !transform || !ctx || typeof ctx.drawImage !== "function") return false;
        const scaleX = Number(transform.ScaleX) || 1;
        const scaleY = Number(transform.ScaleY) || 1;
        const halfWidth = PLUSH_RENDER.Width * Math.max(0.05, Math.abs(scaleX)) / 2;
        const halfHeight = PLUSH_RENDER.Height * Math.max(0.05, Math.abs(scaleY)) / 2;
        const centerX = PLUSH_RENDER.Left + PLUSH_RENDER.Width / 2;
        const centerY = PLUSH_RENDER.Top + PLUSH_RENDER.Height / 2;
        const rotation = (Number(transform.Rotation) || 0) * Math.PI / 180;
        const center = characterPointToMainCanvas(C, centerX, centerY);
        const xPoint = characterPointToMainCanvas(C, centerX + Math.cos(rotation) * halfWidth, centerY + Math.sin(rotation) * halfWidth);
        const yPoint = characterPointToMainCanvas(C, centerX - Math.sin(rotation) * halfHeight, centerY + Math.cos(rotation) * halfHeight);
        const translation = layerTranslationMainCanvasDelta(
            C,
            centerX,
            centerY,
            Number(transform.TranslationX) || 0,
            Number(transform.TranslationY) || 0
        );
        if (!center || !xPoint || !yPoint || !translation) return false;
        center.x += translation.x;
        center.y += translation.y;
        xPoint.x += translation.x;
        xPoint.y += translation.y;
        yPoint.x += translation.x;
        yPoint.y += translation.y;
        const xVec = { x: xPoint.x - center.x, y: xPoint.y - center.y };
        const yVec = { x: yPoint.x - center.x, y: yPoint.y - center.y };

        storeManualPlushMainBounds(C, item, center, xVec, yVec);

        const width = Math.max(8, Math.hypot(xVec.x, xVec.y) * 2);
        const height = Math.max(8, Math.hypot(yVec.x, yVec.y) * 2);
        const angle = Math.atan2(xVec.y, xVec.x);
        try {
            ctx.save();
            if (typeof ctx.setTransform === "function") ctx.setTransform(1, 0, 0, 1, 0, 0);
            ctx.translate(center.x, center.y);
            ctx.rotate(angle);
            ctx.scale(scaleX < 0 ? -1 : 1, scaleY < 0 ? -1 : 1);
            ctx.drawImage(image, -width / 2, -height / 2, width, height);
            ctx.restore();
            return true;
        } catch (_) {
            try { ctx.restore(); } catch (_) {}
            return false;
        }
    }

    function prunePetSuitPlushOverlays() {
        const present = new Set();
        if (window.CurrentScreen === "ChatRoom") {
            const characters = Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [];
            for (const C of characters) present.add(petSuitOverlayKey(C));
            if (window.Player && !characters.includes(window.Player)) present.add(petSuitOverlayKey(window.Player));
        }
        for (const key of [...petSuitRenderStates.keys()]) {
            if (!present.has(key)) petSuitRenderStates.delete(key);
        }
    }

    function startPetSuitOverlaySweep() {
        return true;
    }

    function playerCharacterPointToScreen(characterX, characterY) {
        return characterPointToScreen(window.Player, characterX, characterY);
    }

    function plushOverlayPositionSignature(C, item) {
        if (!C || !isOurs(item)) return "";
        const draw = characterChatRoomDraw(C);
        const transform = readActivePlushLayerTransform(item);
        if (!transform) return "";
        return [
            draw?.x ?? "", draw?.y ?? "", draw?.zoom ?? "", Number(C?.HeightRatio) || 1,
            draw?.matrix?.a ?? "", draw?.matrix?.b ?? "", draw?.matrix?.c ?? "", draw?.matrix?.d ?? "", draw?.matrix?.e ?? "", draw?.matrix?.f ?? "",
            transform.TranslationX, transform.TranslationY, transform.ScaleX, transform.ScaleY, transform.Rotation,
        ].join("|");
    }

    function mainCanvasCssScale() {
        const canvas = document.getElementById("MainCanvas") || document.querySelector("canvas");
        const rect = canvas?.getBoundingClientRect?.();
        if (!canvas || !rect || rect.width <= 0 || rect.height <= 0) return null;
        const logicalWidth = Number(canvas.width) || 2000;
        const logicalHeight = Number(canvas.height) || 1000;
        return {
            canvas,
            rect,
            logicalWidth,
            logicalHeight,
            cssPerMainX: rect.width / logicalWidth,
            cssPerMainY: rect.height / logicalHeight,
        };
    }

    function boundsFromCanvasPoints(points) {
        if (!Array.isArray(points) || !points.length) return null;
        const valid = points.filter(point => Number.isFinite(point?.x) && Number.isFinite(point?.y));
        if (!valid.length) return null;
        const xs = valid.map(point => point.x);
        const ys = valid.map(point => point.y);
        const left = Math.min(...xs);
        const right = Math.max(...xs);
        const top = Math.min(...ys);
        const bottom = Math.max(...ys);
        return {
            left, right, top, bottom,
            width: Math.max(0, right - left),
            height: Math.max(0, bottom - top),
            centerX: (left + right) / 2,
            centerY: (top + bottom) / 2,
            points: valid.map(point => ({ x: point.x, y: point.y })),
        };
    }

    function plushTransformSignature(item) {
        if (!isOurs(item)) return "";
        const transform = readActivePlushLayerTransform(item);
        if (!transform) return "";
        return [
            item?.Asset?.Group?.Name || "",
            canonicalWirePlushOption(getItemPlushOption(item)),
            transform.TranslationX,
            transform.TranslationY,
            transform.ScaleX,
            transform.ScaleY,
            transform.Rotation,
        ].join("|");
    }

    function cloneBounds(bounds) {
        if (!bounds) return null;
        const points = Array.isArray(bounds.points)
            ? bounds.points.map(point => ({ x: Number(point.x), y: Number(point.y) }))
            : [
                { x: Number(bounds.left), y: Number(bounds.top) },
                { x: Number(bounds.right), y: Number(bounds.top) },
                { x: Number(bounds.right), y: Number(bounds.bottom) },
                { x: Number(bounds.left), y: Number(bounds.bottom) },
            ];
        return boundsFromCanvasPoints(points);
    }

    function screenBoundsToMainBounds(bounds) {
        const scale = mainCanvasCssScale();
        if (!bounds || !scale) return null;
        const points = (Array.isArray(bounds.points) && bounds.points.length
            ? bounds.points
            : [
                { x: bounds.left, y: bounds.top },
                { x: bounds.right, y: bounds.top },
                { x: bounds.right, y: bounds.bottom },
                { x: bounds.left, y: bounds.bottom },
            ]).map(point => ({
                x: (Number(point.x) - scale.rect.left) / scale.cssPerMainX,
                y: (Number(point.y) - scale.rect.top) / scale.cssPerMainY,
            }));
        return boundsFromCanvasPoints(points);
    }

    function mainBoundsToScreenBounds(bounds) {
        const scale = mainCanvasCssScale();
        if (!bounds || !scale) return null;
        const points = (Array.isArray(bounds.points) && bounds.points.length
            ? bounds.points
            : [
                { x: bounds.left, y: bounds.top },
                { x: bounds.right, y: bounds.top },
                { x: bounds.right, y: bounds.bottom },
                { x: bounds.left, y: bounds.bottom },
            ]).map(point => ({
                x: scale.rect.left + Number(point.x) * scale.cssPerMainX,
                y: scale.rect.top + Number(point.y) * scale.cssPerMainY,
            }));
        return boundsFromCanvasPoints(points);
    }

    function translateMainBounds(bounds, dx, dy) {
        if (!bounds) return null;
        const x = Number(dx) || 0;
        const y = Number(dy) || 0;
        const points = (Array.isArray(bounds.points) && bounds.points.length
            ? bounds.points
            : [
                { x: bounds.left, y: bounds.top },
                { x: bounds.right, y: bounds.top },
                { x: bounds.right, y: bounds.bottom },
                { x: bounds.left, y: bounds.bottom },
            ]).map(point => ({ x: Number(point.x) + x, y: Number(point.y) + y }));
        return boundsFromCanvasPoints(points);
    }

    function characterProjectionKey(C) {
        const member = Number(C?.MemberNumber);
        if (Number.isFinite(member)) return `member:${member}`;
        if (C === window.Player) return "player";
        return `character:${String(C?.ID ?? C?.Name ?? "unknown")}`;
    }

    function overlayBoundsKey(C, item) {
        const group = item?.Asset?.Group?.Name || GROUP;
        return `${characterProjectionKey(C)}|${group}`;
    }

    function storeManualPlushMainBounds(C, item, center, xVec, yVec) {
        if (!C || !isOurs(item) || !center || !xVec || !yVec) return false;
        const points = [
            { x: center.x - xVec.x - yVec.x, y: center.y - xVec.y - yVec.y },
            { x: center.x + xVec.x - yVec.x, y: center.y + xVec.y - yVec.y },
            { x: center.x + xVec.x + yVec.x, y: center.y + xVec.y + yVec.y },
            { x: center.x - xVec.x + yVec.x, y: center.y - xVec.y + yVec.y },
        ];
        const bounds = boundsFromCanvasPoints(points);
        if (!bounds) return false;
        manualPlushMainBounds.set(overlayBoundsKey(C, item), {
            bounds,
            transformSignature: plushTransformSignature(item),
            at: Date.now(),
        });
        return true;
    }

    function manualPlushScreenBounds(C, item) {
        if (!C || !isOurs(item)) return null;
        const entry = manualPlushMainBounds.get(overlayBoundsKey(C, item));
        if (!entry || Date.now() - Number(entry.at || 0) > 1500) return null;
        if (entry.transformSignature !== plushTransformSignature(item)) return null;
        return mainBoundsToScreenBounds(entry.bounds);
    }

    function dragOverlayBoundsForItem(C, item) {
        if (!C || !isOurs(item) || C !== window.Player) return null;
        const groupName = item?.Asset?.Group?.Name || GROUP;

        if (dragSession?.groupName === groupName && dragSession.overlayCurrentMainBounds) {
            return mainBoundsToScreenBounds(dragSession.overlayCurrentMainBounds);
        }

        const entry = directDragOverlayBoundsByGroup.get(groupName);
        if (!entry || entry.transformSignature !== plushTransformSignature(item)) return null;

        const calculated = calculatedPlushScreenBounds(C, item);
        const calculatedMain = screenBoundsToMainBounds(calculated);
        if (!calculatedMain) return mainBoundsToScreenBounds(entry.bounds);

        const currentDraw = characterChatRoomDraw(C);
        const currentZoom = Number(currentDraw?.zoom);
        const storedZoom = Number(entry.drawZoom);
        const zoomRatio = Number.isFinite(currentZoom) && currentZoom > 0 &&
            Number.isFinite(storedZoom) && storedZoom > 0
            ? currentZoom / storedZoom
            : 1;

        return mainBoundsToScreenBounds(translateMainBounds(
            calculatedMain,
            Number(entry.correctionX || 0) * zoomRatio,
            Number(entry.correctionY || 0) * zoomRatio
        ));
    }

    function applyLearnedOverlayError(C, item, calculatedBounds) {
        if (!C || C !== window.Player || !isOurs(item) || !calculatedBounds) return calculatedBounds;
        const groupName = item?.Asset?.Group?.Name || GROUP;
        const learned = directDragOverlayErrorByGroup.get(groupName);
        const transform = readActivePlushLayerTransform(item);
        if (!learned || !transform) return calculatedBounds;

        const tx = Number(transform.TranslationX) || 0;
        const ty = Number(transform.TranslationY) || 0;
        let dx = 0;
        let dy = 0;
        if (Number.isFinite(learned.errorPerTranslationX)) dx += tx * learned.errorPerTranslationX;
        if (Number.isFinite(learned.errorPerTranslationY)) dy += ty * learned.errorPerTranslationY;

        if (!dx && !dy) return calculatedBounds;
        const main = screenBoundsToMainBounds(calculatedBounds);
        if (!main) return calculatedBounds;
        return mainBoundsToScreenBounds(translateMainBounds(main, dx, dy)) || calculatedBounds;
    }

    function commitDirectDragOverlayBounds(session, item) {
        if (!session || !isOurs(item) || !session.overlayCurrentMainBounds) return false;
        const groupName = session.groupName;
        const calculated = calculatedPlushScreenBounds(window.Player, item);
        const calculatedMain = screenBoundsToMainBounds(calculated);
        const direct = cloneBounds(session.overlayCurrentMainBounds);
        if (!calculatedMain || !direct) return false;

        const correctionX = direct.centerX - calculatedMain.centerX;
        const correctionY = direct.centerY - calculatedMain.centerY;
        const draw = characterChatRoomDraw(window.Player);
        const transform = readActivePlushLayerTransform(item);

        directDragOverlayBoundsByGroup.set(groupName, {
            bounds: direct,
            correctionX,
            correctionY,
            transformSignature: plushTransformSignature(item),
            drawZoom: Number(draw?.zoom) || 1,
            at: Date.now(),
        });

        if (transform) {
            const previous = directDragOverlayErrorByGroup.get(groupName) || {};
            const next = { ...previous };
            const tx = Number(transform.TranslationX) || 0;
            const ty = Number(transform.TranslationY) || 0;
            if (Math.abs(tx) >= 8 && Math.abs(correctionX) >= 0.5) {
                next.errorPerTranslationX = correctionX / tx;
            }
            if (Math.abs(ty) >= 8 && Math.abs(correctionY) >= 0.5) {
                next.errorPerTranslationY = correctionY / ty;
            }
            next.at = Date.now();
            directDragOverlayErrorByGroup.set(groupName, next);
        }
        return true;
    }

    function layerTranslationHeightRatio(C) {
        const ratio = Number(C?.HeightRatio);
        return Number.isFinite(ratio) && ratio > 0.01 ? ratio : 1;
    }

    function layerTranslationMainCanvasDelta(C, originX, originY, translationX, translationY) {
        const origin = characterPointToMainCanvas(C, originX, originY);
        const unitX = characterPointToMainCanvas(C, originX + 1, originY);
        const unitY = characterPointToMainCanvas(C, originX, originY + 1);
        if (!origin || !unitX || !unitY) return null;

        const ratio = layerTranslationHeightRatio(C);
        const tx = Number(translationX) || 0;
        const ty = Number(translationY) || 0;
        return {
            x: ((unitX.x - origin.x) * tx + (unitY.x - origin.x) * ty) / ratio,
            y: ((unitX.y - origin.y) * tx + (unitY.y - origin.y) * ty) / ratio,
        };
    }

    function layerTranslationScreenDelta(C, originX, originY, translationX, translationY) {
        const canvas = document.getElementById("MainCanvas") || document.querySelector("canvas");
        const rect = canvas?.getBoundingClientRect?.();
        if (!canvas || !rect || rect.width <= 0 || rect.height <= 0) return null;

        const delta = layerTranslationMainCanvasDelta(C, originX, originY, translationX, translationY);
        if (!delta) return null;

        const logicalWidth = Number(canvas.width) || 2000;
        const logicalHeight = Number(canvas.height) || 1000;
        return {
            x: delta.x * rect.width / logicalWidth,
            y: delta.y * rect.height / logicalHeight,
        };
    }

    function calculatedPlushScreenBounds(C, item) {
        if (!C || !isOurs(item)) return null;
        const transform = readActivePlushLayerTransform(item);
        if (!transform) return null;

        const scaleX = Math.max(0.05, Math.abs(Number(transform.ScaleX) || 1));
        const scaleY = Math.max(0.05, Math.abs(Number(transform.ScaleY) || 1));
        const halfWidth = PLUSH_RENDER.Width * scaleX / 2;
        const halfHeight = PLUSH_RENDER.Height * scaleY / 2;

        const baseCenterX = PLUSH_RENDER.Left + PLUSH_RENDER.Width / 2;
        const baseCenterY = PLUSH_RENDER.Top + PLUSH_RENDER.Height / 2;
        const radians = (Number(transform.Rotation) || 0) * Math.PI / 180;
        const cos = Math.cos(radians);
        const sin = Math.sin(radians);

        const translation = layerTranslationScreenDelta(
            C,
            baseCenterX,
            baseCenterY,
            Number(transform.TranslationX) || 0,
            Number(transform.TranslationY) || 0
        );
        if (!translation) return null;

        const localCorners = [
            [-halfWidth, -halfHeight],
            [halfWidth, -halfHeight],
            [halfWidth, halfHeight],
            [-halfWidth, halfHeight],
        ];

        const points = [];
        for (const [localX, localY] of localCorners) {
            const characterX = baseCenterX + localX * cos - localY * sin;
            const characterY = baseCenterY + localX * sin + localY * cos;
            const point = characterPointToScreen(C, characterX, characterY);
            if (!point || !Number.isFinite(point.x) || !Number.isFinite(point.y)) return null;
            points.push({
                x: point.x + translation.x,
                y: point.y + translation.y,
            });
        }

        const xs = points.map(point => point.x);
        const ys = points.map(point => point.y);
        const left = Math.min(...xs);
        const right = Math.max(...xs);
        const top = Math.min(...ys);
        const bottom = Math.max(...ys);

        return {
            left,
            right,
            top,
            bottom,
            width: Math.max(0, right - left),
            height: Math.max(0, bottom - top),
            centerX: (left + right) / 2,
            centerY: (top + bottom) / 2,
            points,
        };
    }

    function plushScreenBounds(C, item) {
        if (!C || !isOurs(item)) return null;

        const groupName = item?.Asset?.Group?.Name || GROUP;

        if (C === window.Player &&
            dragSession?.groupName === groupName &&
            dragSession.overlayCurrentMainBounds) {
            const activeDragBounds = mainBoundsToScreenBounds(dragSession.overlayCurrentMainBounds);
            if (activeDragBounds) return activeDragBounds;
        }

        const manual = manualPlushScreenBounds(C, item);
        if (manual) return manual;

        const direct = dragOverlayBoundsForItem(C, item);
        if (direct) return direct;

        const calculated = calculatedPlushScreenBounds(C, item);
        return applyLearnedOverlayError(C, item, calculated);
    }

    function speechBubbleTargetItem() {
        if (dragSession?.groupName) {
            const dragged = getInventoryItem(window.Player, dragSession.groupName);
            if (isOurs(dragged)) return dragged;
        }

        if (speechBubbleGroupName) {
            const owned = getInventoryItem(window.Player, speechBubbleGroupName);
            if (isOurs(owned)) return owned;
        }

        const selected = getDragTargetItem();
        if (isOurs(selected)) return selected;

        return getHeld(window.Player);
    }

    function statusOverlayTargetItem() {
        if (dragSession?.groupName) {
            const dragged = getInventoryItem(window.Player, dragSession.groupName);
            if (isOurs(dragged)) return dragged;
        }

        const selected = getDragTargetItem();
        if (isOurs(selected)) return selected;

        return getHeld(window.Player);
    }

    function positionSpeechBubble() {
        if (!speechBubbleElement?.isConnected) return false;
        const item = speechBubbleTargetItem();
        const bounds = plushScreenBounds(window.Player, item);
        if (!bounds) return false;

        speechBubbleElement.style.left = `${Math.round(bounds.centerX)}px`;
        speechBubbleElement.style.top = `${Math.round(bounds.top + SPEECH_BUBBLE_Y_OFFSET_CSS_PX - 5)}px`;
        return true;
    }

    function showSpeechBubble(text = null, { force = false, durationMs = SPEECH_BUBBLE_DURATION_MS } = {}) {
        if (!force && !getFeatureSettings().speechBubbles) return false;
        const bubbleItem = dragSession?.groupName
            ? getInventoryItem(window.Player, dragSession.groupName)
            : (isOurs(getDragTargetItem()) ? getDragTargetItem() : getHeld(window.Player));
        if (!isOurs(bubbleItem) || window.CurrentScreen !== "ChatRoom") return false;
        removeSpeechBubble();
        speechBubbleGroupName = PLUSH_GROUPS.includes(bubbleItem?.Asset?.Group?.Name)
            ? bubbleItem.Asset.Group.Name
            : GROUP;
        const bubble = document.createElement("div");
        bubble.className = "SubbysPlushiesSpeechBubble";
        bubble.textContent = String(text || randomPlushSpeech()).slice(0, 90);
        Object.assign(bubble.style, {
            position: "fixed", zIndex: "2147482900", transform: "translate(-50%, -100%)",
            maxWidth: "180px", padding: "6px 9px", border: "1px solid currentColor",
            borderRadius: "8px", background: "rgba(255,255,255,0.94)", color: "black",
            font: "13px Arial, sans-serif", lineHeight: "1.25", textAlign: "center", pointerEvents: "none",
            boxShadow: "0 1px 3px rgba(0,0,0,.25)",
        });
        document.body.appendChild(bubble);
        speechBubbleElement = bubble;
        positionSpeechBubble();
        recordStat("speech", 1, { plushName: plushNameForItem(bubbleItem) });
        speechBubbleTimer = window.setTimeout(removeSpeechBubble, Math.max(250, Number(durationMs) || SPEECH_BUBBLE_DURATION_MS));
        return true;
    }

    function plushStatusDescriptor(item = statusOverlayTargetItem()) {
        const now = Date.now();
        if (manualPlushEmote && Number(manualPlushEmote.until) > now) return manualPlushEmote;
        if (manualPlushEmote && Number(manualPlushEmote.until) <= now) manualPlushEmote = null;
        if (activeProtectSession) return { type: "protective", symbol: "!", color: "#FFD166" };

        const plushName = isOurs(item) ? plushNameForItem(item) : currentPlushName();
        if (isPlushSleepy(plushName)) return { type: "sleepy", symbol: "zZ", color: "#D8C8FF" };

        const score = getPlushMoodRecord(plushName).score;
        if (score <= 38) return { type: "sulky", symbol: "…", color: "#C8B9C8" };
        if (score >= 66) return { type: "happy", symbol: "♥", color: "#FF8FC7" };
        return null;
    }

    function removePlushStatusIcon() {
        try { plushStatusIconElement?.remove?.(); } catch (_) {}
        plushStatusIconElement = null;
        localOverlayPositionSignature = null;
    }

    function positionPlushStatusIcon() {
        if (!plushStatusIconElement?.isConnected) return false;
        const item = statusOverlayTargetItem();
        const bounds = plushScreenBounds(window.Player, item);
        if (!bounds) return false;
        plushStatusIconElement.style.left = `${Math.round(bounds.right + 3)}px`;
        plushStatusIconElement.style.top = `${Math.round(bounds.top + 10)}px`;
        return true;
    }

    function scheduleLocalOverlayReposition() {
        if (!plushScreenVisible()) return;
        if (localOverlayRepositionFrame != null) return;
        localOverlayRepositionFrame = requestAnimationFrame(() => {
            localOverlayRepositionFrame = null;
            if (speechBubbleElement?.isConnected) positionSpeechBubble();
            if (plushStatusIconElement?.isConnected) positionPlushStatusIcon();
            if (dragToggleButton?.isConnected) refreshDragToggleButton();
            const item = statusOverlayTargetItem();
            if (isOurs(item)) localOverlayPositionSignature = plushOverlayPositionSignature(window.Player, item);
        });
    }

    function refreshPlushStatusIcon() {
        const targetItem = statusOverlayTargetItem();
        if (!plushScreenVisible() || !isOurs(targetItem)) {
            removePlushStatusIcon();
            schedulePlushStatusSleepRefresh(targetItem);
            return false;
        }
        const descriptor = plushStatusDescriptor(targetItem);
        if (!descriptor?.symbol) {
            removePlushStatusIcon();
            schedulePlushStatusSleepRefresh(targetItem);
            return false;
        }
        if (!plushStatusIconElement?.isConnected) {
            const icon = document.createElement("div");
            icon.className = "SubbysPlushiesMoodVisual";
            Object.assign(icon.style, {
                position: "fixed",
                zIndex: "2147482880",
                transform: "translate(0, -100%)",
                pointerEvents: "none",
                userSelect: "none",
                font: "bold 11px Arial, sans-serif",
                lineHeight: "1",
                textShadow: "0 1px 2px rgba(0,0,0,.85)",
                whiteSpace: "nowrap",
            });
            document.body.appendChild(icon);
            plushStatusIconElement = icon;
        }
        plushStatusIconElement.textContent = descriptor.symbol;
        plushStatusIconElement.style.color = descriptor.color || "#FFFFFF";
        plushStatusIconElement.dataset.state = descriptor.type || "mood";
        const positioned = positionPlushStatusIcon();
        schedulePlushStatusSleepRefresh(targetItem);
        return positioned;
    }

    function schedulePlushStatusSleepRefresh(item = statusOverlayTargetItem()) {
        if (plushStatusIconTimer != null) window.clearTimeout(plushStatusIconTimer);
        plushStatusIconTimer = null;
        if (document.hidden || window.CurrentScreen !== "ChatRoom" || !isOurs(item)) return false;

        const plushName = plushNameForItem(item);
        const record = getPlushRelationshipRecord(plushName);
        const dueAt = (Number(record?.lastInteractionAt) || Date.now()) + SLEEPY_AFTER_MS;
        const wait = dueAt - Date.now();
        if (wait <= 0) return false;

        plushStatusIconTimer = window.setTimeout(() => {
            plushStatusIconTimer = null;
            refreshPlushStatusIcon();
        }, Math.max(50, Math.min(0x7fffffff, wait + 50)));
        return true;
    }

    function startPlushStatusIconMonitor() {
        const result = refreshPlushStatusIcon();
        schedulePlushStatusSleepRefresh(statusOverlayTargetItem());
        return result;
    }

    function plushEmoteDefinition(type) {
        const key = String(type || "").trim().toLowerCase();
        const definitions = {
            happy: { type: "happy", symbol: "♥", color: "#FF8FC7", bubble: "♥" },
            angry: { type: "angry", symbol: "!!", color: "#FF8F8F", bubble: "Hmph!" },
            sleepy: { type: "sleepy", symbol: "zZ", color: "#D8C8FF", bubble: "zZ..." },
            protective: { type: "protective", symbol: "!", color: "#FFD166", bubble: "!" },
            protect: { type: "protective", symbol: "!", color: "#FFD166", bubble: "!" },
            sulky: { type: "sulky", symbol: "…", color: "#C8B9C8", bubble: "..." },
        };
        return definitions[key] || null;
    }

    function sendSyncedPlushEmote(type) {
        const selected = plushEmoteDefinition(type);
        if (!selected || window.CurrentScreen !== "ChatRoom" || typeof window.ServerSend !== "function") return false;
        try {
            window.ServerSend("ChatRoomChat", {
                Content: `${PLUSH_EMOTE_SYNC_CONTENT_PREFIX}${selected.type}`,
                Type: "Hidden",
                Dictionary: [
                    { Tag: PLUSH_EMOTE_SYNC_TAG, Text: selected.type },
                    { Tag: "SubbysPlushiesEmotePlush", Text: currentPlushName() },
                    { Tag: "SubbysPlushiesEmoteDuration", Text: String(PLUSH_EMOTE_DURATION_MS) },
                ],
            });
            return true;
        } catch (e) {
            warn("Could not synchronize plushie emote:", e);
            return false;
        }
    }

    function syncedPlushEmoteType(data) {
        if (!data || typeof data !== "object") return null;
        const content = String(data.Content || "");
        if (content.startsWith(PLUSH_EMOTE_SYNC_CONTENT_PREFIX)) {
            const selected = plushEmoteDefinition(content.slice(PLUSH_EMOTE_SYNC_CONTENT_PREFIX.length));
            if (selected) return selected.type;
        }
        const dictionary = Array.isArray(data.Dictionary) ? data.Dictionary : [];
        const entry = dictionary.find(part => part?.Tag === PLUSH_EMOTE_SYNC_TAG && typeof part?.Text === "string");
        const selected = plushEmoteDefinition(entry?.Text);
        return selected?.type || null;
    }

    function isSyncedPlushEmotePacket(data) {
        return !!syncedPlushEmoteType(data) && (data?.Type === "Hidden" || data?.Type === "Action");
    }

    function removeRemotePlushEmote(memberNumber) {
        const member = Number(memberNumber);
        const state = remotePlushEmotes.get(member);
        if (!state) return false;
        if (state.timer != null) window.clearTimeout(state.timer);
        try { state.icon?.remove?.(); } catch (_) {}
        try { state.bubble?.remove?.(); } catch (_) {}
        remotePlushEmotes.delete(member);
        return true;
    }

    function clearRemotePlushEmotes() {
        for (const member of [...remotePlushEmotes.keys()]) removeRemotePlushEmote(member);
        clearPetSuitPlushOverlays();
        lastCharacterChatRoomDraw.clear();
    }

    function positionRemotePlushEmote(memberNumber) {
        const member = Number(memberNumber);
        const state = remotePlushEmotes.get(member);
        if (!state) return false;
        if (Date.now() >= state.until) {
            removeRemotePlushEmote(member);
            return false;
        }
        const C = getRoomCharacterByMember(member);
        const item = getHeld(C);
        if (!C || !isOurs(item)) return false;
        const bounds = currentPlushCanvasBounds(item);
        if (!bounds) return false;

        const iconPoint = characterPointToScreen(C, bounds.visualRight + 3, bounds.visualTop + 10);
        const bubblePoint = characterPointToScreen(C, bounds.centerX, bounds.visualTop - 8);
        if (iconPoint && state.icon?.isConnected) {
            state.icon.style.left = `${Math.round(iconPoint.x)}px`;
            state.icon.style.top = `${Math.round(iconPoint.y)}px`;
        }
        if (bubblePoint && state.bubble?.isConnected) {
            state.bubble.style.left = `${Math.round(bubblePoint.x)}px`;
            state.bubble.style.top = `${Math.round(bubblePoint.y + SPEECH_BUBBLE_Y_OFFSET_CSS_PX - 5)}px`;
        }
        return !!(iconPoint || bubblePoint);
    }

    function showRemotePlushEmote(memberNumber, type) {
        const member = Number(memberNumber);
        const playerMember = Number(window.Player?.MemberNumber);
        if (!Number.isFinite(member) || member === playerMember || window.CurrentScreen !== "ChatRoom") return false;
        const selected = plushEmoteDefinition(type);
        const C = getRoomCharacterByMember(member);
        if (!selected || !C || !isOurs(getHeld(C))) return false;

        removeRemotePlushEmote(member);
        const icon = document.createElement("div");
        icon.className = "SubbysPlushiesRemoteMoodVisual";
        icon.textContent = selected.symbol;
        Object.assign(icon.style, {
            position: "fixed", zIndex: "2147482878", transform: "translate(0, -100%)",
            pointerEvents: "none", userSelect: "none", font: "bold 11px Arial, sans-serif",
            lineHeight: "1", textShadow: "0 1px 2px rgba(0,0,0,.85)", whiteSpace: "nowrap",
            color: selected.color || "#FFFFFF",
        });

        const bubble = document.createElement("div");
        bubble.className = "SubbysPlushiesRemoteSpeechBubble";
        bubble.textContent = selected.bubble;
        Object.assign(bubble.style, {
            position: "fixed", zIndex: "2147482898", transform: "translate(-50%, -100%)",
            maxWidth: "180px", padding: "6px 9px", border: "1px solid currentColor",
            borderRadius: "8px", background: "rgba(255,255,255,0.94)", color: "black",
            font: "13px Arial, sans-serif", lineHeight: "1.25", textAlign: "center", pointerEvents: "none",
            boxShadow: "0 1px 3px rgba(0,0,0,.25)",
        });

        document.body.append(icon, bubble);
        const state = {
            type: selected.type,
            until: Date.now() + PLUSH_EMOTE_DURATION_MS,
            icon,
            bubble,
            timer: null,
            positionSignature: "",
        };
        state.timer = window.setTimeout(() => removeRemotePlushEmote(member), PLUSH_EMOTE_DURATION_MS + 80);
        remotePlushEmotes.set(member, state);
        positionRemotePlushEmote(member);
        return true;
    }

    function processSyncedPlushEmote(data) {
        const type = syncedPlushEmoteType(data);
        const sender = Number(data?.Sender);
        if (!type || !Number.isFinite(sender)) return false;
        return showRemotePlushEmote(sender, type);
    }

    function rememberAddonPresence(memberNumber, version = "") {
        const member = Number(memberNumber);
        if (!Number.isFinite(member)) return false;
        addonPresenceMembers.set(member, { version: String(version || ""), at: Date.now() });
        return true;
    }

    function sendAddonPresence(force = false) {
        if (window.CurrentScreen !== "ChatRoom" || typeof window.ServerSend !== "function") return false;
        const now = Date.now();
        if (!force && now - lastAddonPresenceBroadcastAt < 900) return false;
        const member = Number(window.Player?.MemberNumber);
        if (Number.isFinite(member)) rememberAddonPresence(member, VERSION);
        try {
            window.ServerSend("ChatRoomChat", {
                Content: ADDON_PRESENCE_CONTENT,
                Type: "Hidden",
                Dictionary: [{ Tag: ADDON_PRESENCE_TAG, Text: VERSION }],
            });
            lastAddonPresenceBroadcastAt = now;
            return true;
        } catch (_) {
            return false;
        }
    }

    function processAddonPresencePacket(data) {
        if (!data || data.Type !== "Hidden" || data.Content !== ADDON_PRESENCE_CONTENT) return false;
        const sender = Number(data.Sender);
        if (!Number.isFinite(sender)) return false;

        rememberAddonPresence(sender, getDictionaryText(data, ADDON_PRESENCE_TAG) || "");
        return true;
    }

    function pruneAddonPresence() {
        const present = new Set((Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [])
            .map(C => Number(C?.MemberNumber))
            .filter(Number.isFinite));
        const playerMember = Number(window.Player?.MemberNumber);
        if (Number.isFinite(playerMember)) present.add(playerMember);
        for (const member of [...addonPresenceMembers.keys()]) {
            if (!present.has(member)) addonPresenceMembers.delete(member);
        }
    }

    function characterHasAddonPresence(C) {
        if (!C) return false;
        const member = Number(C.MemberNumber);
        const playerMember = Number(window.Player?.MemberNumber);
        if (C === window.Player || (Number.isFinite(member) && member === playerMember)) return true;
        return Number.isFinite(member) && addonPresenceMembers.has(member);
    }

    function pruneSharedWaveChains(now = Date.now()) {
        for (const [id, at] of seenSharedWaveChains) if (now - Number(at || 0) > 60000) seenSharedWaveChains.delete(id);
    }

    function sharedWaveCharacterX(C, fallbackIndex = 0) {
        try {
            const point = characterPointToMainCanvas(C, 500, 500);
            if (Number.isFinite(point?.x)) return Number(point.x);
        } catch (_) {}
        const id = Number(C?.ID);
        if (Number.isFinite(id)) return id * 1000;
        return fallbackIndex * 1000;
    }

    function sharedWaveParticipantsLeftToRight() {
        const chars = [];
        const room = Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [];
        const all = [window.Player, ...room].filter(Boolean);
        const seen = new Set();

        for (let i = 0; i < all.length; i++) {
            const C = all[i];
            const member = Number(C?.MemberNumber);
            if (!Number.isFinite(member) || seen.has(member)) continue;
            seen.add(member);
            chars.push({ member, x: sharedWaveCharacterX(C, i), index: i });
        }

        chars.sort((a, b) => a.x - b.x || a.index - b.index || a.member - b.member);
        return chars.map(entry => entry.member);
    }

    function applySharedWavePose(C, durationMs) {
        if (!C) return false;
        return applyTemporaryRaisedArm(
            C,
            Math.max(900, Number(durationMs) || 2500),
            "shared-wave"
        );
    }

    function scheduleSharedWavePayload(payload) {
        if (!getFeatureSettings().sharedEmoteChains || !payload || typeof payload !== "object") return false;

        const id = String(payload.id || "");
        const members = Array.isArray(payload.members)
            ? [...new Set(payload.members.map(Number).filter(Number.isFinite))]
            : [];
        const startAt = Number(payload.startAt);

        if (!id || !members.length || !Number.isFinite(startAt)) return false;

        pruneSharedWaveChains();
        if (seenSharedWaveChains.has(id)) return true;
        seenSharedWaveChains.set(id, Date.now());

        const localMember = Number(window.Player?.MemberNumber);

        for (let index = 0; index < members.length; index++) {
            const member = members[index];
            const C =
                Number.isFinite(localMember) && member === localMember
                    ? window.Player
                    : getRoomCharacterByMember(member);

            if (!C) continue;

            const delay = Math.max(
                0,
                startAt + index * SHARED_WAVE_STEP_MS - Date.now()
            );
            window.setTimeout(
                () => applySharedWavePose(C, SHARED_WAVE_POSE_MS),
                delay
            );
        }

        return true;
    }

    function processSharedWaveChainPacket(data) {
        if (!data || data.Type !== "Hidden" || data.Content !== SHARED_WAVE_CONTENT) return false;
        const sender = Number(data.Sender);
        if (Number.isFinite(sender)) rememberAddonPresence(sender, "wave-chain");
        const raw = getDictionaryText(data, SHARED_WAVE_TAG);
        if (!raw) return true;
        try { scheduleSharedWavePayload(JSON.parse(raw)); } catch (_) {}
        return true;
    }

    function actionLooksLikeWave(data) {
        if (!isChatAction(data)) return false;
        const spec = getCustomActivityFromAction(data);
        if (spec?.key === "wave") return true;
        return /\bwav(?:e|es|ed|ing)\b/i.test(actionSearchText(data));
    }

    function maybeStartSharedWaveChain(data, force = false) {
        if (window.CurrentScreen !== "ChatRoom") return false;
        if (!force && !actionLooksLikeWave(data)) return false;

        const settings = getFeatureSettings();
        if (!settings.sharedEmoteChains) {
            if (force && window.Player) return applySharedWavePose(window.Player, SHARED_WAVE_POSE_MS);
            return false;
        }

        const now = Date.now();
        if (now - lastSharedWaveStartedAt < SHARED_WAVE_COOLDOWN_MS) return false;

        const members = sharedWaveParticipantsLeftToRight();
        if (members.length < 2) {
            lastSharedWaveStartedAt = now;
            return window.Player ? applySharedWavePose(window.Player, SHARED_WAVE_POSE_MS) : false;
        }

        lastSharedWaveStartedAt = now;
        sendAddonPresence(false);

        const starter = Number(window.Player?.MemberNumber);
        const payload = {
            v: 1,
            id: `${Number.isFinite(starter) ? starter : "local"}:${now}:${Math.random().toString(36).slice(2, 8)}`,
            startAt: now + SHARED_WAVE_LEAD_MS,
            members,
        };

        scheduleSharedWavePayload(payload);

        try {
            window.ServerSend("ChatRoomChat", {
                Content: SHARED_WAVE_CONTENT,
                Type: "Hidden",
                Dictionary: [{ Tag: SHARED_WAVE_TAG, Text: JSON.stringify(payload) }],
            });
            return true;
        } catch (_) {
            return true;
        }
    }

    function expressionReactionTargetIsLocal(data) {
        const context = getActionCharacterContext(data);
        const localMember = Number(window.Player?.MemberNumber);
        if (Number.isFinite(context.targetMember) && Number.isFinite(localMember)) return Number(context.targetMember) === localMember;
        const target = normalizeDialogueName(context.targetName, "").toLowerCase();
        if (!target) return false;
        const localNames = [getCharacterDisplayName(window.Player), window.Player?.Name, window.Player?.AccountName]
            .filter(Boolean).map(name => normalizeDialogueName(name, "").toLowerCase());
        return localNames.includes(target);
    }

    function processExpressionReaction(data, spec) {
        if (!getFeatureSettings().expressionReactions || !spec || !expressionReactionTargetIsLocal(data)) return false;
        const sender = Number(data?.Sender);
        const localMember = Number(window.Player?.MemberNumber);
        if (Number.isFinite(sender) && Number.isFinite(localMember) && sender === localMember) return false;
        if (typeof window.CharacterSetFacialExpression !== "function") return false;
        try {
            const gentle = !["bonk", "extraPointDramatically", "extraTapHead"].includes(spec.key);
            window.CharacterSetFacialExpression(window.Player, "Blush", "Low", gentle ? 6 : 4);
            window.CharacterSetFacialExpression(window.Player, "Mouth", "Grin", gentle ? 5 : 3);
            if (typeof window.ChatRoomCharacterUpdate === "function") window.setTimeout(() => {
                try { window.ChatRoomCharacterUpdate(window.Player); } catch (_) {}
            }, 20);
            return true;
        } catch (_) {
            return false;
        }
    }

    const ADDON_PRESENCE_ICON_SLOT_X = 229;
    const ADDON_PRESENCE_ICON_SLOT_TOP = 4;
    const ADDON_PRESENCE_ICON_CHARACTER_SIZE = 42;
    const ADDON_PRESENCE_ICON_ALPHA = 0.55;

    function addonPresenceIconHiddenByNativeUI() {
        const state = Number(window.ChatRoomHideIconState);
        return Number.isFinite(state) && state !== 0;
    }

    function addonPresenceCharacterVisible(C) {
        if (!C || !characterHasAddonPresence(C)) return false;

        const member = Number(C?.MemberNumber);
        const localMember = Number(window.Player?.MemberNumber);

        if (
            Number.isFinite(member) &&
            member !== localMember &&
            Array.isArray(window.Player?.GhostList) &&
            window.Player.GhostList.includes(member)
        ) {
            return false;
        }

        return true;
    }

    function nativePresenceIconRect(C, placement = null) {
        const draw = placement || characterChatRoomDraw(C);
        if (!draw || !Number.isFinite(Number(draw.at)) || Date.now() - draw.at > 1200) return null;

        if (
            draw &&
            Number.isFinite(Number(draw.x)) &&
            Number.isFinite(Number(draw.y)) &&
            Number.isFinite(Number(draw.zoom)) &&
            Number(draw.zoom) > 0
        ) {
            const zoom = Number(draw.zoom);
            const rawLeft = Number(draw.x) + ADDON_PRESENCE_ICON_SLOT_X * zoom;
            const rawTop = Number(draw.y) + ADDON_PRESENCE_ICON_SLOT_TOP;
            const size = ADDON_PRESENCE_ICON_CHARACTER_SIZE * zoom;
            if ([rawLeft, rawTop, size].every(Number.isFinite)) {
                return {
                    x: rawLeft,
                    y: rawTop,
                    width: Math.max(18, Math.min(44, size)),
                    height: Math.max(18, Math.min(44, size)),
                };
            }
        }

        return null;
    }

    const nativePresenceDomBadges = new Map();
    const nativePresencePendingOverlayWork = new Map();
    const nativePresenceCaptureTimes = new Map();
    const nativePresenceEffectProbeTimes = new Map();
    let nativePresenceBadgePruneTimer = null;
    let nativePresenceOverlayWorkRaf = 0;
    // The addon indicator is a hover-only decoration, never a permanent badge.
    // Keep the pointer in CSS screen coordinates so browser zoom and canvas scaling
    // are handled by the same character-coordinate helpers used by plushie overlays.
    let nativePresenceHoverPointer = null;
    let nativePresenceHoveredKey = null;
    let nativePresenceHoverFrame = 0;
    let nativePresenceHoverListenersInstalled = false;

    function nativePresenceBadgeKey(C) {
        const member = Number(C?.MemberNumber);
        if (Number.isFinite(member)) return `member:${member}`;
        return C === window.Player ? "player" : null;
    }

    function nativePresenceCanvasElement() {
        return document.getElementById("MainCanvas") || document.querySelector("canvas");
    }

    function nativePresenceHoveredCharacterKey() {
        const pointer = nativePresenceHoverPointer;
        if (!pointer || window.CurrentScreen !== "ChatRoom" || document.hidden || addonPresenceIconHiddenByNativeUI()) return null;
        const canvas = nativePresenceCanvasElement();
        const canvasRect = canvas?.getBoundingClientRect?.();
        if (!canvasRect || pointer.x < canvasRect.left || pointer.x > canvasRect.right ||
            pointer.y < canvasRect.top || pointer.y > canvasRect.bottom) return null;

        const roster = Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [];
        const members = roster.includes(window.Player) ? roster : [...roster, window.Player];
        let winner = null;
        let bestScore = Infinity;
        for (const C of members) {
            if (!addonPresenceCharacterVisible(C)) continue;
            const draw = characterChatRoomDraw(C);
            if (!draw || !Number.isFinite(draw.at) || Date.now() - draw.at > 1200) continue;
            // BC draws characters on a native 500 x 1000 character canvas.
            // The existing helper accounts for height, zoom, and appearance offsets.
            const start = characterPointToScreen(C, 0, 0);
            const end = characterPointToScreen(C, 500, 1000);
            if (!start || !end) continue;
            const left = Math.min(start.x, end.x);
            const right = Math.max(start.x, end.x);
            const top = Math.min(start.y, end.y);
            const bottom = Math.max(start.y, end.y);
            const width = right - left;
            const height = bottom - top;
            if (width < 5 || height < 5 || pointer.x < left || pointer.x > right ||
                pointer.y < top || pointer.y > bottom) continue;
            // If avatars overlap, prefer the one whose center is closest, so
            // hovering one person never lights up several addon indicators.
            const score = Math.pow((pointer.x - (left + right) / 2) / width, 2) +
                Math.pow((pointer.y - (top + bottom) / 2) / height, 2);
            if (score < bestScore) {
                winner = nativePresenceBadgeKey(C);
                bestScore = score;
            }
        }
        return winner;
    }

    function refreshNativePresenceBadgeHover() {
        nativePresenceHoveredKey = nativePresenceHoveredCharacterKey();
        if (nativePresenceHoveredKey && !nativePresenceDomBadges.has(nativePresenceHoveredKey)) {
            const key = nativePresenceHoveredKey;
            const members = Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [];
            const C = key === nativePresenceBadgeKey(window.Player) ? window.Player :
                members.find(member => nativePresenceBadgeKey(member) === key);
            const placement = C && characterChatRoomDraw(C);
            if (C && placement && Date.now() - Number(placement.at) <= 1200) positionNativePresenceDomBadge(C, placement);
        }
        const now = Date.now();
        for (const [key, image] of nativePresenceDomBadges) {
            if (!image?.isConnected) continue;
            const age = now - (Number(image.dataset.lastSubbysDrawAt) || 0);
            image.style.display = key === nativePresenceHoveredKey && age <= 1200 ? "block" : "none";
        }
    }

    function scheduleNativePresenceBadgeHoverRefresh() {
        if (nativePresenceHoverFrame) return;
        nativePresenceHoverFrame = window.requestAnimationFrame(() => {
            nativePresenceHoverFrame = 0;
            refreshNativePresenceBadgeHover();
        });
    }

    function installNativePresenceBadgeHoverListeners() {
        if (nativePresenceHoverListenersInstalled) return;
        nativePresenceHoverListenersInstalled = true;
        // Using a document listener avoids fragile per-canvas attachment after BC
        // re-creates its canvas; pointer events still must originate on MainCanvas.
        document.addEventListener("pointermove", event => {
            const canvas = nativePresenceCanvasElement();
            nativePresenceHoverPointer = event.target === canvas && event.pointerType !== "touch"
                ? { x: event.clientX, y: event.clientY }
                : null;
            scheduleNativePresenceBadgeHoverRefresh();
        }, { passive: true, capture: true });
        document.addEventListener("pointerout", event => {
            if (event.target === nativePresenceCanvasElement() && event.relatedTarget !== event.target) {
                nativePresenceHoverPointer = null;
                refreshNativePresenceBadgeHover();
            }
        }, true);
        document.addEventListener("pointercancel", () => {
            nativePresenceHoverPointer = null;
            refreshNativePresenceBadgeHover();
        }, true);
        window.addEventListener("blur", () => {
            nativePresenceHoverPointer = null;
            refreshNativePresenceBadgeHover();
        });
        document.addEventListener("visibilitychange", () => {
            if (document.hidden) nativePresenceHoverPointer = null;
            refreshNativePresenceBadgeHover();
        });
    }

    function ensureNativePresenceDomBadge(C) {
        const key = nativePresenceBadgeKey(C);
        if (!key) return null;

        const existing = nativePresenceDomBadges.get(key);
        if (existing?.isConnected) return existing;

        const image = document.createElement("img");
        image.className = "SubbysPlushiesPresenceBadge";
        image.alt = "";
        image.draggable = false;
        image.src = PLUSH_FALLBACK_IMAGE;
        Object.assign(image.style, {
            position: "fixed",
            display: "none",
            pointerEvents: "none",
            userSelect: "none",
            objectFit: "contain",
            opacity: String(ADDON_PRESENCE_ICON_ALPHA),
            zIndex: "2147482000",
            margin: "0",
            padding: "0",
            border: "0",
            background: "transparent",
            transformOrigin: "top left",
        });

        document.body.appendChild(image);
        nativePresenceDomBadges.set(key, image);
        return image;
    }

    function hideNativePresenceDomBadges(remove = false) {
        for (const [key, image] of nativePresenceDomBadges) {
            if (!image) {
                nativePresenceDomBadges.delete(key);
                continue;
            }
            if (remove) {
                try { image.remove(); } catch (_) {}
                nativePresenceDomBadges.delete(key);
            } else {
                image.style.display = "none";
            }
        }
        if (remove) {
            if (nativePresenceBadgePruneTimer != null) window.clearTimeout(nativePresenceBadgePruneTimer);
            nativePresenceBadgePruneTimer = null;
            nativePresenceHoverPointer = null;
            nativePresenceHoveredKey = null;
            nativePresencePendingOverlayWork.clear();
            nativePresenceCaptureTimes.clear();
            nativePresenceEffectProbeTimes.clear();
            lastCharacterChatRoomDraw.clear();
            lastPlayerChatRoomDraw = null;
        }
    }

    function positionNativePresenceDomBadge(C, placement) {
        if (
            window.CurrentScreen !== "ChatRoom" ||
            addonPresenceIconHiddenByNativeUI() ||
            !addonPresenceCharacterVisible(C)
        ) {
            return false;
        }

        const logicalRect = nativePresenceIconRect(C, placement);
        if (!logicalRect) return false;

        const canvas = nativePresenceCanvasElement();
        const screenRect = canvas?.getBoundingClientRect?.();
        if (!canvas || !screenRect || screenRect.width <= 0 || screenRect.height <= 0) return false;

        const logicalWidth = Number(canvas.width) || 2000;
        const logicalHeight = Number(canvas.height) || 1000;
        const scaleX = screenRect.width / logicalWidth;
        const scaleY = screenRect.height / logicalHeight;

        const left = screenRect.left + logicalRect.x * scaleX;
        const top = screenRect.top + logicalRect.y * scaleY;
        const width = Math.max(14, logicalRect.width * scaleX);
        const height = Math.max(14, logicalRect.height * scaleY);

        if (![left, top, width, height].every(Number.isFinite)) return false;

        // Do not allocate DOM badges for all remote members every render.
        if (nativePresenceHoveredKey !== nativePresenceBadgeKey(C)) return false;
        const image = ensureNativePresenceDomBadge(C);
        if (!image) return false;

        image.dataset.lastSubbysDrawAt = String(placement.at || Date.now());
        Object.assign(image.style, {
            display: nativePresenceHoveredKey === nativePresenceBadgeKey(C) ? "block" : "none",
            left: `${Math.round(left)}px`,
            top: `${Math.round(top)}px`,
            width: `${Math.round(width)}px`,
            height: `${Math.round(height)}px`,
        });

        if (nativePresenceHoveredKey) scheduleNativeBadgeExpiry();
        nativePresenceDrawMethod = "DOM overlay after character render";
        nativePresenceDrawCount++;
        lastNativePresenceDrawAt = Date.now();
        return true;
    }

    function flushNativePresenceOverlayWork() {
        nativePresenceOverlayWorkRaf = 0;

        if (
            !plushScreenVisible() ||
            addonPresenceIconHiddenByNativeUI()
        ) {
            nativePresencePendingOverlayWork.clear();
            hideNativePresenceDomBadges(false);
            return;
        }

        const pending = [...nativePresencePendingOverlayWork.values()];
        nativePresencePendingOverlayWork.clear();
        for (const entry of pending) {
            const C = entry?.C;
            const placement = entry?.placement;
            if (!C || !placement) continue;

            try {
                rememberVisibleOverlayPlacement(C, placement);
                refreshCharacterPlushOverlaysFromNativeOverlay(C, placement);

                if (addonPresenceCharacterVisible(C)) positionNativePresenceDomBadge(C, placement);
            } catch (e) {
                warn("Deferred character-overlay plush rendering failed:", e);
            }
        }

        // The mouse may already be over a player when the next draw is queued.
        refreshNativePresenceBadgeHover();
        const now = Date.now();
        if (now - (flushNativePresenceOverlayWork.lastPruneAt || 0) > 1200) {
            flushNativePresenceOverlayWork.lastPruneAt = now;
            pruneNativePresenceDomBadges();
        }
    }

    function pruneNativePresenceDomBadges() {
        const inRoom = window.CurrentScreen === "ChatRoom" && !document.hidden &&
            !addonPresenceIconHiddenByNativeUI();
        const now = Date.now();
        const roster = Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [];
        const localMember = Number(window.Player?.MemberNumber);
        for (const [key, image] of nativePresenceDomBadges) {
            if (!image?.isConnected) {
                nativePresenceDomBadges.delete(key);
                continue;
            }
            const member = key.startsWith("member:") ? Number(key.slice(7)) : NaN;
            const C = Number.isFinite(member) && member === localMember
                ? window.Player
                : roster.find(p => Number(p?.MemberNumber) === member);
            const last = Number(image.dataset.lastSubbysDrawAt) || 0;
            if (!inRoom || !C || !addonPresenceCharacterVisible(C) || now - last > 1200) {
                image.style.display = "none";
            }
        }
        // Re-evaluate geometry while the pointer is stationary and BC changes poses.
        if (inRoom && nativePresenceHoverPointer) refreshNativePresenceBadgeHover();
    }

    function scheduleNativeBadgeExpiry() {
        if (nativePresenceBadgePruneTimer != null || !nativePresenceHoveredKey || !nativePresenceDomBadges.size) return;
        nativePresenceBadgePruneTimer = window.setTimeout(() => {
            nativePresenceBadgePruneTimer = null;
            pruneNativePresenceDomBadges();
            // Keep the stale-badge safeguard while hovered only. No idle loop.
            if (nativePresenceHoveredKey && nativePresenceDomBadges.size) scheduleNativeBadgeExpiry();
        }, 1500);
    }

    function queueNativePresenceOverlayWork(C, placement) {
        if (!C || !placement || !plushScreenVisible()) return false;
        const key = nativePresenceBadgeKey(C) || C;
        nativePresencePendingOverlayWork.set(key, { C, placement });

        if (!nativePresenceOverlayWorkRaf) {
            nativePresenceOverlayWorkRaf = requestAnimationFrame(flushNativePresenceOverlayWork);
        }
        return true;
    }

    let lastNativePresenceOverlayContext = null;

    function rememberVisibleOverlayPlacement(C, placement) {
        if (!C || !placement) return false;
        const member = Number(C.MemberNumber);
        const playerMember = Number(window.Player?.MemberNumber);
        const samePlayer = C === window.Player ||
            (Number.isFinite(playerMember) && member === playerMember);
        if (samePlayer) lastPlayerChatRoomDraw = placement;
        if (Number.isFinite(member)) lastCharacterChatRoomDraw.set(member, placement);
        return true;
    }

    function refreshCharacterPlushOverlaysFromNativeOverlay(C, placement) {
        if (!C || !placement || window.CurrentScreen !== "ChatRoom") return false;
        rememberVisibleOverlayPlacement(C, placement);

        const handheld = getHandheldItem(C);
        if (isOurs(handheld) || petSuitRenderStates.has(petSuitOverlayKey(C))) {
            try { drawPetSuitPlushCanvasOverlay(C); } catch (_) {}
        }

        const member = Number(C.MemberNumber);
        const playerMember = Number(window.Player?.MemberNumber);
        const samePlayer = C === window.Player ||
            (Number.isFinite(playerMember) && member === playerMember);

        if (samePlayer && (speechBubbleElement?.isConnected || plushStatusIconElement?.isConnected)) {
            const dragTarget = getDragTargetItem();
            const signatureItem = isOurs(dragTarget) ? dragTarget : getHeld(C);
            const signature = plushOverlayPositionSignature(C, signatureItem);
            if (signature && signature !== localOverlayPositionSignature) {
                localOverlayPositionSignature = signature;
                scheduleLocalOverlayReposition();
            }
        } else if (Number.isFinite(member)) {
            const remote = remotePlushEmotes.get(member);
            if (remote) {
                const signature = plushOverlayPositionSignature(C, getHeld(C));
                if (signature && signature !== remote.positionSignature) {
                    remote.positionSignature = signature;
                    requestAnimationFrame(() => positionRemotePlushEmote(member));
                }
            }
        }
        return true;
    }

    function scheduleNativeAddonPresenceOverlayRetry(reason = "character drawing unavailable") {
        if (nativePresenceChatRoomRunHooked || nativePresenceOverlayRetryTimer != null) return false;
        const index = Math.min(nativePresenceOverlayRetryAttempt, NATIVE_PRESENCE_OVERLAY_RETRY_DELAYS_MS.length - 1);
        const delay = NATIVE_PRESENCE_OVERLAY_RETRY_DELAYS_MS[index];
        nativePresenceOverlayRetryAttempt++;
        nativePresenceOverlayRetryTimer = window.setTimeout(() => {
            nativePresenceOverlayRetryTimer = null;
            if (!nativePresenceChatRoomRunHooked && !installNativeAddonPresenceOverlayHook({ scheduleRetry: false })) {
                scheduleNativeAddonPresenceOverlayRetry(reason);
            }
        }, delay);
        return true;
    }

    function installNativeAddonPresenceOverlayHook({ scheduleRetry = true } = {}) {
        if (nativePresenceChatRoomRunHooked) return true;
        if (typeof window.DrawCharacter !== "function") {
            if (scheduleRetry) scheduleNativeAddonPresenceOverlayRetry("DrawCharacter unavailable");
            return false;
        }

        const hooked = installHook("DrawCharacter", 10000, (args, next) => {
            let C = null;
            let placement = null;
            if (window.CurrentScreen === "ChatRoom") {
                C = args?.[0] || null;
                const member = Number(C?.MemberNumber);
                const isPlayer = C === window.Player ||
                    (Number.isFinite(member) && member === Number(window.Player?.MemberNumber));
                const inRoom = isPlayer ||
                    (Number.isFinite(member) && Array.isArray(window.ChatRoomCharacter) &&
                     window.ChatRoomCharacter.some(p => Number(p?.MemberNumber) === member));
                if (C && inRoom) {
                    const x = Number(args?.[1]);
                    const y = Number(args?.[2]);
                    const zoom = args?.[3] == null ? 1 : Number(args[3]);
                    if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(zoom) &&
                        x > -2200 && x < 4200 && y > -2200 && y < 2500 && zoom > 0.03 && zoom < 8) {
                        placement = { x, y, zoom, matrix: null, at: Date.now(), source: "DrawCharacter" };
                    }
                }
            }
            const result = next(args);
            if (placement) {
                rememberVisibleOverlayPlacement(C, placement);
                const key = nativePresenceBadgeKey(C);
                const member = Number(C.MemberNumber);
                const local = C === window.Player || member === Number(window.Player?.MemberNumber);
                // Detect restraint overlays once every 1.5s when idle, not on
                // every native DrawCharacter invocation for each remote avatar.
                const activeRestraintOverlay = !!petSuitRenderStates.get(petSuitOverlayKey(C))?.active;
                const lastProbe = nativePresenceEffectProbeTimes.get(key) || 0;
                let newlyRestrained = false;
                if (!activeRestraintOverlay && placement.at - lastProbe >= 1500) {
                    nativePresenceEffectProbeTimes.set(key, placement.at);
                    newlyRestrained = !!characterPetSuitItem(C) && isOurs(getHandheldItem(C));
                }
                const needsOverlay = !!nativePresenceHoverPointer || activeRestraintOverlay || newlyRestrained ||
                    (Number.isFinite(member) && remotePlushEmotes.has(member)) ||
                    (local && (speechBubbleElement?.isConnected || plushStatusIconElement?.isConnected));
                const last = nativePresenceCaptureTimes.get(key) || 0;
                if (needsOverlay && (placement.at - last >= 100 || !last)) {
                    nativePresenceCaptureTimes.set(key, placement.at);
                    queueNativePresenceOverlayWork(C, placement);
                }
                lastNativePresenceOverlayContext = {
                    member: Number(C.MemberNumber) || null,
                    x: placement.x,
                    y: placement.y,
                    zoom: placement.zoom,
                    source: placement.source,
                    at: placement.at,
                };
            }
            return result;
        });
        nativePresenceChatRoomRunHooked = hooked;
        if (!hooked) {
            if (scheduleRetry) scheduleNativeAddonPresenceOverlayRetry("DrawCharacter hook not ready");
            return false;
        }
        nativePresenceOverlayRetryAttempt = 0;
        if (nativePresenceOverlayRetryTimer != null) {
            window.clearTimeout(nativePresenceOverlayRetryTimer);
            nativePresenceOverlayRetryTimer = null;
        }
        installNativePresenceBadgeHoverListeners();
        return true;
    }

    window.SubbysPlushiesPerformanceDiag = () => ({
        visible: plushScreenVisible(), loadedPlushImages: renderImages.filter(image => image && image !== renderFallbackImage).length,
        pendingPlushLoads: renderImagePromises.size, pendingActionIcons: actionIconLoads.size, pendingCanvasRedraws: dirtyPlushCharacters.size,
        activePresenceBadges: nativePresenceDomBadges.size,
        queuedPresenceDraws: nativePresencePendingOverlayWork.size,
        cachedLore: (gitDataState.loadedFiles || []).includes("lore.json"),
    });

    window.SubbysPlushiesDialogueTest = (actionKey = "pet") => {
        const spec = PLUGIN_ACTIVITY_BY_KEY.get(String(actionKey || "pet"));
        if (!spec) return null;
        const sourceName = getCharacterDisplayName(window.Player) || "Someone";
        const value = activityTemplate(
            spec,
            true,
            window.Player,
            window.Player,
            sourceName,
            sourceName,
            currentPlushName()
        );
        console.log("[Subby's Plushies dialogue test]", value);
        return value;
    };

    window.SubbysPlushiesPresenceDiag = () => {
        const C = window.Player || null;
        const info = {
            version: VERSION,
            currentScreen: window.CurrentScreen,
            localMember: Number(window.Player?.MemberNumber) || null,
            localPresence: !!C && characterHasAddonPresence(C),
            knownPresenceMembers: [...addonPresenceMembers.keys()],
            characterOverlayHooked: nativePresenceChatRoomRunHooked,
            renderBackend: nativePresenceChatRoomRunHooked ? "ModSDK DrawCharacter position capture + deferred DOM badges" : "waiting-for-DrawCharacter",
            overlayFunctionAvailable: typeof window.DrawCharacter === "function",
            badgeCount: nativePresenceDomBadges.size,
            visibleBadgeCount: [...nativePresenceDomBadges.values()].filter(img => img?.isConnected && img.style.display !== "none").length,
            visibilityMode: "character-hover-only",
            hoveredCharacter: nativePresenceHoveredKey,
            pointerOverGameCanvas: !!nativePresenceHoverPointer,
            overlayRetryAttempt: nativePresenceOverlayRetryAttempt,
            overlayRetryPending: nativePresenceOverlayRetryTimer != null,
            renderModSdkHooksBySubbysPlushies: {
                DrawCharacter: installedHooks.has("DrawCharacter"),
                ChatRoomRun: installedHooks.has("ChatRoomRun"),
                ChatRoomDrawCharacterOverlay: false,
            },
            directCoreRenderOverwrites: { DrawCharacter: false, ChatRoomRun: false },
            lastOverlayContext: lastNativePresenceOverlayContext,
            ChatRoomRun: typeof window.ChatRoomRun,
            DrawImageEx: typeof window.DrawImageEx,
            DrawImageResize: typeof window.DrawImageResize,
            ChatRoomHideIconState: window.ChatRoomHideIconState,
            drawMethod: nativePresenceDrawMethod,
            drawCount: nativePresenceDrawCount,
            lastDrawAt: lastNativePresenceDrawAt || null,
            localRect: C ? nativePresenceIconRect(C) : null,
            asset: "assets/plushies/subbycat.png",
            anchor: {
                mode: "chatroom-slot-top",
                slotX: ADDON_PRESENCE_ICON_SLOT_X,
                slotTop: ADDON_PRESENCE_ICON_SLOT_TOP,
                size: ADDON_PRESENCE_ICON_CHARACTER_SIZE,
                alpha: ADDON_PRESENCE_ICON_ALPHA,
            },
        };
        try { console.table(info); } catch (_) { console.log(info); }
        return info;
    };
    window.SubbysPlushiesPresenceDiagnostic = window.SubbysPlushiesPresenceDiag;

    function triggerPlushEmote(type) {
        const selected = plushEmoteDefinition(type);
        if (!selected || !isOurs(getHeld(window.Player))) return false;
        if (manualPlushEmoteTimer != null) window.clearTimeout(manualPlushEmoteTimer);
        manualPlushEmote = { ...selected, until: Date.now() + PLUSH_EMOTE_DURATION_MS };
        emitPluginApiEvent("emote", { plushName: currentPlushName(), type: selected.type, symbol: selected.symbol, durationMs: PLUSH_EMOTE_DURATION_MS, synced: window.CurrentScreen === "ChatRoom" });
        refreshPlushStatusIcon();
        showSpeechBubble(selected.bubble, { force: true, durationMs: PLUSH_EMOTE_DURATION_MS });
        if (window.CurrentScreen === "ChatRoom") sendSyncedPlushEmote(selected.type);
        manualPlushEmoteTimer = window.setTimeout(() => {
            manualPlushEmoteTimer = null;
            manualPlushEmote = null;
            refreshPlushStatusIcon();
        }, PLUSH_EMOTE_DURATION_MS + 50);
        return true;
    }

    function cancelIdleAnimation(reschedule = true) {
        if (idleAnimationTimer != null) window.clearTimeout(idleAnimationTimer);
        idleAnimationTimer = null;
        idleAnimationGeneration++;
        const session = activeIdleAnimationSession;
        activeIdleAnimationSession = null;
        if (session) {
            const entries = Array.isArray(session.entries)
                ? session.entries
                : [{ groupName: GROUP, layerName: session.layerName, base: session.base }];
            let changed = false;
            for (const entry of entries) {
                const current = getInventoryItem(window.Player, entry.groupName || GROUP);
                if (!isOurs(current) || getActivePlushLayerName(current) !== entry.layerName || !entry.base) continue;
                if (setPlushLayerTransform(current, entry.layerName, entry.base)) changed = true;
            }
            if (changed) rebuildCharacterCanvas(window.Player, "idle animation cancel");
        }
        if (reschedule && getFeatureSettings().idleAnimations) scheduleNextIdleAnimation();
        return true;
    }

    function runIdleAnimation() {
        const settings = getFeatureSettings();
        if (!settings.idleAnimations || isLowCpuMode() || window.CurrentScreen !== "ChatRoom" || dragSession || nativeLayeringVisible() || activeIdleAnimationSession) return false;

        const temporaryHandPose = !!(activeBalanceHeadSession || activeHideBehindSession || activeProtectSession);
        const entries = [];
        for (const item of getEquippedPlushItems(window.Player)) {
            const groupName = item?.Asset?.Group?.Name || GROUP;
            if (temporaryHandPose && groupName === GROUP) continue;
            const plushName = plushNameForItem(item);
            if (isPlushSleepy(plushName)) continue;
            const layerName = getActivePlushLayerName(item);
            const base = readActivePlushLayerTransform(item);
            if (!layerName || !base) continue;
            entries.push({ groupName, layerName, plushName, base: { ...base } });
        }
        if (!entries.length) return false;

        const generation = ++idleAnimationGeneration;
        activeIdleAnimationSession = { generation, entries };
        const direction = Math.random() < 0.5 ? -1 : 1;
        const frames = IDLE_ANIMATION_FRAMES.map(frame => ({
            delay: frame.delayMs,
            dy: frame.deltaY,
            rot: frame.rotationMultiplier * direction,
            restore: !!frame.restore,
        }));

        for (const frame of frames) {
            window.setTimeout(() => {
                const session = activeIdleAnimationSession;
                if (!session || session.generation !== generation) return;
                let changed = false;

                for (const entry of session.entries) {
                    const current = getInventoryItem(window.Player, entry.groupName);
                    if (!isOurs(current) || getActivePlushLayerName(current) !== entry.layerName) continue;
                    const nextTransform = frame.restore
                        ? entry.base
                        : {
                            ...entry.base,
                            TranslationY: entry.base.TranslationY + frame.dy,
                            Rotation: entry.base.Rotation + frame.rot,
                        };
                    if (setPlushLayerTransform(current, entry.layerName, nextTransform)) changed = true;
                }

                if (changed) {
                    rebuildCharacterCanvas(window.Player, frame.restore ? "idle plush animation restore" : "idle plush animation");
                    scheduleLocalOverlayReposition();
                }

                if (frame.restore) {
                    const finished = session.entries.slice();
                    activeIdleAnimationSession = null;
                    for (const entry of finished) recordStat("idle", 1, { plushName: entry.plushName });
                    if (settings.speechBubbles && Math.random() < SPEECH_IDLE_CHANCE) showSpeechBubble();
                }
            }, frame.delay);
        }
        return true;
    }

    function plushScreenVisible() {
        if (document.hidden || window.CurrentScreen !== "ChatRoom") return false;
        const canvas = document.getElementById("MainCanvas");
        if (!canvas || typeof canvas.getBoundingClientRect !== "function") return true;
        const rect = canvas.getBoundingClientRect();
        if (rect.width <= 0 || rect.height <= 0) return false;
        return rect.bottom > 0 && rect.right > 0 && rect.top < window.innerHeight && rect.left < window.innerWidth;
    }

    function scheduleNextIdleAnimation(delay = null) {
        if (idleAnimationTimer != null) window.clearTimeout(idleAnimationTimer);
        if (!getFeatureSettings().idleAnimations || isLowCpuMode() || !plushScreenVisible()) { idleAnimationTimer = null; return false; }
        const wait = Number.isFinite(delay) ? Math.max(500, delay) : IDLE_MIN_DELAY_MS + Math.random() * (IDLE_MAX_DELAY_MS - IDLE_MIN_DELAY_MS);
        idleAnimationTimer = window.setTimeout(() => {
            idleAnimationTimer = null;
            if (plushScreenVisible()) runIdleAnimation();
            scheduleNextIdleAnimation();
        }, wait);
        return true;
    }

    let visibilityPerformanceHooksInstalled = false;

    function installVisibilityPerformanceHooks() {
        if (visibilityPerformanceHooksInstalled) return true;
        visibilityPerformanceHooksInstalled = true;
        const resumeIfVisible = () => {
            if (!plushScreenVisible()) return;
            if (getFeatureSettings().idleAnimations && !isLowCpuMode() && idleAnimationTimer == null)
                scheduleNextIdleAnimation(1200);
            scheduleDirtyPlushRender();
            scheduleLocalOverlayReposition();
            scheduleNativePresenceBadgeHoverRefresh();
        };
        window.addEventListener("scroll", resumeIfVisible, {passive:true});
        window.addEventListener("resize", resumeIfVisible, {passive:true});
        document.addEventListener("visibilitychange", () => {
            if (document.hidden) {
                cancelIdleAnimation(false);
                if (hugTightlyActivityMonitor != null) {
                    window.clearTimeout(hugTightlyActivityMonitor);
                    hugTightlyActivityMonitor = null;
                }
                if (plushStatusIconTimer != null) {
                    window.clearTimeout(plushStatusIconTimer);
                    plushStatusIconTimer = null;
                }
                return;
            }

            syncHugTightlyActivityAvailability("tab visible");
            scheduleActivityIntegrityCheck();
            if (!installedHooks.has("ChatRoomAppendChat")) ensureOfferChatObserver("tab visible fallback");
            refreshDragToggleButton();
            refreshRoomMascotOverlay();
            refreshRoomMascotAdminButton();
            startPlushStatusIconMonitor();
            if (getFeatureSettings().idleAnimations && !isLowCpuMode()) scheduleNextIdleAnimation(1200);
            scheduleRoomRosterEventCheck("tab visible", 0);
        }, { passive: true });
        return true;
    }

    function showCurrentPlushInfo() {
        void ensureRemotePlushLore();
        const name = currentPlushName();
        const lore = getPlushLore(name) || { title: "Plushie", text: "Lore is not available yet. The addon will use the validated Git copy when it is online or cached." };
        const mood = getPlushMoodRecord(name);
        const relationship = relationshipStatus(name);
        const mascot = roomMascotState?.name
            ? `Room mascot: ${roomMascotState.name}${normalizeLoreLookupKey(roomMascotState.name) === normalizeLoreLookupKey(name) ? ` • +${ROOM_MASCOT_AFFECTION_MODIFIER} affection modifier` : ""}`
            : "Room mascot: none";
        appendLocalInfoBox(`${name} — ${lore.hidden ? "Hidden lore" : lore.title}`, [
            lore.hidden ? `${name}'s lore has not been published yet.` : lore.text,
            `Mood: ${moodLabel(mood.score)} (${mood.score}/100) • interactions: ${mood.interactions}`,
            `Relationship: ${relationship.level} (${relationship.interactions})${relationship.nextLevel ? ` • ${relationship.remaining} to ${relationship.nextLevel}` : " • max"} • ${isPlushSleepy(name) ? "sleeping zZ" : "awake"}`,
            `Protect Me: ${getFeatureSettings().protectMe ? "ON" : "off"} • Jealous Plushie: ${getFeatureSettings().jealousPlushie ? "ON" : "off"}`,
            mascot,
        ]);
        return { name, lore, mood: { ...mood }, relationship: { ...relationship } };
    }

    function handleLocalPlushInteraction(key) {
        const delta = MOOD_DELTAS[key] || 0;
        if (delta) adjustCurrentPlushMood(delta, key);
        const plushName = currentPlushName();
        recordStat("interaction", 1, { action: key, plushName });
        const relationship = touchPlushRelationship(plushName, { increment: 1, wake: true });
        trackInteractionAchievements(key, plushName);
        if (!isLowCpuMode() && (key === "pet" || key === "pat")) window.setTimeout(animatePetting, 70);
        if (!relationship.milestone && getFeatureSettings().speechBubbles && SPEECH_INTERACTION_ACTIONS.includes(key) && Math.random() < SPEECH_INTERACTION_CHANCE) {
            window.setTimeout(() => showSpeechBubble(), SPEECH_INTERACTION_DELAY_MS);
        }
        emitPluginApiEvent("interaction", {
            action: key,
            plushName,
            mood: { ...getPlushMoodRecord(plushName) },
            relationship: { ...relationship },
        });
    }

    function activityNameFromRunArgsFast(args) {
        const values = Array.isArray(args) ? args : [args];
        const candidates = [];
        const add = value => {
            if (typeof value === "string" && value && !candidates.includes(value)) candidates.push(value);
        };
        for (const value of values) {
            if (typeof value === "string") { add(value); continue; }
            if (!value || typeof value !== "object" || looksLikeCharacter(value)) continue;
            add(value.ActivityName);
            const nested = value.Activity;
            if (typeof nested === "string") add(nested);
            else if (nested && typeof nested === "object") {
                add(nested.ActivityName);
                add(nested.Name);
            }
            add(value.Name);
            add(value.Content);
        }
        return candidates.find(isAffectionateActivityName) || candidates[0] || "";
    }

    function isAffectionateActivityName(value) {
        const lower = String(value || "").toLowerCase();
        return !!lower && JEALOUS_ACTIVITY_KEYWORDS.some(token => lower.includes(token));
    }

    function triggerJealousReaction(target, activityName = "") {
        if (!getFeatureSettings().jealousPlushie || !isOurs(getHeld(window.Player))) return false;
        const now = Date.now();
        if (now - lastJealousReactionAt < 12000) return false;
        lastJealousReactionAt = now;
        adjustCurrentPlushMood(MOOD_DELTAS.jealous, `jealous:${activityName || "affection"}`);

        const sourceName = getCharacterDisplayName(window.Player) || "Someone";
        const targetName = getCharacterDisplayName(target) || "someone else";
        const plushName = currentPlushName();
        sendStandaloneActionMessage(`${plushName} plushie gives ${targetName} a tiny jealous stare while ${sourceName} gives away attention.`);
        return true;
    }

    function actionSearchText(data) {
        let text = typeof data?.Content === "string" ? data.Content : "";
        const dictionary = data?.Dictionary;
        if (Array.isArray(dictionary)) {
            for (const entry of dictionary) {
                if (typeof entry?.Text === "string") text += ` ${entry.Text}`;
            }
        }
        return text.toLowerCase();
    }

    function actionLooksProtectable(data) {
        if (!getFeatureSettings().protectMe || !isChatAction(data) || !isOurs(getHeld(window.Player))) return false;
        const text = actionSearchText(data);
        return PROTECT_KEYWORDS.some(token => text.includes(token));
    }

    function protectContextTargetsLocalPlayer(context) {
        const playerMember = Number(window.Player?.MemberNumber);
        if (!Number.isFinite(playerMember)) return false;

        if (Number.isFinite(context?.targetMember)) return Number(context.targetMember) === playerMember;

        return offerTargetIsLocalPlayer(context?.targetName);
    }

    function protectSourceIsLocal(context, data = null) {
        const playerMember = Number(window.Player?.MemberNumber);
        if (Number.isFinite(playerMember)) {
            if (Number.isFinite(context?.sourceMember) && Number(context.sourceMember) === playerMember) return true;
            if (Number(data?.Sender) === playerMember) return true;
        }

        const source = normalizeOfferName(context?.sourceName);
        return !!source && localOfferNameVariants().has(source);
    }

    function triggerProtectReaction(sourceName = null, triggerSource = "activity packet") {
        if (!getFeatureSettings().protectMe || !isOurs(getHeld(window.Player))) return false;

        const now = Date.now();
        if (now - lastProtectReactionAt < 1200) return false;
        lastProtectReactionAt = now;
        trackProtectAchievement();

        adjustCurrentPlushMood(MOOD_DELTAS.protect, `protect me:${triggerSource}`);
        window.setTimeout(movePlushToProtectTemporarily, 40);

        const plushName = currentPlushName();
        const holderName = getCharacterDisplayName(window.Player) || "its holder";
        const troubleName = sourceName || "the incoming trouble";
        sendStandaloneActionMessage(`${plushName} plushie jumps into a protective pose between ${holderName} and ${troubleName}.`);
        return true;
    }

    function maybeTriggerProtect(data, prechecked = false) {
        if (!prechecked && !actionLooksProtectable(data)) return false;
        const context = getActionCharacterContext(data);
        if (!protectContextTargetsLocalPlayer(context)) return false;
        if (protectSourceIsLocal(context, data)) return false;
        return triggerProtectReaction(context.sourceName, "activity packet");
    }

    function parseRenderedProtectAction(text) {
        let value = String(text || "")
            .replace(/[\u2018\u2019]/g, "'")
            .replace(/\s+/g, " ")
            .trim();
        if (!value || !PROTECT_RENDER_VERB_RE.test(value)) return null;

        value = value.replace(/^\(+\s*/, "");
        const match = value.match(PROTECT_RENDER_ACTION_RE);
        if (!match) return null;

        return {
            sourceName: String(match[1] || "").trim(),
            verb: String(match[2] || "").trim(),
            targetName: String(match[3] || "").trim(),
        };
    }

    function inspectRenderedProtectRow(row) {
        if (!(row instanceof Element)) return false;
        if (processedProtectChatRows.has(row)) return false;
        if (!getFeatureSettings().protectMe || !isOurs(getHeld(window.Player))) return false;

        const text = String(row.textContent || "").replace(/\s+/g, " ").trim();
        const parsed = parseRenderedProtectAction(text);
        if (!parsed) return false;

        processedProtectChatRows.add(row);
        if (!offerTargetIsLocalPlayer(parsed.targetName)) return false;

        const resolvedSource = resolveRenderedOfferSource(row, parsed.sourceName);
        if (balanceRenderedSourceIsLocal(resolvedSource.sourceName, resolvedSource.sourceMember)) return false;

        return triggerProtectReaction(resolvedSource.sourceName, `rendered ${parsed.verb}`);
    }

    function animatePetting() {
        const item = getHeld(window.Player);
        if (!isOurs(item) || activeBalanceHeadSession || activeHideBehindSession || activeProtectSession || activeIdleAnimationSession) return false;
        const layerName = getActivePlushLayerName(item);
        const base = readActivePlushLayerTransform(item);
        if (!layerName || !base) return false;

        const generation = ++petAnimationGeneration;
        const frames = [
            { delay: 0, dy: -3, rot: -4 },
            { delay: 90, dy: -6, rot: 4 },
            { delay: 180, dy: -3, rot: -3 },
            { delay: 270, dy: 0, rot: 0 },
        ];

        for (const frame of frames) {
            window.setTimeout(() => {
                if (generation !== petAnimationGeneration) return;
                const current = getHeld(window.Player);
                if (!isOurs(current) || getActivePlushLayerName(current) !== layerName) return;
                setPlushLayerTransform(current, layerName, {
                    TranslationY: base.TranslationY + frame.dy,
                    Rotation: base.Rotation + frame.rot,
                });
                rebuildCharacterCanvas(window.Player, "petting animation");
                if (frame.delay === 270) rememberCharacterPlushState(window.Player, current);
            }, frame.delay);
        }
        return true;
    }

    function battleCharacterLabel(C) {
        const name = getCharacterDisplayName(C) || C?.Name || "Someone";
        const member = Number(C?.MemberNumber);
        return Number.isFinite(member) ? `${name}(${member})` : name;
    }

    function resolveBattleTarget(query = "") {
        const playerMember = Number(window.Player?.MemberNumber);
        const focused = window.DialogFocusCharacter;
        if (!query && focused && Number(focused.MemberNumber) !== playerMember) return focused;
        const wanted = String(query || "").trim().toLowerCase();
        const characters = Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [];
        if (/^\d+$/.test(wanted)) return characters.find(C => Number(C?.MemberNumber) === Number(wanted)) || null;
        if (wanted) return characters.find(C => [getCharacterDisplayName(C), C?.Name, C?.Nickname].filter(Boolean).some(n => String(n).toLowerCase().includes(wanted))) || null;
        return null;
    }

    function closeBattleTargetPrompt() {
        try { battleTargetPromptElement?.remove?.(); } catch (_) {}
        battleTargetPromptElement = null;
    }

    function showBattleTargetPrompt() {
        if (!isOurs(getHeld(window.Player))) {
            appendLocalInfoBox("Plushie battle", ["Equip a plushie first."], { compact: true });
            return false;
        }

        closeBattleTargetPrompt();
        const canvas = document.getElementById("MainCanvas") || document.querySelector("canvas");
        const rect = canvas?.getBoundingClientRect?.();
        if (!rect || rect.width <= 0 || rect.height <= 0) return false;

        const root = document.createElement("div");
        root.className = "SubbysPlushiesBattleTargetPrompt";
        Object.assign(root.style, {
            position: "fixed",
            zIndex: "2147483300",
            left: `${Math.round(rect.left + rect.width * 0.50)}px`,
            top: `${Math.round(rect.top + rect.height * 0.50)}px`,
            transform: "translate(-50%, -50%)",
            width: `${Math.max(300, Math.min(430, Math.round(rect.width * 0.30)))}px`,
            boxSizing: "border-box",
            padding: "16px",
            border: "1px solid #8E719A",
            borderRadius: "14px",
            background: "rgba(33,27,43,0.98)",
            color: "#F7EEF5",
            boxShadow: "0 12px 36px rgba(0,0,0,0.48)",
            font: "14px Arial, sans-serif",
        });

        const title = document.createElement("div");
        title.textContent = "Plushie Battle";
        Object.assign(title.style, { fontSize: "20px", fontWeight: "bold", color: "#D8A8C9", marginBottom: "5px" });
        const subtitle = document.createElement("div");
        subtitle.textContent = "Who do you want to battle?";
        Object.assign(subtitle.style, { opacity: "0.82", marginBottom: "10px" });

        const input = document.createElement("input");
        input.type = "text";
        input.placeholder = "Type a player name or member number";
        input.autocomplete = "off";
        Object.assign(input.style, {
            width: "100%",
            boxSizing: "border-box",
            padding: "9px 10px",
            borderRadius: "7px",
            border: "1px solid #8E719A",
            outline: "none",
            background: "#2A2233",
            color: "#F7EEF5",
            font: "14px Arial, sans-serif",
        });

        const suggestions = document.createElement("div");
        Object.assign(suggestions.style, { marginTop: "8px", fontSize: "12px", color: "#C5B6C8", lineHeight: "1.35" });
        const playerMember = Number(window.Player?.MemberNumber);
        const roomNames = (Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [])
            .filter(C => Number(C?.MemberNumber) !== playerMember)
            .map(C => getCharacterDisplayName(C) || C?.Name)
            .filter(Boolean)
            .slice(0, 8);
        suggestions.textContent = roomNames.length ? `In room: ${roomNames.join(", ")}` : "Enter the exact name or member number.";

        const errorText = document.createElement("div");
        Object.assign(errorText.style, { minHeight: "18px", marginTop: "7px", fontSize: "12px", color: "#F0A9B7" });

        const controls = document.createElement("div");
        Object.assign(controls.style, { display: "flex", justifyContent: "flex-end", gap: "8px", marginTop: "8px" });
        const cancel = document.createElement("button");
        const battle = document.createElement("button");
        cancel.type = battle.type = "button";
        cancel.textContent = "Cancel";
        battle.textContent = "Battle";
        for (const button of [cancel, battle]) Object.assign(button.style, {
            minWidth: "92px",
            padding: "7px 12px",
            borderRadius: "8px",
            border: "1px solid #8E719A",
            color: "#F7EEF5",
            cursor: "pointer",
            font: "bold 13px Arial, sans-serif",
        });
        cancel.style.background = "#302638";
        battle.style.background = "#5A4565";

        const submit = () => {
            const query = String(input.value || "").trim();
            if (!query) {
                errorText.textContent = "Type a player name first.";
                input.focus();
                return;
            }
            const target = resolveBattleTarget(query);
            if (!target || Number(target.MemberNumber) === playerMember) {
                errorText.textContent = "I couldn't find that player in the room.";
                input.select();
                return;
            }
            const member = Number(target.MemberNumber);
            closeBattleTargetPrompt();
            challengePlushBattle(Number.isFinite(member) ? String(member) : query);
        };

        cancel.addEventListener("click", closeBattleTargetPrompt);
        battle.addEventListener("click", submit);
        input.addEventListener("keydown", event => {
            if (event.key === "Enter") { event.preventDefault(); submit(); }
            else if (event.key === "Escape") { event.preventDefault(); closeBattleTargetPrompt(); }
        });
        root.addEventListener("pointerdown", event => event.stopPropagation());
        root.append(title, subtitle, input, suggestions, errorText, controls);
        controls.append(cancel, battle);
        document.body.appendChild(root);
        battleTargetPromptElement = root;
        window.setTimeout(() => input.focus(), 0);
        return true;
    }

    function closeBattlePrompt() {
        if (!battlePromptElement) return;
        try { battlePromptElement.querySelectorAll("button").forEach(button => button.disabled = true); } catch (_) {}
        battlePromptElement = null;
    }

    function rollBattleRound() {
        const move = BATTLE_MOVES[Math.floor(Math.random() * BATTLE_MOVES.length)];
        const score = move.min + Math.floor(Math.random() * (move.max - move.min + 1));
        return { move: move.name, score };
    }

    function pruneRecentBattleDataTokens(now = Date.now()) {
        for (const [token, seenAt] of recentBattleDataTokens) {
            if (!Number.isFinite(seenAt) || now - seenAt > BATTLE_DATA_DEDUPE_MS) recentBattleDataTokens.delete(token);
        }
    }

    function normalizeBattleData(value) {
        if (!value || typeof value !== "object" || value.protocol !== BATTLE_DATA_PROTOCOL) return null;
        const challengerMember = Number(value.challengerMember);
        const accepterMember = Number(value.accepterMember);
        if (!Number.isFinite(challengerMember) || !Number.isFinite(accepterMember)) return null;
        const rounds = Array.isArray(value.rounds)
            ? value.rounds.map(line => String(line || "").slice(0, 220)).filter(Boolean).slice(0, 10)
            : [];
        if (!rounds.length) return null;
        return {
            protocol: BATTLE_DATA_PROTOCOL,
            token: String(value.token || ""),
            challengerMember,
            accepterMember,
            challengerName: String(value.challengerName || "Challenger").slice(0, 80),
            accepterName: String(value.accepterName || "Player").slice(0, 80),
            challengerPlush: String(value.challengerPlush || "Plushie").slice(0, 80),
            accepterPlush: String(value.accepterPlush || "Plushie").slice(0, 80),
            challengerScore: Math.max(0, Number(value.challengerScore) || 0),
            accepterScore: Math.max(0, Number(value.accepterScore) || 0),
            accepterResult: ["wins", "loses", "draws"].includes(value.accepterResult) ? value.accepterResult : "draws",
            rounds,
        };
    }

    function battleDataFromAction(data) {
        const dictionary = Array.isArray(data?.Dictionary) ? data.Dictionary : [];
        const entry = dictionary.find(part => part?.Tag === BATTLE_DATA_TAG && typeof part?.Text === "string");
        if (!entry) return null;
        try { return normalizeBattleData(JSON.parse(entry.Text)); } catch (_) { return null; }
    }

    function showBattleRoundSummary(payload) {
        const data = normalizeBattleData(payload);
        if (!data) return false;
        const playerMember = Number(window.Player?.MemberNumber);
        if (playerMember !== data.challengerMember && playerMember !== data.accepterMember) return false;
        const now = Date.now();
        pruneRecentBattleDataTokens(now);
        if (data.token && recentBattleDataTokens.has(data.token)) return true;
        if (data.token) recentBattleDataTokens.set(data.token, now);
        appendLocalInfoBox("Plushie battle", [
            ...data.rounds,
            `Final: ${data.accepterPlush} ${data.accepterScore} — ${data.challengerPlush} ${data.challengerScore}`,
        ], { compact: true, fixedBattleText: true });
        return true;
    }

    function sendBattleResultAction(message, payload) {
        if (typeof window.ServerSend !== "function" || !message) return false;
        const data = normalizeBattleData(payload);
        try {
            window.ServerSend("ChatRoomChat", {
                Content: "Beep",
                Type: "Action",
                Dictionary: [
                    { Tag: "Beep", Text: "msg" },
                    { Tag: "msg", Text: message },
                    ...(data ? [{ Tag: BATTLE_DATA_TAG, Text: JSON.stringify(data) }] : []),
                ],
            });
            if (data) {
                window.ServerSend("ChatRoomChat", {
                    Content: BATTLE_DATA_TAG,
                    Type: "Hidden",
                    Dictionary: [{ Tag: BATTLE_DATA_TAG, Text: JSON.stringify(data) }],
                });
            }
            return true;
        } catch (e) {
            warn("Could not send plushie battle result:", e);
            return false;
        }
    }

    function resolveAcceptedBattle(challengerMember, challengerName, challengerPlush) {
        const playerMember = Number(window.Player?.MemberNumber);
        const playerName = getCharacterDisplayName(window.Player) || "Someone";
        const ownPlush = currentPlushName();
        if (!isOurs(getHeld(window.Player))) {
            appendLocalInfoBox("Plushie battle", ["Equip a Subby's Plushies plushie before accepting the battle."], { compact: true });
            return false;
        }
        let challengerScore = 0, playerScore = 0;
        const roundLines = [];
        for (let i = 1; i <= BATTLE_ROUNDS; i++) {
            const a = rollBattleRound(), b = rollBattleRound();
            challengerScore += a.score; playerScore += b.score;
            roundLines.push(`R${i}: ${challengerPlush} ${a.move} ${a.score} vs ${ownPlush} ${b.move} ${b.score}`);
        }
        const playerResult = playerScore > challengerScore ? "wins" : playerScore < challengerScore ? "loses" : "draws";
        const battleData = {
            protocol: BATTLE_DATA_PROTOCOL,
            token: `battle:${challengerMember}:${playerMember}:${Date.now()}:${Math.random().toString(36).slice(2, 9)}`,
            challengerMember,
            accepterMember: playerMember,
            challengerName,
            accepterName: playerName,
            challengerPlush,
            accepterPlush: ownPlush,
            challengerScore,
            accepterScore: playerScore,
            accepterResult: playerResult,
            rounds: roundLines,
        };
        sendStandaloneActionMessage(`${battleCharacterLabel(window.Player)} accepts ${challengerName}(${challengerMember})'s plushie battle challenge with ${ownPlush}.`);
        showBattleRoundSummary(battleData);
        window.setTimeout(() => {
            sendBattleResultAction(`Plushie battle result: ${playerName}(${playerMember}) [${ownPlush}] ${playerResult} against ${challengerName}(${challengerMember}) [${challengerPlush}]. Scores ${playerScore}-${challengerScore}.`, battleData);
            lastBattleResult = {
                result: playerResult === "wins" ? "win" : playerResult === "loses" ? "loss" : "draw",
                playerScore,
                challengerScore,
                ownPlush,
                challengerPlush,
                rounds: roundLines.slice(),
                token: battleData.token,
                at: new Date().toISOString(),
            };
        }, BATTLE_RESULT_DELAY_MS);
        return true;
    }

    function showBattlePrompt(challengerMember, challengerName, challengerPlush) {
        if (Number(challengerMember) === Number(window.Player?.MemberNumber)) return false;
        if (typeof window.ChatRoomAppendChat !== "function") return false;
        closeBattlePrompt();
        const row = document.createElement("div");
        row.className = "ChatMessage SubbysPlushiesBattlePrompt";
        Object.assign(row.style, {
            margin: "2px 4px",
            padding: "4px 6px",
            border: "1px solid currentColor",
            borderRadius: "5px",
            fontSize: "13px",
            lineHeight: "1.25",
        });
        const msg = document.createElement("div");
        msg.textContent = `${challengerName} challenges you to a plushie battle with ${challengerPlush}!`;
        const controls = document.createElement("div");
        Object.assign(controls.style, { display: "flex", gap: "4px", marginTop: "3px" });
        const accept = document.createElement("button"), decline = document.createElement("button");
        accept.textContent = "Accept"; decline.textContent = "Decline";
        for (const button of [accept, decline]) Object.assign(button.style, { fontSize: "12px", padding: "3px 7px", minHeight: "24px" });
        const decide = accepted => {
            if (!row.isConnected || row.dataset.decided === "true") return;
            if (accepted && !resolveAcceptedBattle(challengerMember, challengerName, challengerPlush)) return;
            row.dataset.decided = "true";
            accept.disabled = decline.disabled = true;
            controls.remove();
            if (!accepted) {
                sendStandaloneActionMessage(`${battleCharacterLabel(window.Player)} declines ${challengerName}(${challengerMember})'s plushie battle challenge.`);
                msg.textContent = "Battle declined.";
            } else msg.textContent = `Battle accepted — resolving ${BATTLE_ROUNDS} round${BATTLE_ROUNDS === 1 ? "" : "s"}...`;
            if (battlePromptElement === row) battlePromptElement = null;
        };
        accept.addEventListener("click", e => { e.preventDefault(); e.stopPropagation(); decide(true); });
        decline.addEventListener("click", e => { e.preventDefault(); e.stopPropagation(); decide(false); });
        controls.append(accept, decline); row.append(msg, controls); window.ChatRoomAppendChat(row);
        battlePromptElement = row;
        return true;
    }

    function challengePlushBattle(targetQuery = "") {
        if (!isOurs(getHeld(window.Player))) {
            appendLocalInfoBox("Plushie battle", ["Equip a plushie first."], { compact: true });
            return false;
        }
        const target = resolveBattleTarget(targetQuery);
        if (!target || Number(target.MemberNumber) === Number(window.Player?.MemberNumber)) {
            appendLocalInfoBox("Plushie battle", ["Focus another character or use /plushiebattle <member number or name>."], { compact: true });
            return false;
        }
        const sourceLabel = battleCharacterLabel(window.Player);
        const targetLabel = battleCharacterLabel(target);
        const plushName = currentPlushName();
        sendStandaloneActionMessage(`${sourceLabel} challenges ${targetLabel} to a plushie battle with ${plushName}.`);
        return true;
    }

    function processBattleAction(data) {
        if (!isChatAction(data)) return false;
        const msg = getDictionaryText(data, "msg") || "";
        let match = msg.match(BATTLE_CHALLENGE_RE);
        if (match) {
            const sourceMember = Number(match[2]), targetMember = Number(match[4]);
            if (targetMember === Number(window.Player?.MemberNumber) && sourceMember !== targetMember) showBattlePrompt(sourceMember, match[1].trim(), match[5].trim());
            return true;
        }

        match = msg.match(BATTLE_RESULT_RE);
        if (match) {
            const battleData = battleDataFromAction(data);
            if (battleData) showBattleRoundSummary(battleData);
            const firstMember = Number(match[2]), firstResult = match[4].toLowerCase(), secondMember = Number(match[6]);
            const playerMember = Number(window.Player?.MemberNumber);
            if (playerMember !== firstMember && playerMember !== secondMember) return true;
            let result = "draw";
            if (playerMember === firstMember) result = firstResult === "wins" ? "win" : firstResult === "loses" ? "loss" : "draw";
            else result = firstResult === "wins" ? "loss" : firstResult === "loses" ? "win" : "draw";
            const playerIsFirst = playerMember === firstMember;
            const ownPlush = playerIsFirst ? match[3].trim() : match[7].trim();
            const opponent = playerIsFirst ? match[5].trim() : match[1].trim();
            const opponentMember = playerIsFirst ? secondMember : firstMember;
            const opponentPlush = playerIsFirst ? match[7].trim() : match[3].trim();
            const ownScore = Number(playerIsFirst ? match[8] : match[9]) || 0;
            const opponentScore = Number(playerIsFirst ? match[9] : match[8]) || 0;
            recordStat("battlePlayed", 1, { plushName: ownPlush });
            recordStat(result === "win" ? "battleWin" : result === "loss" ? "battleLoss" : "battleDraw", 1, { plushName: ownPlush });
            trackBattleAchievement(result, ownScore, opponentScore);
            const historyEntry = recordBattleHistory({
                at: Date.now(), opponent, opponentMember, plush: ownPlush, opponentPlush,
                score: ownScore, opponentScore, result,
            });
            lastBattleResult = {
                result,
                text: msg,
                at: new Date().toISOString(),
                historyEntry,
                rounds: battleData?.rounds?.slice() || lastBattleResult?.rounds || [],
                token: battleData?.token || lastBattleResult?.token || null,
            };
            emitPluginApiEvent("battle", historyEntry);
            return true;
        }

        return false;
    }

    function compareVersions(a, b) {
        const parse = value => String(value || "0").split(/[.-]/).map(part => /^\d+$/.test(part) ? Number(part) : part);
        const A = parse(a), B = parse(b), length = Math.max(A.length, B.length);
        for (let i = 0; i < length; i++) {
            const av = A[i] ?? 0, bv = B[i] ?? 0;
            if (typeof av === "number" && typeof bv === "number") {
                if (av !== bv) return av > bv ? 1 : -1;
            } else {
                const cmp = String(av).localeCompare(String(bv));
                if (cmp) return cmp > 0 ? 1 : -1;
            }
        }
        return 0;
    }

    function versionFromScriptText(text) {
        const match = String(text || "").match(/@version\s+([^\s]+)/i) || String(text || "").match(/const\s+VERSION\s*=\s*["']([^"']+)/);
        return match?.[1] || null;
    }

    async function fetchTextWithTimeout(url, timeoutMs = 6000) {
        const controller = typeof AbortController === "function" ? new AbortController() : null;
        const timer = controller ? window.setTimeout(() => controller.abort(), timeoutMs) : null;
        try {
            const response = await fetch(url, { cache: "no-store", ...(controller ? { signal: controller.signal } : {}) });
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            return await response.text();
        } finally {
            if (timer != null) window.clearTimeout(timer);
        }
    }

    function gitDataPlainObject(value) {
        return !!value && typeof value === "object" && !Array.isArray(value);
    }

    function gitDataFinite(value, fallback, min = -Infinity, max = Infinity) {
        const number = Number(value);
        return Number.isFinite(number) && number >= min && number <= max ? number : fallback;
    }

    function gitDataString(value, fallback = "", maxLength = 8000) {
        if (typeof value !== "string") return fallback;
        const normalized = value.trim();
        return normalized ? normalized.slice(0, maxLength) : fallback;
    }

    function gitDataStringArray(value, fallback = [], maxItems = 100, maxLength = 180) {
        if (!Array.isArray(value)) return [...fallback];
        const result = [];
        for (const entry of value.slice(0, maxItems)) {
            const text = gitDataString(entry, "", maxLength);
            if (text) result.push(text);
        }
        return result.length ? result : [...fallback];
    }

    function escapeRegExp(value) {
        return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    }

    function protectVerbForms(verbs) {
        const forms = new Set();
        for (const raw of verbs) {
            const verb = String(raw || "").trim().toLowerCase();
            if (!/^[a-z]+$/.test(verb)) continue;
            forms.add(verb);
            forms.add(`${verb}s`);
            forms.add(`${verb}es`);
            if (verb.endsWith("e")) forms.add(`${verb.slice(0, -1)}es`);
        }
        return [...forms].sort((a, b) => b.length - a.length);
    }

    function rebuildProtectRenderRegex(verbs) {
        const forms = protectVerbForms(verbs);
        if (!forms.length) return false;
        const alternation = forms.map(escapeRegExp).join("|");
        PROTECT_RENDER_VERB_RE = new RegExp(`\\b(${alternation})\\b`, "i");
        PROTECT_RENDER_ACTION_RE = new RegExp(`(.+?)\\s+(${alternation})\\s+(.+?)(?:'s|')\\s+[^.)]+`, "i");
        return true;
    }

    function cuddleQueenEncounterValue() {
        if (Number(window.Player?.MemberNumber) === CUDDLE_QUEEN_MEMBER_NUMBER) return 1;
        if (window.CurrentScreen !== "ChatRoom") return 0;
        const characters = Array.isArray(window.ChatRoomCharacter) ? window.ChatRoomCharacter : [];
        return characters.some(C => Number(C?.MemberNumber) === CUDDLE_QUEEN_MEMBER_NUMBER) ? 1 : 0;
    }

    function currentChatRoomName() {
        const candidates = [
            window.ChatRoomData?.Name,
            window.ChatRoomData?.RoomName,
            window.ChatRoomData?.DisplayName,
        ];
        const value = candidates.find(entry => typeof entry === "string" && entry.trim());
        return String(value || "").trim();
    }

    function cuddleRoomJoinedValue() {
        if (window.CurrentScreen !== "ChatRoom") return 0;
        const normalize = value => String(value || "")
            .replace(/[\u2018\u2019]/g, "'")
            .replace(/\s+/g, " ")
            .trim()
            .toLowerCase();
        return normalize(currentChatRoomName()) === normalize(CUDDLE_ROOM_NAME) ? 1 : 0;
    }

    function ensureRequiredAchievements(definitions) {
        const list = Array.isArray(definitions) ? [...definitions] : [];
        if (!list.some(entry => entry?.id === "meet_cuddle_queen")) {
            list.push(Object.freeze({
                id: "meet_cuddle_queen",
                name: "Meet the cuddle queen",
                description: "Share a chat room with the Cuddle Queen.",
                condition: Object.freeze({ metric: "cuddleQueenEncounter", operator: ">=", value: 1 }),
                test: stats => cuddleQueenEncounterValue() >= 1,
            }));
        }
        if (!list.some(entry => entry?.id === "join_cuddle_room")) {
            list.push(Object.freeze({
                id: "join_cuddle_room",
                name: "Join the cuddle room",
                description: "Join Subbycat's place.",
                condition: Object.freeze({ metric: "cuddleRoomJoined", operator: ">=", value: 1 }),
                test: stats => cuddleRoomJoinedValue() >= 1,
            }));
        }
        if (!list.some(entry => entry?.id === "bestie_material")) {
            list.push(Object.freeze({
                id: "bestie_material",
                name: "Bestie Material",
                description: "Reach Bestie relationship with any plushie.",
                condition: Object.freeze({ metric: "maxRelationshipInteractions", operator: ">=", value: 50 }),
                test: stats => maxRelationshipInteractions() >= 50,
            }));
        }
        if (!list.some(entry => entry?.id === "stitched_together")) {
            list.push(Object.freeze({
                id: "stitched_together",
                name: "Stitched Together",
                description: "Reach Bonded relationship with any plushie.",
                condition: Object.freeze({ metric: "maxRelationshipInteractions", operator: ">=", value: 100 }),
                test: stats => maxRelationshipInteractions() >= 100,
            }));
        }
        return Object.freeze(list);
    }

    function achievementMetricValue(stats, metric) {
        if (metric === "affectionCount") return statAffectionCount(stats);
        if (metric === "uniquePlushiesUsed") return Object.keys(stats?.plushesUsed || {}).length;
        if (metric === "cuddleQueenEncounter") return cuddleQueenEncounterValue();
        if (metric === "cuddleRoomJoined") return cuddleRoomJoinedValue();
        if (metric === "maxRelationshipInteractions") return maxRelationshipInteractions();
        if (metric === "friendPlushies") return countPlushiesAtRelationship("Friend");
        if (metric === "bondedPlushies") return countPlushiesAtRelationship("Bonded");
        if (metric === "maxMoodScore") return maxPlushMoodScore();
        if (metric === "maxInteractionDays") return maxInteractionDaysForOnePlush(stats);
        if (metric === "uniqueRoomsVisited") return objectKeyCount(getAchievementProgress(stats).roomsVisited);
        if (metric === "uniquePlayersInteracted") return objectKeyCount(getAchievementProgress(stats).playersInteracted);
        if (metric === "bonkedPlushies") return objectKeyCount(getAchievementProgress(stats).bonkedPlushies);
        const parts = String(metric || "").split(".").filter(Boolean);
        let value = stats;
        for (const part of parts) {
            if (!gitDataPlainObject(value) && typeof value !== "object") return 0;
            value = value?.[part];
        }
        return Number(value) || 0;
    }

    function achievementConditionPasses(stats, condition) {
        if (!gitDataPlainObject(condition)) return false;
        const actual = achievementMetricValue(stats, condition.metric);
        const expected = Number(condition.value);
        if (!Number.isFinite(expected)) return false;
        switch (condition.operator) {
            case ">=": return actual >= expected;
            case "<=": return actual <= expected;
            case ">": return actual > expected;
            case "<": return actual < expected;
            case "==":
            case "=": return actual === expected;
            default: return false;
        }
    }

    function normalizeLoreLookupKey(value) {
        return String(value || "")
            .toLowerCase()
            .replace(/&/g, "and")
            .replace(/lyly/g, "lily")
            .replace(/kyutie/g, "kyu")
            .replace(/[^a-z0-9]/g, "");
    }

    function getPlushLore(name) {
        const direct = PLUSH_LORE?.[name];
        if (direct) return direct;
        const wanted = normalizeLoreLookupKey(name);
        if (!wanted) return null;
        for (const [key, value] of Object.entries(PLUSH_LORE || {})) {
            if (normalizeLoreLookupKey(key) === wanted) return value;
        }
        return null;
    }

    function normalizeGitDataFile(fileName, payload) {
        if (!gitDataPlainObject(payload) || Number(payload.schemaVersion) !== GIT_DATA_SCHEMA_VERSION) return null;

        if (fileName === "lore.json") {
            if (!gitDataPlainObject(payload.lore)) return null;
            const lore = Object.create(null);
            for (const [key, value] of Object.entries(payload.lore)) {
                if (!gitDataPlainObject(value)) continue;
                const title = gitDataString(value.title, "", 180);
                const text = gitDataString(value.text, "", 12000);
                if (title && text) lore[String(key).slice(0, 180)] = Object.freeze({ title, text });
            }
            return Object.keys(lore).length ? { lore: Object.freeze(lore) } : null;
        }

        if (fileName === "speech.json") {
            if (!gitDataPlainObject(payload.moodBuckets)) return null;
            const buckets = Object.create(null);
            for (const key of ["grumpy", "calm", "happy", "adoring"]) {
                const bucket = payload.moodBuckets[key];
                if (!gitDataPlainObject(bucket)) continue;
                const lines = gitDataStringArray(bucket.lines, [], 80, 120);
                if (lines.length) buckets[key] = Object.freeze(lines);
            }
            if (!Object.keys(buckets).length) return null;
            const triggers = gitDataPlainObject(payload.automaticTriggers) ? payload.automaticTriggers : {};
            return {
                bubbleDurationMs: gitDataFinite(payload.bubbleDurationMs, SPEECH_BUBBLE_DURATION_MS, 500, 20000),
                bubbleYOffsetCssPx: gitDataFinite(payload.bubbleYOffsetCssPx, SPEECH_BUBBLE_Y_OFFSET_CSS_PX, -200, 200),
                buckets: Object.freeze(buckets),
                interactionActions: Object.freeze(gitDataStringArray(triggers.interactionActions, SPEECH_INTERACTION_ACTIONS, 50, 80)),
                interactionChance: gitDataFinite(triggers.interactionChance, SPEECH_INTERACTION_CHANCE, 0, 1),
                interactionDelayMs: gitDataFinite(triggers.interactionDelayMs, SPEECH_INTERACTION_DELAY_MS, 0, 5000),
                idleChance: gitDataFinite(triggers.idleChance, SPEECH_IDLE_CHANCE, 0, 1),
            };
        }

        if (fileName === "moods.json") {
            const labels = Array.isArray(payload.labels)
                ? payload.labels.map(entry => ({
                    maxScore: gitDataFinite(entry?.maxScore, NaN, 0, 1000),
                    label: gitDataString(entry?.label, "", 80),
                })).filter(entry => Number.isFinite(entry.maxScore) && entry.label).sort((a, b) => a.maxScore - b.maxScore)
                : [];
            const deltas = gitDataPlainObject(payload.interactionDeltas) ? Object.create(null) : null;
            if (deltas) {
                for (const [key, value] of Object.entries(payload.interactionDeltas)) {
                    const amount = Number(value);
                    if (Number.isFinite(amount) && Math.abs(amount) <= 1000) deltas[key] = amount;
                }
            }
            if (!labels.length || !deltas || !Object.keys(deltas).length) return null;
            const min = gitDataFinite(payload.minimumScore, MOOD_MIN_SCORE, -1000, 1000);
            const max = gitDataFinite(payload.maximumScore, MOOD_MAX_SCORE, min, 2000);
            return {
                defaultScore: gitDataFinite(payload.defaultScore, MOOD_DEFAULT_SCORE, min, max),
                minimumScore: min,
                maximumScore: max,
                driftTarget: gitDataFinite(payload.driftTarget, MOOD_DRIFT_TARGET, min, max),
                driftStep: gitDataFinite(payload.driftStep, MOOD_DRIFT_STEP, 1, 100),
                driftEveryMs: gitDataFinite(payload.driftEveryMinutes, MOOD_DRIFT_EVERY_MS / 60000, 1, 10080) * 60000,
                labels: Object.freeze(labels.map(Object.freeze)),
                deltas: Object.freeze(deltas),
            };
        }

        if (fileName === "achievements.json") {
            if (!Array.isArray(payload.achievements)) return null;
            const definitions = [];
            for (const entry of payload.achievements.slice(0, 100)) {
                if (!gitDataPlainObject(entry) || !gitDataPlainObject(entry.condition)) continue;
                const id = gitDataString(entry.id, "", 80);
                const name = gitDataString(entry.name, "", 120);
                const description = gitDataString(entry.description, "", 500);
                const metric = gitDataString(entry.condition.metric, "", 120);
                const operator = gitDataString(entry.condition.operator, "", 4);
                const value = Number(entry.condition.value);
                if (!id || !name || !description || !metric || ![">=", "<=", ">", "<", "==", "="].includes(operator) || !Number.isFinite(value)) continue;
                const condition = Object.freeze({ metric, operator, value });
                definitions.push(Object.freeze({ id, name, description, hidden: !!entry.hidden, condition, test: stats => achievementConditionPasses(stats, condition) }));
            }
            if (!definitions.length) return null;
            return {
                affectionActionKeys: Object.freeze(gitDataStringArray(payload.affectionActionKeys, AFFECTION_ACTION_KEYS, 80, 80)),
                achievements: Object.freeze(definitions),
            };
        }

        if (fileName === "battle.json") {
            if (!Array.isArray(payload.moves)) return null;
            const moves = [];
            for (const entry of payload.moves.slice(0, 40)) {
                const name = gitDataString(entry?.name, "", 120);
                const min = Number(entry?.min), max = Number(entry?.max);
                if (!name || !Number.isFinite(min) || !Number.isFinite(max) || max < min || Math.abs(min) > 10000 || Math.abs(max) > 10000) continue;
                moves.push(Object.freeze({ name, min, max }));
            }
            if (!moves.length) return null;
            return {
                rounds: Math.round(gitDataFinite(payload.rounds, BATTLE_ROUNDS, 1, 10)),
                resultDelayMs: gitDataFinite(payload.resultDelayMs, BATTLE_RESULT_DELAY_MS, 0, 10000),
                moves: Object.freeze(moves),
            };
        }

        if (fileName === "commands.json") {
            if (!Array.isArray(payload.groups)) return null;
            const groups = [];
            for (const group of payload.groups.slice(0, 30)) {
                const title = gitDataString(group?.title, "", 120);
                if (!title || !Array.isArray(group?.commands)) continue;
                const commands = [];
                for (const entry of group.commands.slice(0, 100)) {
                    const command = gitDataString(entry?.command, "", 180);
                    const description = gitDataString(entry?.description, "", 600);
                    if (!command.startsWith("/") || !description || /^\/plushiesnap(?:\s|$)/i.test(command)) continue;
                    commands.push(Object.freeze({ command, description }));
                }
                if (commands.length) groups.push(Object.freeze({ title, commands: Object.freeze(commands) }));
            }
            return groups.length ? { groups: Object.freeze(groups) } : null;
        }

        if (fileName === "poses.json") {
            const temporary = gitDataPlainObject(payload.temporaryPoses) ? payload.temporaryPoses : {};
            const normalizePose = (entry, fallbackDuration, fallbackTransform) => {
                if (!gitDataPlainObject(entry)) return { durationMs: fallbackDuration, transform: fallbackTransform };
                return {
                    durationMs: gitDataFinite(entry.durationMs, fallbackDuration, 250, 60000),
                    transform: Object.freeze({
                        TranslationX: gitDataFinite(entry.TranslationX, fallbackTransform.TranslationX, -1000, 1000),
                        TranslationY: gitDataFinite(entry.TranslationY, fallbackTransform.TranslationY, -1000, 1000),
                        Rotation: gitDataFinite(entry.Rotation, fallbackTransform.Rotation, -360, 360),
                    }),
                };
            };
            return {
                balanceHead: normalizePose(temporary.balanceHead, BALANCE_HEAD_DURATION_MS, BALANCE_HEAD_TRANSFORM),
                hideBehind: normalizePose(temporary.hideBehindFace, HIDE_BEHIND_DURATION_MS, HIDE_BEHIND_FACE_TRANSFORM),
            };
        }

        if (fileName === "defaults.json") {
            if (!gitDataPlainObject(payload.featureDefaults)) return null;
            const current = FEATURE_DEFAULTS;
            const next = {};
            for (const key of Object.keys(current)) {
                next[key] = Object.prototype.hasOwnProperty.call(payload.featureDefaults, key)
                    ? !!payload.featureDefaults[key]
                    : !!current[key];
            }
            return { featureDefaults: Object.freeze(next) };
        }

        if (fileName === "idle.json") {
            if (!Array.isArray(payload.frames)) return null;
            const frames = [];
            for (const entry of payload.frames.slice(0, 30)) {
                const delayMs = Number(entry?.delayMs), deltaY = Number(entry?.deltaY), rotationMultiplier = Number(entry?.rotationMultiplier);
                if (!Number.isFinite(delayMs) || !Number.isFinite(deltaY) || !Number.isFinite(rotationMultiplier)) continue;
                frames.push(Object.freeze({
                    delayMs: Math.max(0, Math.min(10000, delayMs)),
                    deltaY: Math.max(-100, Math.min(100, deltaY)),
                    rotationMultiplier: Math.max(-50, Math.min(50, rotationMultiplier)),
                    restore: !!entry?.restore,
                }));
            }
            if (!frames.length || !frames.some(frame => frame.restore)) return null;
            return {
                minDelayMs: gitDataFinite(payload.minDelayMs, IDLE_MIN_DELAY_MS, 1000, 600000),
                maxDelayMs: gitDataFinite(payload.maxDelayMs, IDLE_MAX_DELAY_MS, 1000, 600000),
                frames: Object.freeze(frames.sort((a, b) => a.delayMs - b.delayMs)),
                speechChanceAfterAnimation: gitDataFinite(payload.speechChanceAfterAnimation, SPEECH_IDLE_CHANCE, 0, 1),
            };
        }

        if (fileName === "protect.json") {
            const keywords = gitDataStringArray(payload.keywords, PROTECT_KEYWORDS, 100, 40)
                .map(value => value.toLowerCase())
                .filter(value => !/^pokes?$/.test(value));
            for (const required of ["boop", "bap"]) if (!keywords.includes(required)) keywords.push(required);

            const verbs = gitDataStringArray(payload.renderVerbs, keywords, 100, 40)
                .map(value => value.toLowerCase())
                .filter(value => !/^pokes?$/.test(value));
            for (const required of ["boop", "bap"]) if (!verbs.includes(required)) verbs.push(required);

            const jealous = gitDataStringArray(payload.jealousActivityKeywords, JEALOUS_ACTIVITY_KEYWORDS, 100, 40)
                .map(value => value.toLowerCase());
            if (!jealous.includes("poke")) jealous.push("poke");
            const transform = gitDataPlainObject(payload.transform) ? Object.freeze({
                TranslationX: gitDataFinite(payload.transform.TranslationX, PROTECT_TRANSFORM.TranslationX, -1000, 1000),
                TranslationY: gitDataFinite(payload.transform.TranslationY, PROTECT_TRANSFORM.TranslationY, -1000, 1000),
                Rotation: gitDataFinite(payload.transform.Rotation, PROTECT_TRANSFORM.Rotation, -360, 360),
            }) : PROTECT_TRANSFORM;
            return {
                durationMs: gitDataFinite(payload.durationMs, PROTECT_DURATION_MS, 250, 60000),
                transform,
                keywords: Object.freeze(keywords),
                renderVerbs: Object.freeze(verbs),
                jealousKeywords: Object.freeze(jealous),
            };
        }

        if (fileName === "relationships.json") {
            if (!Array.isArray(payload.levels)) return null;
            const levels = payload.levels
                .slice(0, 20)
                .map(entry => ({
                    name: gitDataString(entry?.name, "", 80),
                    minInteractions: Math.max(0, Math.floor(gitDataFinite(entry?.minInteractions, NaN, 0, 1000000))),
                }))
                .filter(entry => entry.name && Number.isFinite(entry.minInteractions))
                .sort((a, b) => a.minInteractions - b.minInteractions);
            if (!levels.length || levels[0].minInteractions !== 0) return null;
            const speechLines = Object.create(null);
            if (gitDataPlainObject(payload.speechLines)) {
                for (const level of levels) {
                    const lines = gitDataStringArray(payload.speechLines[level.name], [], 40, 120);
                    if (lines.length) speechLines[level.name] = Object.freeze(lines);
                }
            }
            return {
                sleepyAfterMs: gitDataFinite(payload.sleepyAfterMinutes, SLEEPY_AFTER_MS / 60000, 1, 10080) * 60000,
                levels: Object.freeze(levels.map(Object.freeze)),
                speechLines: Object.freeze(speechLines),
            };
        }

        return null;
    }

    function applyNormalizedGitDataFile(fileName, normalized) {
        if (!normalized) return false;
        if (fileName === "lore.json") {
            const mergedLore = { ...normalized.lore, ...BUILTIN_PLUSH_LORE };
            for (const [name, entry] of Object.entries(BUILTIN_PLUSH_LORE)) {
                if (entry.hidden && !entry.text) {
                    const wanted = normalizeLoreLookupKey(name);
                    const published = Object.entries(normalized.lore).find(([key, value]) =>
                        normalizeLoreLookupKey(key) === wanted && !!value?.text);
                    if (published) mergedLore[name] = published[1];
                }
            }
            PLUSH_LORE = Object.freeze(mergedLore);
        }
        else if (fileName === "speech.json") {
            SPEECH_BUBBLE_DURATION_MS = normalized.bubbleDurationMs;
            SPEECH_BUBBLE_Y_OFFSET_CSS_PX = normalized.bubbleYOffsetCssPx;
            PLUSH_SPEECH = normalized.buckets;
            SPEECH_INTERACTION_ACTIONS = normalized.interactionActions;
            SPEECH_INTERACTION_CHANCE = normalized.interactionChance;
            SPEECH_INTERACTION_DELAY_MS = normalized.interactionDelayMs;
            SPEECH_IDLE_CHANCE = normalized.idleChance;
        } else if (fileName === "moods.json") {
            MOOD_DEFAULT_SCORE = normalized.defaultScore;
            MOOD_MIN_SCORE = normalized.minimumScore;
            MOOD_MAX_SCORE = normalized.maximumScore;
            MOOD_DRIFT_TARGET = 0;
            MOOD_DRIFT_STEP = 1;
            MOOD_DRIFT_EVERY_MS = 8 * 60 * 60 * 1000;
            MOOD_LABELS = normalized.labels;
            MOOD_DELTAS = normalized.deltas;
        } else if (fileName === "achievements.json") {
            AFFECTION_ACTION_KEYS = normalized.affectionActionKeys;
            const builtIns = new Map(BUILTIN_ACHIEVEMENTS.map(entry => [entry.id, entry]));
            const merged = [...BUILTIN_ACHIEVEMENTS];
            for (const external of normalized.achievements) {
                if (!builtIns.has(external.id)) merged.push(external);
            }
            ACHIEVEMENTS = ensureRequiredAchievements(Object.freeze(merged));
        } else if (fileName === "battle.json") {
            BATTLE_ROUNDS = normalized.rounds;
            BATTLE_RESULT_DELAY_MS = normalized.resultDelayMs;
            BATTLE_MOVES = normalized.moves;
        } else if (fileName === "commands.json") {
            EXTENSIONS_COMMAND_GROUPS = normalized.groups;
            plushieCommandAutocompleteCache = null;
        } else if (fileName === "poses.json") {
            BALANCE_HEAD_DURATION_MS = normalized.balanceHead.durationMs;
            BALANCE_HEAD_TRANSFORM = normalized.balanceHead.transform;
            HIDE_BEHIND_DURATION_MS = normalized.hideBehind.durationMs;
            HIDE_BEHIND_FACE_TRANSFORM = normalized.hideBehind.transform;
        } else if (fileName === "defaults.json") {
            FEATURE_DEFAULTS = Object.freeze({
                ...normalized.featureDefaults,
                ignorePoseChangingEmotes: Object.prototype.hasOwnProperty.call(normalized.featureDefaults, "ignorePoseChangingEmotes")
                    ? !!normalized.featureDefaults.ignorePoseChangingEmotes
                    : false,
                highlightMyName: false,
            });
        } else if (fileName === "idle.json") {
            IDLE_MIN_DELAY_MS = Math.min(normalized.minDelayMs, normalized.maxDelayMs);
            IDLE_MAX_DELAY_MS = Math.max(normalized.minDelayMs, normalized.maxDelayMs);
            IDLE_ANIMATION_FRAMES = normalized.frames;
        } else if (fileName === "protect.json") {
            PROTECT_DURATION_MS = normalized.durationMs;
            PROTECT_TRANSFORM = normalized.transform;
            PROTECT_KEYWORDS = normalized.keywords;
            JEALOUS_ACTIVITY_KEYWORDS = normalized.jealousKeywords;
            rebuildProtectRenderRegex(normalized.renderVerbs);
        } else if (fileName === "relationships.json") {
            RELATIONSHIP_LEVELS = normalized.levels;
            RELATIONSHIP_SPEECH = normalized.speechLines;
            SLEEPY_AFTER_MS = normalized.sleepyAfterMs;
            refreshPlushStatusIcon();
        } else return false;
        return true;
    }

    function validateAndApplyGitDataFile(fileName, payload) {
        const normalized = normalizeGitDataFile(fileName, payload);
        return normalized ? applyNormalizedGitDataFile(fileName, normalized) : false;
    }

    function readGitDataCache() {
        try {
            const raw = window.localStorage?.getItem(GIT_DATA_CACHE_KEY);
            if (!raw) return null;
            const parsed = JSON.parse(raw);
            return gitDataPlainObject(parsed) && Number(parsed.schemaVersion) === GIT_DATA_SCHEMA_VERSION ? parsed : null;
        } catch (_) {
            return null;
        }
    }

    function writeGitDataCache(cache) {
        try {
            window.localStorage?.setItem(GIT_DATA_CACHE_KEY, JSON.stringify(cache));
            return true;
        } catch (_) {
            return false;
        }
    }

    function loadCachedGitData() {
        const cache = readGitDataCache();
        if (!cache || !gitDataPlainObject(cache.files)) return false;
        const loaded = [];
        for (const fileName of GIT_DATA_FILES) {
            if (validateAndApplyGitDataFile(fileName, cache.files[fileName])) loaded.push(fileName);
        }
        if (!loaded.length) return false;
        gitDataState = {
            ...gitDataState,
            source: "cache",
            loadedFiles: loaded,
            cachedAt: Number(cache.savedAt) || null,
            indexPluginVersion: typeof cache.indexPluginVersion === "string" ? cache.indexPluginVersion : null,
            lastError: null,
        };
        log(`Loaded ${loaded.length} validated Git data file${loaded.length === 1 ? "" : "s"} from local cache.`);
        return true;
    }

    function gitDataPathFromIndex(index, fileName) {
        const candidate = index?.files?.[fileName]?.path;
        const path = typeof candidate === "string" && candidate.trim() ? candidate.trim() : `data/${fileName}`;
        if (!/^data\/[A-Za-z0-9._/-]+\.json$/.test(path) || path.includes("..")) return null;
        return path;
    }

    async function fetchGitDataJson(url, timeoutMs = 8000) {
        const text = await fetchTextWithTimeout(url, timeoutMs);
        return JSON.parse(text);
    }

    function gitDataStatusText() {
        const count = gitDataState.loadedFiles?.length || 0;
        if (gitDataState.source === "github") return `GitHub live (${count}/${GIT_DATA_FILES.length} files)`;
        if (gitDataState.source === "cache") return `Cached Git data (${count}/${GIT_DATA_FILES.length} files)`;
        return "Built-in fallback";
    }

    async function refreshGitDataFromGitHub({ force = false, silent = true, includeLore = false } = {}) {
        if (gitDataRefreshPromise) return gitDataRefreshPromise;
        if (!force) {
            let lastCheck = 0;
            try { lastCheck = Number(window.localStorage?.getItem(GIT_DATA_LAST_CHECK_KEY)) || 0; } catch (_) {}
            if (Date.now() - lastCheck < GIT_DATA_REFRESH_INTERVAL_MS && gitDataState.loadedFiles.length) return { ...gitDataState };
        }

        gitDataRefreshPromise = (async () => {
            try {
                const stamp = Date.now();
                const index = await fetchGitDataJson(`${DATA_INDEX_URL}?t=${stamp}`);
                if (!gitDataPlainObject(index) || Number(index.schemaVersion) !== GIT_DATA_SCHEMA_VERSION || !gitDataPlainObject(index.files)) {
                    throw new Error("Unsupported or invalid data/index.json schema.");
                }

                const previous = readGitDataCache();
                const cachedFiles = gitDataPlainObject(previous?.files) ? { ...previous.files } : {};
                const loaded = [];
                const failures = [];

                const results = await Promise.allSettled(GIT_DATA_FILES.filter(fileName => includeLore || fileName !== "lore.json").map(async fileName => {
                    const path = gitDataPathFromIndex(index, fileName);
                    if (!path) throw new Error(`${fileName}: invalid path in data/index.json`);
                    const payload = await fetchGitDataJson(`${REPOSITORY_RAW_ROOT}/${path}?t=${stamp}`);
                    return { fileName, payload };
                }));

                const fetched = new Map();
                for (const result of results) {
                    if (result.status === "fulfilled") fetched.set(result.value.fileName, result.value.payload);
                    else failures.push(String(result.reason || "unknown failure"));
                }

                for (const fileName of GIT_DATA_FILES) {
                    if (!fetched.has(fileName)) continue;
                    const payload = fetched.get(fileName);
                    if (!validateAndApplyGitDataFile(fileName, payload)) {
                        failures.push(`${fileName}: validation failed`);
                        continue;
                    }
                    loaded.push(fileName);
                    cachedFiles[fileName] = payload;
                }

                if (!loaded.length) throw new Error(failures[0] || "No Git data files could be loaded.");

                const savedAt = Date.now();
                writeGitDataCache({
                    schemaVersion: GIT_DATA_SCHEMA_VERSION,
                    savedAt,
                    indexPluginVersion: typeof index.pluginVersion === "string" ? index.pluginVersion : null,
                    files: cachedFiles,
                });
                try { window.localStorage?.setItem(GIT_DATA_LAST_CHECK_KEY, String(savedAt)); } catch (_) {}

                gitDataState = {
                    source: "github",
                    loadedFiles: [...new Set([...(gitDataState.loadedFiles || []), ...loaded])],
                    cachedAt: savedAt,
                    refreshedAt: savedAt,
                    indexPluginVersion: typeof index.pluginVersion === "string" ? index.pluginVersion : null,
                    lastError: failures.length ? `${failures.length} file(s) kept their cached/fallback copy.` : null,
                };

                if (featureSettingsState == null) {
                }
                if (speechBubbleElement) positionSpeechBubble();
                if (extensionsPanelElement?.isConnected) renderExtensionsPanel();
                log(`Refreshed ${loaded.length}/${GIT_DATA_FILES.length} validated Git data files.`, failures.length ? failures : "");
                if (!silent) appendLocalInfoBox("Git data", [gitDataStatusText(), failures.length ? `${failures.length} file(s) used cache/fallback.` : "All supported data files validated."]);
                return { ...gitDataState };
            } catch (e) {
                gitDataState = { ...gitDataState, lastError: String(e) };
                try { window.localStorage?.setItem(GIT_DATA_LAST_CHECK_KEY, String(Date.now())); } catch (_) {}
                warn("Git data refresh failed; keeping validated cache/built-in fallbacks:", e);
                if (!silent) appendLocalInfoBox("Git data", ["Refresh failed; the addon kept its last-known-good cache/built-in fallbacks.", String(e)]);
                return { ...gitDataState };
            } finally {
                gitDataRefreshPromise = null;
            }
        })();
        return gitDataRefreshPromise;
    }

    // Lore is fetched on first inspection, not during every startup data refresh.
    // Local cached lore and built-in stories remain usable offline immediately.
    let onDemandLorePromise = null;
    let onDemandLoreFetched = false;
    let onDemandLoreRetryAfter = 0;
    async function ensureRemotePlushLore() {
        if (onDemandLorePromise) return onDemandLorePromise;
        if (Date.now() < onDemandLoreRetryAfter) return false;
        if (onDemandLoreFetched) return true;
        onDemandLorePromise = (async () => {
            try {
                const index = await fetchGitDataJson(`${DATA_INDEX_URL}?t=${Date.now()}`);
                if (!gitDataPlainObject(index) || Number(index.schemaVersion) !== GIT_DATA_SCHEMA_VERSION)
                    throw new Error("Invalid lore index");
                const path = gitDataPathFromIndex(index, "lore.json");
                if (!path) throw new Error("No lore.json entry in data/index.json");
                const payload = await fetchGitDataJson(`${REPOSITORY_RAW_ROOT}/${path}?t=${Date.now()}`);
                if (!validateAndApplyGitDataFile("lore.json", payload)) throw new Error("Invalid lore.json data");
                const old = readGitDataCache();
                writeGitDataCache({schemaVersion:GIT_DATA_SCHEMA_VERSION, savedAt:Date.now(),
                    indexPluginVersion:old?.indexPluginVersion || null,
                    files:{...(gitDataPlainObject(old?.files) ? old.files : {}), "lore.json":payload}});
                gitDataState = {...gitDataState, loadedFiles:[...new Set([...(gitDataState.loadedFiles || []), "lore.json"])],
                    lastError:null};
                onDemandLoreFetched = true;
                if (extensionsActiveTab === "lore" && extensionsPanelElement?.isConnected) renderExtensionsPanel();
                return true;
            } catch (e) {
                onDemandLoreRetryAfter = Date.now()+60000;
                warn("On-demand lore fetch failed; using built-in/cached lore:", e); return false;
            }
            finally { onDemandLorePromise = null; }
        })();
        return onDemandLorePromise;
    }

    function showGitDataStatus() {
        const refreshed = gitDataState.refreshedAt ? new Date(gitDataState.refreshedAt).toLocaleString() : "Not this session";
        const cached = gitDataState.cachedAt ? new Date(gitDataState.cachedAt).toLocaleString() : "None";
        appendLocalInfoBox("Git-backed data", [
            `Source: ${gitDataStatusText()}`,
            `Index release version: ${gitDataState.indexPluginVersion || "Unknown"}`,
            `Last live refresh: ${refreshed}`,
            `Last-known-good cache: ${cached}`,
            gitDataState.lastError ? `Note: ${gitDataState.lastError}` : "Validation: OK",
        ]);
        return { ...gitDataState };
    }

    function normalizeReleaseUrl(value) {
        try {
            const url = new URL(String(value || ""), UPDATE_REPOSITORY_PAGE);
            return url.protocol === "https:" ? url.href : UPDATE_REPOSITORY_PAGE;
        } catch (_) {
            return UPDATE_REPOSITORY_PAGE;
        }
    }

    async function resolveLatestAddonVersion() {
        try {
            const text = await fetchTextWithTimeout(`${UPDATE_MANIFEST_URL}?t=${Date.now()}`);
            const manifest = JSON.parse(text);
            if (manifest && typeof manifest.version === "string") {
                return {
                    version: manifest.version,
                    downloadUrl: normalizeReleaseUrl(manifest.downloadUrl),
                    notes: typeof manifest.notes === "string" ? manifest.notes : "",
                    source: "version.json",
                };
            }
        } catch (_) {}

        try {
            const listingText = await fetchTextWithTimeout(`${UPDATE_REPOSITORY_API}&t=${Date.now()}`);
            const listing = JSON.parse(listingText);
            if (!Array.isArray(listing)) return null;
            const candidates = listing
                .filter(entry => typeof entry?.name === "string" && /subby.*plush.*(?:\.user\.js|\.js|\.txt)$/i.test(entry.name))
                .sort((a, b) => Number(/\.user\.js$/i.test(b.name)) - Number(/\.user\.js$/i.test(a.name)));
            for (const entry of candidates.slice(0, 5)) {
                if (typeof entry.download_url !== "string") continue;
                try {
                    const scriptText = await fetchTextWithTimeout(`${entry.download_url}?t=${Date.now()}`);
                    const version = versionFromScriptText(scriptText);
                    if (version) return { version, downloadUrl: normalizeReleaseUrl(entry.html_url || entry.download_url), notes: "", source: entry.name };
                } catch (_) {}
            }
        } catch (_) {}
        return null;
    }

    async function checkForUpdates({ silent = false } = {}) {
        if (updateCheckPromise) return updateCheckPromise;
        updateCheckPromise = (async () => {
            try {
                const latest = await resolveLatestAddonVersion();
                if (!latest) {
                    lastUpdateInfo = { ok: false, version: VERSION, at: new Date().toISOString(), reason: "No release metadata found." };
                    if (!silent) appendLocalInfoBox("Subby's Plushies updater", ["Could not find release metadata in the GitHub repository.", "Add a version.json file or publish the userscript in the repository root to enable update detection."]);
                    return lastUpdateInfo;
                }

                const comparison = compareVersions(latest.version, VERSION);
                lastUpdateInfo = { ok: true, current: VERSION, latest: latest.version, updateAvailable: comparison > 0, ...latest, at: new Date().toISOString() };
                if (comparison > 0) {
                    appendLocalInfoBox("Subby's Plushies update available", [
                        `Installed: v${VERSION} • Latest: v${latest.version}`,
                        latest.notes || "A newer build is available in the repository.",
                        "The updater only checks versions; it never executes downloaded code automatically.",
                    ]);
                } else if (!silent) {
                    appendLocalInfoBox("Subby's Plushies updater", [`v${VERSION} is up to date.`, `Release source: ${latest.source}`]);
                }
                return lastUpdateInfo;
            } catch (e) {
                lastUpdateInfo = { ok: false, version: VERSION, error: String(e), at: new Date().toISOString() };
                if (!silent) appendLocalInfoBox("Subby's Plushies updater", [`Update check failed: ${String(e)}`]);
                return lastUpdateInfo;
            } finally {
                try { window.localStorage?.setItem(UPDATE_CHECK_STORAGE_KEY, String(Date.now())); } catch (_) {}
                updateCheckPromise = null;
            }
        })();
        return updateCheckPromise;
    }

    function scheduleAutomaticUpdateCheck() {
        if (!getFeatureSettings().autoUpdateChecks) return;
        let previous = 0;
        try { previous = Number(window.localStorage?.getItem(UPDATE_CHECK_STORAGE_KEY)) || 0; } catch (_) {}
        if (Date.now() - previous < UPDATE_CHECK_INTERVAL_MS) return;
        window.setTimeout(() => {
            if (getFeatureSettings().autoUpdateChecks) void checkForUpdates({ silent: true });
        }, 5000);
    }

    async function openLatestUpdatePage() {
        const info = lastUpdateInfo?.ok ? lastUpdateInfo : await checkForUpdates({ silent: false });
        const url = normalizeReleaseUrl(info?.downloadUrl);
        try {
            window.open(url, "_blank", "noopener,noreferrer");
            return url;
        } catch (_) {
            return null;
        }
    }

    function roomAdminMembers() {
        const admins = window.ChatRoomData?.Admin;
        return Array.isArray(admins)
            ? admins.map(Number).filter(Number.isFinite)
            : [];
    }

    function isRoomAdminMember(memberNumber) {
        const member = Number(memberNumber);
        if (!Number.isFinite(member)) return false;
        return roomAdminMembers().includes(member);
    }

    function canSetRoomMascot() {
        try {
            if (typeof window.ChatRoomPlayerIsAdmin === "function" && window.ChatRoomPlayerIsAdmin()) return true;
        } catch (_) {}
        return isRoomAdminMember(window.Player?.MemberNumber);
    }

    function currentRoomMascotCacheKey() {
        const data = window.ChatRoomData;
        const name = String(data?.Name || "").trim();
        if (!name) return null;
        const space = String(data?.Space || "MainHall").trim() || "MainHall";
        return `${space}::${name}`;
    }

    function getRoomMascotCache() {
        if (roomMascotCacheState) return roomMascotCacheState;
        const stored = readLocalJSON(ROOM_MASCOT_CACHE_STORAGE_KEY, {});
        roomMascotCacheState = stored && typeof stored === "object" ? stored : {};
        return roomMascotCacheState;
    }

    function getRoomMascotLocalPositionStore() {
        if (roomMascotPositionState) return roomMascotPositionState;
        const stored = readLocalJSON(ROOM_MASCOT_POSITION_STORAGE_KEY, {});
        roomMascotPositionState = stored && typeof stored === "object" ? stored : {};
        return roomMascotPositionState;
    }

    function getLocalRoomMascotPosition() {
        const key = currentRoomMascotCacheKey();
        const stored = key ? getRoomMascotLocalPositionStore()?.[key] : null;
        const x = Number(stored?.x);
        const y = Number(stored?.y);
        return {
            x: Number.isFinite(x) ? Math.max(0, Math.min(1, x)) : 0.94,
            y: Number.isFinite(y) ? Math.max(0, Math.min(1, y)) : 0.16,
        };
    }

    function setLocalRoomMascotPosition(x, y) {
        const key = currentRoomMascotCacheKey();
        if (!key) return false;
        const store = getRoomMascotLocalPositionStore();
        store[key] = {
            x: Math.max(0, Math.min(1, Number(x) || 0)),
            y: Math.max(0, Math.min(1, Number(y) || 0)),
        };
        writeLocalJSON(ROOM_MASCOT_POSITION_STORAGE_KEY, store);
        return true;
    }

    function cacheRoomMascotState(state) {
        const key = currentRoomMascotCacheKey();
        if (!key) return false;
        const cache = getRoomMascotCache();
        if (state?.name) cache[key] = cloneBackupValue(state);
        else delete cache[key];
        writeLocalJSON(ROOM_MASCOT_CACHE_STORAGE_KEY, cache);
        return true;
    }

    function roomMascotFromSharedRoomData() {
        const raw = window.ChatRoomData?.Custom?.[ROOM_MASCOT_CUSTOM_KEY];
        if (!raw) return null;
        const name = typeof raw === "string" ? raw : raw?.name;
        if (typeof name !== "string" || !name.trim()) return null;
        const known = PLUSH_NAMES.find(entry => String(entry || "").toLowerCase() === name.trim().toLowerCase());
        if (!known) return null;
        const member = Number(raw?.memberNumber);
        const affectionModifier = Number(raw?.affectionModifier);
        return {
            name: known,
            setBy: typeof raw?.setBy === "string" && raw.setBy.trim() ? raw.setBy.trim() : "room admin",
            memberNumber: Number.isFinite(member) ? member : null,
            at: typeof raw?.at === "string" ? raw.at : null,
            affectionModifier: Number.isFinite(affectionModifier) ? affectionModifier : ROOM_MASCOT_AFFECTION_MODIFIER,
            shared: true,
        };
    }

    function recoverRoomMascotState({ allowCache = true } = {}) {
        const roomLoaded = !!String(window.ChatRoomData?.Name || "").trim();
        const shared = roomMascotFromSharedRoomData();
        if (shared) {
            roomMascotState = shared;
            cacheRoomMascotState(shared);
            refreshRoomMascotOverlay();
            return { source: "room", state: { ...shared } };
        }

        if (roomLoaded) {
            cacheRoomMascotState(null);
            roomMascotState = null;
            removeRoomMascotOverlay();
            return { source: "room-none", state: null };
        }

        const key = currentRoomMascotCacheKey();
        const cached = allowCache && key ? getRoomMascotCache()?.[key] : null;
        if (cached?.name && mascotRenderIndex(cached.name) >= 0) {
            roomMascotState = { ...cached, cached: true };
            refreshRoomMascotOverlay();
            return { source: "cache", state: { ...roomMascotState } };
        }

        roomMascotState = null;
        removeRoomMascotOverlay();
        return { source: "none", state: null };
    }

    function buildRoomUpdatePayloadWithCustom(custom) {
        const data = window.ChatRoomData;
        if (!data || typeof data !== "object") return null;

        const room = {};
        const keys = [
            "Name", "Description", "Background", "Limit", "Admin", "Ban", "Private", "Locked",
            "Language", "BlockCategory", "Visibility", "Access", "Space", "Game", "Custom",
        ];
        for (const key of keys) {
            if (!Object.prototype.hasOwnProperty.call(data, key) || data[key] === undefined) continue;
            room[key] = cloneTransferValue(data[key]);
        }
        room.Custom = custom && Object.keys(custom).length ? custom : undefined;
        return room;
    }

    function roomMascotMapViewDetected() {
        try {
            if (window.ChatRoomActiveView && window.ChatRoomViews?.Map && window.ChatRoomActiveView === window.ChatRoomViews.Map) return true;
        } catch (_) {}
        return !!(
            document.getElementById("chat-room-map-view") ||
            document.getElementById("chat-room-map-view-panel") ||
            document.querySelector("[id^='chat-room-map-view']")
        );
    }

    function roomMascotMapPublishUnsafe() {
        return roomMascotMapViewDetected() && window.ChatRoomData?.MapData == null;
    }

    function publishRoomMascotSharedStateNow(state) {
        if (!canSetRoomMascot() || typeof window.ServerSend !== "function" || !window.ChatRoomData) return false;
        const currentCustom = window.ChatRoomData.Custom && typeof window.ChatRoomData.Custom === "object"
            ? cloneBackupValue(window.ChatRoomData.Custom)
            : {};
        if (state?.name) {
            currentCustom[ROOM_MASCOT_CUSTOM_KEY] = {
                name: state.name,
                setBy: state.setBy || getCharacterDisplayName(window.Player) || "room admin",
                memberNumber: Number(window.Player?.MemberNumber) || null,
                at: state.at || new Date().toISOString(),
                affectionModifier: Number.isFinite(Number(state.affectionModifier)) ? Number(state.affectionModifier) : ROOM_MASCOT_AFFECTION_MODIFIER,
            };
        } else {
            delete currentCustom[ROOM_MASCOT_CUSTOM_KEY];
        }

        const room = buildRoomUpdatePayloadWithCustom(currentCustom);
        if (!room) return false;

        window.ChatRoomData.Custom = Object.keys(currentCustom).length ? currentCustom : undefined;
        lastRoomMascotSharedSyncAt = Date.now();
        try {
            window.ServerSend("ChatRoomAdmin", {
                MemberNumber: window.Player?.ID,
                Room: room,
                Action: "Update",
            });
            return true;
        } catch (e) {
            warn("Could not persist the room mascot in shared room data:", e);
            return false;
        }
    }

    function flushQueuedRoomMascotPublish() {
        if (!queuedRoomMascotPublish) return false;
        if (roomMascotMapPublishUnsafe()) {
            const age = Date.now() - queuedRoomMascotPublish.createdAt;
            if (age > 30000) {
                queuedRoomMascotPublish = null;
                queuedRoomMascotPublishTimer = null;
                warn("Room mascot update was not sent because the room map did not finish initializing.");
                return false;
            }
            queuedRoomMascotPublishTimer = window.setTimeout(flushQueuedRoomMascotPublish, 500);
            return false;
        }
        const pending = queuedRoomMascotPublish;
        queuedRoomMascotPublish = null;
        queuedRoomMascotPublishTimer = null;
        return publishRoomMascotSharedStateNow(pending.state);
    }

    function queueRoomMascotSharedState(state) {
        queuedRoomMascotPublish = {
            state: state?.name ? cloneBackupValue(state) : null,
            createdAt: Date.now(),
        };
        if (queuedRoomMascotPublishTimer == null) {
            queuedRoomMascotPublishTimer = window.setTimeout(flushQueuedRoomMascotPublish, 500);
        }
        return true;
    }

    function publishRoomMascotSharedState(state) {
        if (window.CurrentScreen === "ChatAdmin") return true;
        if (roomMascotMapPublishUnsafe()) return queueRoomMascotSharedState(state);
        return publishRoomMascotSharedStateNow(state);
    }

    function mascotRenderIndex(name) {
        const wanted = String(name || "").trim().toLowerCase();
        if (!wanted) return -1;
        return PLUSH_NAMES.findIndex(entry => String(entry || "").trim().toLowerCase() === wanted);
    }

    function removeRoomMascotOverlay() {
        try { roomMascotOverlay?.remove?.(); } catch (_) {}
        roomMascotOverlay = null;
        roomMascotOverlayImage = null;
        roomMascotOverlayLabel = null;
    }

    function roomMascotShouldYieldToMenus() {
        if (nativeLayeringVisible()) return true;
        if (window.DialogFocusItem) return true;
        return false;
    }

    function scheduleRoomMascotUiRefresh() {
        window.setTimeout(() => {
            refreshRoomMascotOverlay();
            refreshDragToggleButton();
            refreshRoomMascotAdminButton();
        }, 0);
    }

    function installRoomMascotUiSafety() {
        if (mascotUiHooksInstalled) return true;
        mascotUiHooksInstalled = true;

        document.addEventListener("pointerdown", event => {
            if (roomMascotOverlay && roomMascotOverlay.contains?.(event.target)) return;
            scheduleRoomMascotUiRefresh();
        }, true);

        document.addEventListener("keydown", event => {
            if (["Escape", "Enter", " "].includes(event.key)) scheduleRoomMascotUiRefresh();
        }, true);

        window.addEventListener("resize", () => {
            scheduleRoomMascotUiRefresh();
            refreshRoomMascotAdminButton();
        }, { passive: true });

        return true;
    }

    function refreshRoomMascotOverlay() {
        const settings = getFeatureSettings();
        const inRoom = window.CurrentScreen === "ChatRoom";
        if (!settings.showRoomMascot || !inRoom || !roomMascotState?.name) {
            removeRoomMascotOverlay();
            return false;
        }
        if (roomMascotShouldYieldToMenus()) {
            if (roomMascotOverlay?.isConnected) roomMascotOverlay.style.display = "none";
            return false;
        }
        const canvas = document.getElementById("MainCanvas") || document.querySelector("canvas");
        const rect = canvas?.getBoundingClientRect?.();
        if (!canvas || !rect || rect.width <= 0 || rect.height <= 0) {
            removeRoomMascotOverlay();
            return false;
        }
        const mascotPosition = getLocalRoomMascotPosition();
        if (roomMascotOverlay?.isConnected && roomMascotOverlay.parentElement !== document.body) removeRoomMascotOverlay();
        if (!roomMascotOverlay?.isConnected) {
            const root = document.createElement("div");
            root.className = "SubbysPlushiesRoomMascot";
            Object.assign(root.style, {
                position: "fixed",
                zIndex: "2147482600",
                boxSizing: "border-box",
                border: "1px solid currentColor",
                borderRadius: "8px",
                background: "rgba(20, 20, 20, 0.72)",
                color: "white",
                textAlign: "center",
                fontFamily: "Arial, sans-serif",
                lineHeight: "1.2",
                userSelect: "none",
                cursor: "move",
                pointerEvents: "auto",
                touchAction: "none",
            });
            const image = document.createElement("img");
            image.alt = "Room mascot plushie";
            Object.assign(image.style, { display: "block", objectFit: "contain", margin: "0 auto", pointerEvents: "none" });
            const label = document.createElement("div");
            Object.assign(label.style, { pointerEvents: "none", display: "flex", flexDirection: "column", alignItems: "center", gap: "1px" });
            root.addEventListener("pointerdown", event => {
                if (event.button !== 0) return;
                event.preventDefault();
                event.stopPropagation();
                roomMascotDragSession = {
                    pointerId: event.pointerId,
                    startX: event.clientX,
                    startY: event.clientY,
                    moved: false,
                    canDrag: true,
                    position: getLocalRoomMascotPosition(),
                };
                try { root.setPointerCapture?.(event.pointerId); } catch (_) {}
            });
            root.addEventListener("pointermove", event => {
                const session = roomMascotDragSession;
                if (!session || session.pointerId !== event.pointerId || !session.canDrag) return;
                const dx = event.clientX - session.startX;
                const dy = event.clientY - session.startY;
                if (!session.moved && Math.hypot(dx, dy) < 4) return;
                session.moved = true;
                const liveRect = (document.getElementById("MainCanvas") || document.querySelector("canvas"))?.getBoundingClientRect?.();
                if (!liveRect || liveRect.width <= 0 || liveRect.height <= 0) return;
                session.position = {
                    x: Math.max(0, Math.min(1, (event.clientX - liveRect.left) / liveRect.width)),
                    y: Math.max(0, Math.min(1, (event.clientY - liveRect.top) / liveRect.height)),
                };
                setLocalRoomMascotPosition(session.position.x, session.position.y);
                refreshRoomMascotOverlay();
            });
            const finishMascotDrag = event => {
                const session = roomMascotDragSession;
                if (!session || session.pointerId !== event.pointerId) return;
                roomMascotDragSession = null;
                try { root.releasePointerCapture?.(event.pointerId); } catch (_) {}
                if (!session.moved) {
                    showRoomMascot();
                    return;
                }
                if (session.position) setLocalRoomMascotPosition(session.position.x, session.position.y);
            };
            root.addEventListener("pointerup", finishMascotDrag);
            root.addEventListener("pointercancel", finishMascotDrag);
            root.append(image, label);
            document.body.appendChild(root);
            roomMascotOverlay = root;
            roomMascotOverlayImage = image;
            roomMascotOverlayLabel = label;
        }
        const currentDpr = Math.max(0.1, Number(window.devicePixelRatio) || ROOM_MASCOT_BASE_DEVICE_PIXEL_RATIO);
        const browserZoomRatio = currentDpr / ROOM_MASCOT_BASE_DEVICE_PIXEL_RATIO;
        const zoomNeutralWidth = rect.width * browserZoomRatio;
        const zoomNeutralHeight = rect.height * browserZoomRatio;
        const viewportScale = Math.max(0.52, Math.min(1, Math.min(zoomNeutralWidth / 1000, zoomNeutralHeight / 760)));
        const zoomCssCompensation = 1 / browserZoomRatio;
        const overlayWidth = Math.max(38, Math.round(72 * viewportScale * zoomCssCompensation));
        const padding = Math.max(2, Math.round(6 * viewportScale * zoomCssCompensation));
        const imageSize = Math.max(24, overlayWidth - padding * 2);
        const fontSize = Math.max(7, Math.round(13 * viewportScale * zoomCssCompensation));
        const rawLeft = rect.left + mascotPosition.x * rect.width - overlayWidth / 2;
        const estimatedHeight = overlayWidth + Math.max(12, Math.round(31 * viewportScale * zoomCssCompensation));
        const rawTop = rect.top + mascotPosition.y * rect.height - estimatedHeight / 2;
        const left = Math.max(rect.left + 2, Math.min(rect.right - overlayWidth - 2, rawLeft));
        const top = Math.max(rect.top + 2, Math.min(rect.bottom - estimatedHeight - 2, rawTop));
        Object.assign(roomMascotOverlay.style, {
            left: `${Math.round(left)}px`,
            top: `${Math.round(top)}px`,
            right: "auto",
            display: "block",
            width: `${overlayWidth}px`,
            padding: `${padding}px`,
            fontSize: `${fontSize}px`,
            cursor: "move",
        });
        Object.assign(roomMascotOverlayImage.style, {
            width: `${imageSize}px`,
            height: `${imageSize}px`,
            marginBottom: `${Math.max(1, Math.round(4 * viewportScale * zoomCssCompensation))}px`,
        });
        const index = mascotRenderIndex(roomMascotState.name);
        const imageSource = index >= 0 ? uiPlushImageSource(index) : uiPlushImageSource(0);
        if (roomMascotOverlayImage && roomMascotOverlayImage.src !== imageSource) roomMascotOverlayImage.src = imageSource;
        if (roomMascotOverlayLabel) {
            roomMascotOverlayLabel.innerHTML = "";
            const titleLine = document.createElement("div");
            titleLine.textContent = "Room Mascot";
            Object.assign(titleLine.style, { fontWeight: "bold", whiteSpace: "nowrap", maxWidth: "100%", overflow: "hidden", textOverflow: "ellipsis" });
            const nameLine = document.createElement("div");
            nameLine.textContent = roomMascotState.name;
            Object.assign(nameLine.style, { whiteSpace: "nowrap", maxWidth: "100%", overflow: "hidden", textOverflow: "ellipsis" });
            roomMascotOverlayLabel.append(titleLine, nameLine);
        }
        return true;
    }

    function setRoomMascotOverlayVisible(visible) {
        const enabled = setFeatureSetting("showRoomMascot", !!visible);
        if (enabled) refreshRoomMascotOverlay();
        else removeRoomMascotOverlay();
        appendLocalInfoBox("Room mascot", [enabled
            ? "Room mascot picture is visible locally."
            : "Room mascot picture is hidden locally. Use /plushiemascot show to restore it."]);
        return enabled;
    }

    function setRoomMascotByName(name, options = null) {
        const wanted = String(name || "").trim();
        const known = Array.from({ length: PUBLIC_PLUSH_COUNT }, (_, option) => publicPlushName(option))
            .find(entry => String(entry || "").toLowerCase() === wanted.toLowerCase());
        if (!known) return false;
        if (!canSetRoomMascot()) {
            appendLocalInfoBox("Room mascot", ["Only a verified room admin can set the shared mascot."]);
            return false;
        }
        const randomPick = !!options?.randomPick;
        const source = getCharacterDisplayName(window.Player) || "Someone";
        if (window.CurrentScreen === "ChatAdmin" && !roomMascotAdminDirty) {
            roomMascotAdminSnapshot = roomMascotFromSharedRoomData();
        }
        roomMascotState = {
            name: known,
            setBy: source,
            memberNumber: Number(window.Player?.MemberNumber) || null,
            at: new Date().toISOString(),
            affectionModifier: ROOM_MASCOT_AFFECTION_MODIFIER,
            shared: true,
        };
        cacheRoomMascotState(roomMascotState);
        refreshRoomMascotOverlay();
        if (window.CurrentScreen === "ChatAdmin") {
            roomMascotAdminDirty = true;
            roomMascotAdminPendingAction = { type: "set", source, name: known, randomPick };
            appendLocalInfoBox("Room mascot", [
                randomPick
                    ? `${known} was chosen randomly. Use the room Save button to publish it.`
                    : `${known} selected. Use the room Save button to publish it.`,
            ]);
            return true;
        }
        const persisted = publishRoomMascotSharedState(roomMascotState);
        sendStandaloneActionMessage(randomPick
            ? `${known} was chosen randomly as the room mascot plushie.`
            : `${source} sets ${known} as the room mascot plushie.`);
        if (!persisted) appendLocalInfoBox("Room mascot", ["Mascot was set locally, but the shared room-state update could not be sent."]);
        recordStat("mascot", 1, { plushName: known });
        return true;
    }

    function setRoomMascotByOption(option, options = null) {
        const publicOption = Number(option);
        if (!validPublicPlushOption(publicOption)) return false;
        const wire = publicToWirePlushOption(publicOption);
        return setRoomMascotByName(PLUSH_NAMES[wire], options);
    }

    function pickRandomRoomMascot(options = null) {
        if (!canSetRoomMascot()) {
            appendLocalInfoBox("Room mascot", ["Only a verified room admin can set the shared mascot."]);
            return false;
        }
        const available = [];
        for (let option = 0; option < PUBLIC_PLUSH_COUNT; option++) {
            if (!validPublicPlushOption(option)) continue;
            const wire = publicToWirePlushOption(option);
            const name = PLUSH_NAMES[wire];
            if (name) available.push({ option, name });
        }
        const exclude = normalizeLoreLookupKey(options?.excludeName);
        const choices = exclude && available.length > 1
            ? available.filter(entry => normalizeLoreLookupKey(entry.name) !== exclude)
            : available;
        if (!choices.length) {
            appendLocalInfoBox("Room mascot", ["No plushies are available to choose from."]);
            return false;
        }
        const selected = choices[Math.floor(Math.random() * choices.length)];
        return setRoomMascotByOption(selected.option, { randomPick: true });
    }

    function closeRoomMascotPicker() {
        try { roomMascotPickerElement?.remove?.(); } catch (_) {}
        roomMascotPickerElement = null;
        return true;
    }

    function openRoomMascotPicker() {
        if (!canSetRoomMascot()) return false;
        closeRoomMascotPicker();
        const root = document.createElement("div");
        root.className = "SubbysPlushiesMascotPicker";
        Object.assign(root.style, {
            position: "fixed",
            inset: "0",
            zIndex: "2147483645",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: "18px",
            boxSizing: "border-box",
            background: "rgba(0,0,0,.55)",
        });
        const panel = document.createElement("div");
        Object.assign(panel.style, {
            width: "min(860px, 96vw)",
            maxHeight: "88vh",
            overflow: "auto",
            boxSizing: "border-box",
            padding: "16px",
            border: "2px solid #6f536f",
            borderRadius: "12px",
            background: "#fff8ff",
            color: "#241924",
            font: "14px Arial, sans-serif",
            boxShadow: "0 12px 40px rgba(0,0,0,.45)",
        });
        const title = document.createElement("div");
        title.textContent = "Pick Room Mascot";
        Object.assign(title.style, { fontSize: "20px", fontWeight: "bold", marginBottom: "12px", textAlign: "center" });
        const grid = document.createElement("div");
        Object.assign(grid.style, {
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))",
            gap: "10px",
        });
        for (let option = 0; option < PUBLIC_PLUSH_COUNT; option++) {
            const wire = publicToWirePlushOption(option);
            const name = PLUSH_NAMES[wire];
            const button = document.createElement("button");
            button.type = "button";
            Object.assign(button.style, {
                minHeight: "142px",
                padding: "8px",
                border: "1px solid #8c718c",
                borderRadius: "9px",
                background: "#ffffff",
                color: "#241924",
                font: "13px Arial, sans-serif",
                cursor: "pointer",
            });
            const image = installUiPlushImageFallback(document.createElement("img"));
            image.alt = name;
            image.loading = "lazy";
            image.decoding = "async";
            image.src = uiPlushImageSource(wire);
            Object.assign(image.style, { display: "block", width: "92px", height: "92px", objectFit: "contain", margin: "0 auto 6px" });
            const label = document.createElement("div");
            label.textContent = name;
            Object.assign(label.style, { fontWeight: "bold", lineHeight: "1.15" });
            button.append(image, label);
            button.addEventListener("click", event => {
                event.preventDefault();
                event.stopPropagation();
                if (setRoomMascotByOption(option)) closeRoomMascotPicker();
            });
            grid.appendChild(button);
        }
        const controls = document.createElement("div");
        Object.assign(controls.style, { display: "flex", justifyContent: "center", gap: "10px", marginTop: "14px", flexWrap: "wrap" });
        const random = document.createElement("button");
        random.type = "button";
        random.textContent = "Pick Random Mascot";
        const clear = document.createElement("button");
        clear.type = "button";
        clear.textContent = "Clear Mascot";
        const cancel = document.createElement("button");
        cancel.type = "button";
        cancel.textContent = "Cancel";
        for (const button of [random, clear, cancel]) Object.assign(button.style, { font: "14px Arial, sans-serif", padding: "8px 16px", cursor: "pointer" });
        random.addEventListener("click", event => {
            event.preventDefault();
            event.stopPropagation();
            if (pickRandomRoomMascot()) closeRoomMascotPicker();
        });
        clear.addEventListener("click", event => { event.preventDefault(); if (clearRoomMascot()) closeRoomMascotPicker(); });
        cancel.addEventListener("click", event => { event.preventDefault(); closeRoomMascotPicker(); });
        root.addEventListener("pointerdown", event => { if (event.target === root) closeRoomMascotPicker(); });
        panel.addEventListener("pointerdown", event => event.stopPropagation());
        controls.append(random, clear, cancel);
        panel.append(title, grid, controls);
        root.appendChild(panel);
        document.body.appendChild(root);
        roomMascotPickerElement = root;
        return true;
    }

    function removeRoomMascotAdminButton() {
        try { roomMascotAdminButton?.remove?.(); } catch (_) {}
        roomMascotAdminButton = null;
    }

    function refreshRoomMascotAdminButton() {
        const visible = window.CurrentScreen === "ChatAdmin" && canSetRoomMascot();
        if (!visible) {
            removeRoomMascotAdminButton();
            if (window.CurrentScreen !== "ChatAdmin") closeRoomMascotPicker();
            return false;
        }
        if (!roomMascotAdminButton?.isConnected) {
            const button = document.createElement("button");
            button.type = "button";
            button.className = "SubbysPlushiesMascotAdminButton";
            button.textContent = "Pick Room Mascot";
            Object.assign(button.style, {
                position: "fixed",
                zIndex: "2147483500",
                boxSizing: "border-box",
                borderRadius: "8px",
                cursor: "pointer",
            });
            button.addEventListener("click", event => {
                event.preventDefault();
                event.stopPropagation();
                openRoomMascotPicker();
            });
            document.body.appendChild(button);
            roomMascotAdminButton = button;
        }
        const scale = Math.max(0.58, Math.min(1, Math.min(window.innerWidth / 1200, window.innerHeight / 800)));
        Object.assign(roomMascotAdminButton.style, {
            right: `${Math.max(8, Math.round(18 * scale))}px`,
            bottom: `${Math.max(8, Math.round(18 * scale))}px`,
            width: `${Math.round(190 * scale)}px`,
            height: `${Math.round(42 * scale)}px`,
            font: `bold ${Math.max(10, Math.round(14 * scale))}px Arial, sans-serif`,
        });
        return true;
    }

    function installRoomMascotAdminPicker() {
        if (roomMascotAdminHookInstalled) return true;
        roomMascotAdminHookInstalled = true;
        installHook("ChatAdminRun", 1000, (args, next) => {
            const result = next(args);
            refreshRoomMascotAdminButton();
            return result;
        });
        installHook("ChatAdminExit", 1000, (args, next) => {
            const revertPending = roomMascotAdminDirty;
            const snapshot = roomMascotAdminSnapshot ? cloneBackupValue(roomMascotAdminSnapshot) : null;
            closeRoomMascotPicker();
            removeRoomMascotAdminButton();
            const result = next(args);
            if (revertPending) {
                roomMascotAdminDirty = false;
                roomMascotAdminSnapshot = null;
                roomMascotAdminPendingAction = null;
                roomMascotState = snapshot;
                cacheRoomMascotState(snapshot);
                if (snapshot?.name) refreshRoomMascotOverlay();
                else removeRoomMascotOverlay();
            }
            return result;
        });
        return true;
    }

    function setCurrentPlushAsRoomMascot() {
        if (!isOurs(getHeld(window.Player))) {
            appendLocalInfoBox("Room mascot", ["Equip a Subby's Plushies plushie first."]);
            return false;
        }
        const name = currentPlushName();
        const changed = setRoomMascotByName(name);
        if (changed) adjustCurrentPlushMood(3, "room mascot");
        return changed;
    }

    function clearRoomMascot() {
        if (!canSetRoomMascot()) {
            appendLocalInfoBox("Room mascot", ["Only a verified room admin can clear the shared mascot."]);
            return false;
        }
        const source = getCharacterDisplayName(window.Player) || "Someone";
        if (window.CurrentScreen === "ChatAdmin" && !roomMascotAdminDirty) {
            roomMascotAdminSnapshot = roomMascotFromSharedRoomData();
        }
        roomMascotState = null;
        cacheRoomMascotState(null);
        removeRoomMascotOverlay();
        if (window.CurrentScreen === "ChatAdmin") {
            roomMascotAdminDirty = true;
            roomMascotAdminPendingAction = { type: "clear", source };
            appendLocalInfoBox("Room mascot", ["Mascot cleared for this edit. Use the room Save button to publish it."]);
            return true;
        }
        const persisted = publishRoomMascotSharedState(null);
        sendStandaloneActionMessage(`${source} clears the room mascot plushie.`);
        if (!persisted) appendLocalInfoBox("Room mascot", ["Mascot was cleared locally, but the shared room-state update could not be sent."]);
        return true;
    }

    function processRoomMascotAction(data) {
        const text = getDictionaryText(data, "msg");
        if (typeof text !== "string") return false;

        const senderMember = Number(data?.Sender);
        if (!isRoomAdminMember(senderMember)) return false;

        const clear = text.match(ROOM_MASCOT_CLEAR_RE);
        if (clear) {
            roomMascotState = null;
            cacheRoomMascotState(null);
            removeRoomMascotOverlay();
            return true;
        }
        const random = text.match(ROOM_MASCOT_RANDOM_RE);
        if (random) {
            const renderedName = String(random[1] || "").trim();
            const known = PLUSH_NAMES.find(name => name.toLowerCase() === renderedName.toLowerCase()) || renderedName;
            const sender = getRoomCharacterByMember(senderMember);
            roomMascotState = {
                name: known,
                setBy: getCharacterDisplayName(sender) || "room admin",
                memberNumber: senderMember,
                at: new Date().toISOString(),
                affectionModifier: ROOM_MASCOT_AFFECTION_MODIFIER,
                shared: true,
            };
            cacheRoomMascotState(roomMascotState);
            refreshRoomMascotOverlay();
            return true;
        }
        const set = text.match(ROOM_MASCOT_SET_RE);
        if (!set) return false;
        const renderedName = String(set[2] || "").trim();
        const known = PLUSH_NAMES.find(name => name.toLowerCase() === renderedName.toLowerCase()) || renderedName;
        roomMascotState = {
            name: known,
            setBy: String(set[1] || "Someone").trim(),
            memberNumber: senderMember,
            at: new Date().toISOString(),
            affectionModifier: ROOM_MASCOT_AFFECTION_MODIFIER,
            shared: true,
        };
        cacheRoomMascotState(roomMascotState);
        refreshRoomMascotOverlay();
        return true;
    }

    function showRoomMascot() {
        if (!roomMascotState) {
            appendLocalInfoBox("Room mascot", ["No shared mascot is currently stored for this room."]);
            return null;
        }
        appendLocalInfoBox("Room mascot", [
            `${roomMascotState.name} • set by ${roomMascotState.setBy || "room admin"}${roomMascotState.cached ? " • cached" : ""}`,
            `Mascot affection modifier: +${Number(roomMascotState.affectionModifier ?? ROOM_MASCOT_AFFECTION_MODIFIER) || 0}`,
            `Picture: ${getFeatureSettings().showRoomMascot ? "visible" : "hidden locally"}`,
        ]);
        return { ...roomMascotState };
    }

    function handleRoomMascotCommand(command) {
        const arg = String(command || "").split(/\s+/)[1] || "info";
        if (arg === "set") return setCurrentPlushAsRoomMascot();
        if (arg === "random") return pickRandomRoomMascot();
        if (arg === "clear" || arg === "remove") return clearRoomMascot();
        if (arg === "hide") return setRoomMascotOverlayVisible(false);
        if (arg === "show" || arg === "unhide") return setRoomMascotOverlayVisible(true);
        if (arg === "picker" || arg === "pick" || arg === "open" || arg === "choose") return openRoomMascotPicker();
        return showRoomMascot();
    }

    function currentPlushCanvasBounds(item) {
        const transform = readActivePlushLayerTransform(item);
        if (!transform) return null;

        const scaleX = Math.max(0.05, Math.abs(Number(transform.ScaleX) || 1));
        const scaleY = Math.max(0.05, Math.abs(Number(transform.ScaleY) || 1));
        const width = PLUSH_RENDER.Width * scaleX;
        const height = PLUSH_RENDER.Height * scaleY;
        const centerX = PLUSH_RENDER.Left + PLUSH_RENDER.Width / 2 + transform.TranslationX;
        const centerY = PLUSH_RENDER.Top + PLUSH_RENDER.Height / 2 + transform.TranslationY;

        const radians = (Number(transform.Rotation) || 0) * Math.PI / 180;
        const cos = Math.abs(Math.cos(radians));
        const sin = Math.abs(Math.sin(radians));
        const boundWidth = width * cos + height * sin;
        const boundHeight = width * sin + height * cos;
        const padding = 12;

        const visualLeft = centerX - boundWidth / 2;
        const visualRight = centerX + boundWidth / 2;
        const visualTop = centerY - boundHeight / 2;
        const visualBottom = centerY + boundHeight / 2;

        return {
            left: visualLeft - padding,
            right: visualRight + padding,
            top: visualTop - padding,
            bottom: visualBottom + padding,
            visualLeft,
            visualRight,
            visualTop,
            visualBottom,
            centerX,
            centerY,
            transform,
        };
    }

    function plushNameForItem(item) {
        if (!isOurs(item)) return "Plushie";
        const option = canonicalWirePlushOption(getItemPlushOption(item));
        return validPlushOption(option) ? (PLUSH_NAMES[option] || "Plushie") : "Plushie";
    }

    function dragTargetLabel(groupName = getDragTargetGroup()) {
        const item = getInventoryItem(window.Player, groupName);
        const slot = groupName === ADDON_GROUP ? "Body (Ceiling Rope slot)" : "Handheld";
        return isOurs(item) ? `${slot} — ${plushNameForItem(item)}` : `${slot} — not equipped`;
    }

    function getDragTargetGroup() {
        if (!dragTargetGroupState) {
            const stored = readLocalJSON(DRAG_TARGET_GROUP_STORAGE_KEY, {});
            const storedGroup = String(stored?.group || "");
            dragTargetGroupState = PLUSH_GROUPS.includes(storedGroup) ? storedGroup : GROUP;
        }

        const preferred = getInventoryItem(window.Player, dragTargetGroupState);
        if (isOurs(preferred)) return dragTargetGroupState;

        const fallback = PLUSH_GROUPS.find(groupName => isOurs(getInventoryItem(window.Player, groupName)));
        if (fallback && fallback !== dragTargetGroupState) {
            dragTargetGroupState = fallback;
            writeLocalJSON(DRAG_TARGET_GROUP_STORAGE_KEY, { group: fallback });
        }
        return dragTargetGroupState;
    }

    function getDragTargetItem() {
        return getInventoryItem(window.Player, getDragTargetGroup());
    }

    function setDragTargetGroup(groupName) {
        const normalized = String(groupName || "");
        if (!PLUSH_GROUPS.includes(normalized)) return false;
        const item = getInventoryItem(window.Player, normalized);
        if (!isOurs(item)) return false;
        if (dragSession) finishDirectDrag(true);
        dragTargetGroupState = normalized;
        writeLocalJSON(DRAG_TARGET_GROUP_STORAGE_KEY, { group: normalized });

        if (speechBubbleElement?.isConnected) {
            speechBubbleGroupName = normalized;
            positionSpeechBubble();
        }
        if (plushStatusIconElement?.isConnected) positionPlushStatusIcon();

        refreshDragToggleButton();
        renderDragUi();
        return true;
    }

    function closeDragUi() {
        try { dragUiElement?.remove?.(); } catch (_) {}
        dragUiElement = null;
        return true;
    }

    function renderDragUi() {
        if (!dragUiElement?.isConnected) return false;
        const style = getExtensionsStyle();
        dragUiElement.replaceChildren();

        const header = document.createElement("div");
        Object.assign(header.style, { display: "flex", alignItems: "center", justifyContent: "space-between", gap: "12px", marginBottom: "10px" });
        const title = document.createElement("strong");
        title.textContent = "Drag UI";
        Object.assign(title.style, { fontSize: "20px", color: style.accent });
        const close = makeExtensionsButton("Close", closeDragUi);
        header.append(title, close);

        const hint = document.createElement("div");
        hint.textContent = "Choose which equipped plushie Easy Drag controls, then enable or disable dragging.";
        Object.assign(hint.style, { color: style.muted, fontSize: "12px", lineHeight: "1.4", marginBottom: "12px" });

        const targetTitle = document.createElement("div");
        targetTitle.textContent = "Drag target";
        Object.assign(targetTitle.style, { fontWeight: "bold", color: style.text, marginBottom: "7px" });

        const targets = document.createElement("div");
        Object.assign(targets.style, { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px", marginBottom: "12px" });
        const selectedGroup = getDragTargetGroup();
        for (const groupName of PLUSH_GROUPS) {
            const item = getInventoryItem(window.Player, groupName);
            const available = isOurs(item);
            const button = makeExtensionsButton(dragTargetLabel(groupName), () => {
                if (available) setDragTargetGroup(groupName);
            }, { active: available && selectedGroup === groupName });
            button.disabled = !available;
            if (!available) {
                button.style.opacity = "0.48";
                button.style.cursor = "not-allowed";
            }
            targets.appendChild(button);
        }

        const mode = makeExtensionsButton(dragModeEnabled ? "Disable Easy Drag" : "Enable Easy Drag", () => {
            setDragMode(!dragModeEnabled);
            renderDragUi();
        }, { active: dragModeEnabled });
        mode.style.width = "100%";

        const dragButtonVisible = !!getFeatureSettings().showDragButton;
        const addDragButton = makeExtensionsButton(
            dragButtonVisible ? "Hide Drag Button" : "Show Drag Button",
            () => {
                setFeatureSetting("showDragButton", !getFeatureSettings().showDragButton);
                refreshDragToggleButton();
                renderDragUi();
            },
            { active: dragButtonVisible }
        );
        addDragButton.style.width = "100%";
        addDragButton.style.marginTop = "8px";

        const status = document.createElement("div");
        const targetItem = getDragTargetItem();
        status.textContent = isOurs(targetItem)
            ? `Current target: ${dragTargetLabel(getDragTargetGroup())} • Easy Drag ${dragModeEnabled ? "ON" : "off"}`
            : "Equip a handheld or Body-slot plushie to use Easy Drag.";
        Object.assign(status.style, { color: style.muted, fontSize: "12px", marginTop: "9px", lineHeight: "1.35" });

        dragUiElement.append(header, hint, targetTitle, targets, mode, addDragButton, status);
        return true;
    }

    function openDragUi() {
        closeDragUi();
        const root = document.createElement("div");
        root.className = "SubbysPlushiesDragUi";
        const style = getExtensionsStyle();
        Object.assign(root.style, {
            position: "fixed",
            zIndex: "2147483450",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
            width: "min(520px, calc(100vw - 28px))",
            boxSizing: "border-box",
            padding: "14px",
            border: `2px solid ${style.border}`,
            borderRadius: "12px",
            background: style.background,
            color: style.text,
            boxShadow: `7px 9px 0 ${style.shadow}, 0 14px 34px rgba(0,0,0,0.44)`,
            font: `${extensionsLayoutMetrics().fontSize}px Arial, sans-serif`,
        });
        root.addEventListener("pointerdown", event => event.stopPropagation());
        document.body.appendChild(root);
        dragUiElement = root;
        renderDragUi();
        return true;
    }

    function applyDragFrame(point) {
        const session = dragSession;
        if (!session || !point) return;
        const current = getInventoryItem(window.Player, session.groupName);
        if (!isOurs(current) || getActivePlushLayerName(current) !== session.layerName) return;
        const dx = point.x - session.startX;
        const dy = point.y - session.startY;
        const layerRatio = layerTranslationHeightRatio(window.Player);
        setPlushLayerTransform(current, session.layerName, {
            ...session.base,
            TranslationX: session.base.TranslationX + dx * layerRatio,
            TranslationY: session.base.TranslationY + dy * layerRatio,
        });

        if (session.overlayStartMainBounds &&
            Number.isFinite(point.mainX) && Number.isFinite(point.mainY)) {
            session.overlayCurrentMainBounds = translateMainBounds(
                session.overlayStartMainBounds,
                point.mainX - session.startMainX,
                point.mainY - session.startMainY
            );
        }

        rebuildCharacterCanvas(window.Player, "direct plush drag");
        scheduleLocalOverlayReposition();
        session.lastPoint = point;
    }

    function finishDirectDrag(cancelled = false) {
        const session = dragSession;
        if (dragFrameRequest != null) {
            cancelAnimationFrame(dragFrameRequest);
            dragFrameRequest = null;
        }
        if (!session) return false;

        const current = getInventoryItem(window.Player, session.groupName);
        if (!isOurs(current) || getActivePlushLayerName(current) !== session.layerName) {
            dragSession = null;
            return false;
        }

        if (cancelled) {
            setPlushLayerTransform(current, session.layerName, { ...session.base });
            session.overlayCurrentMainBounds = cloneBounds(session.overlayStartMainBounds);
        }

        compactPlushLayerTransformsToActive(current, readActivePlushLayerTransform(current));
        resetGenericNativeTransform(current);
        rememberCharacterPlushState(window.Player, current);

        if (!cancelled) commitDirectDragOverlayBounds(session, current);
        else directDragOverlayBoundsByGroup.delete(session.groupName);

        dragSession = null;

        rebuildCharacterCanvas(
            window.Player,
            cancelled ? "direct plush drag cancel" : "direct plush drag commit"
        );

        if (speechBubbleElement?.isConnected) {
            speechBubbleGroupName = session.groupName;
            positionSpeechBubble();
        }
        if (plushStatusIconElement?.isConnected) positionPlushStatusIcon();
        scheduleLocalOverlayReposition();

        if (!cancelled && typeof ChatRoomCharacterUpdate === "function") {
            try { ChatRoomCharacterUpdate(window.Player); } catch (_) {}
        }
        if (!cancelled) recordStat("drag", 1, { plushName: plushNameForItem(current) });
        return true;
    }

    function getDragTogglePosition() {
        if (dragTogglePositionState) return dragTogglePositionState;
        const stored = readLocalJSON(DRAG_TOGGLE_POSITION_STORAGE_KEY, {});
        const x = Number(stored?.x);
        const y = Number(stored?.y);
        dragTogglePositionState = {
            x: Number.isFinite(x) ? Math.max(0, Math.min(1, x)) : 0.92,
            y: Number.isFinite(y) ? Math.max(0, Math.min(1, y)) : 0.90,
        };
        return dragTogglePositionState;
    }

    function saveDragTogglePosition() {
        if (!dragTogglePositionState) return false;
        return writeLocalJSON(DRAG_TOGGLE_POSITION_STORAGE_KEY, dragTogglePositionState);
    }

    function removeDragToggleButton() {
        try { dragToggleButton?.remove?.(); } catch (_) {}
        dragToggleButton = null;
        dragToggleMoveSession = null;
    }

    function refreshDragToggleButton() {
        const inRoom = window.CurrentScreen === "ChatRoom";
        const item = getDragTargetItem();
        if (!getFeatureSettings().showDragButton || !inRoom || !isOurs(item) || nativeLayeringVisible()) {
            removeDragToggleButton();
            return false;
        }
        if (!dragToggleButton?.isConnected) {
            const button = document.createElement("button");
            button.type = "button";
            button.className = "SubbysPlushiesDragToggle";
            Object.assign(button.style, {
                position: "fixed",
                zIndex: "2147482500",
                width: "32px",
                height: "32px",
                padding: "0",
                border: "1px solid rgba(255,255,255,0.72)",
                borderRadius: "9px",
                color: "white",
                font: "16px/1 sans-serif",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "move",
                userSelect: "none",
                touchAction: "none",
                pointerEvents: "auto",
                boxShadow: "0 2px 6px rgba(0,0,0,0.30)",
            });
            button.addEventListener("pointerdown", event => {
                if (event.button !== 0) return;
                event.preventDefault();
                event.stopPropagation();
                event.stopImmediatePropagation();
                dragToggleMoveSession = { pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, moved: false };
                try { button.setPointerCapture?.(event.pointerId); } catch (_) {}
            });
            button.addEventListener("pointermove", event => {
                const session = dragToggleMoveSession;
                if (!session || session.pointerId !== event.pointerId) return;
                event.preventDefault();
                event.stopPropagation();
                const dx = event.clientX - session.startX;
                const dy = event.clientY - session.startY;
                if (!session.moved && Math.hypot(dx, dy) < 4) return;
                session.moved = true;
                const pos = getDragTogglePosition();
                pos.x = Math.max(0, Math.min(1, event.clientX / Math.max(1, window.innerWidth)));
                pos.y = Math.max(0, Math.min(1, event.clientY / Math.max(1, window.innerHeight)));
                refreshDragToggleButton();
            });
            const finish = event => {
                const session = dragToggleMoveSession;
                if (!session || session.pointerId !== event.pointerId) return;
                event.preventDefault();
                event.stopPropagation();
                event.stopImmediatePropagation();
                dragToggleMoveSession = null;
                try { button.releasePointerCapture?.(event.pointerId); } catch (_) {}
                if (session.moved) saveDragTogglePosition();
                else setDragMode(!dragModeEnabled);
            };
            button.addEventListener("pointerup", finish);
            button.addEventListener("pointercancel", event => {
                const session = dragToggleMoveSession;
                if (!session || session.pointerId !== event.pointerId) return;
                dragToggleMoveSession = null;
                saveDragTogglePosition();
            });
            document.body.appendChild(button);
            dragToggleButton = button;
        }
        const buttonSize = 32;
        const pos = getDragTogglePosition();
        const left = Math.max(2, Math.min(window.innerWidth - buttonSize - 2, pos.x * window.innerWidth - buttonSize / 2));
        const top = Math.max(2, Math.min(window.innerHeight - buttonSize - 2, pos.y * window.innerHeight - buttonSize / 2));
        dragToggleButton.style.left = `${Math.round(left)}px`;
        dragToggleButton.style.top = `${Math.round(top)}px`;
        dragToggleButton.textContent = "🖱️";
        const targetLabel = dragTargetLabel(getDragTargetGroup());
        dragToggleButton.setAttribute("aria-label", `${dragModeEnabled ? "Disable" : "Enable"} Easy Drag for ${targetLabel}`);
        dragToggleButton.title = `${targetLabel}. Easy Drag is ${dragModeEnabled ? "ON" : "OFF"} — click to ${dragModeEnabled ? "disable" : "enable"}; drag this button to move it.`;
        dragToggleButton.style.background = dragModeEnabled ? "rgba(72, 170, 105, 0.96)" : "rgba(28, 28, 32, 0.82)";
        dragToggleButton.style.opacity = dragModeEnabled ? "1" : "0.90";
        return true;
    }

    function installDragToggleUi() {
        refreshDragToggleButton();
        window.addEventListener("resize", refreshDragToggleButton, { passive: true });
        return true;
    }

    function setDragMode(enabled) {
        const next = !!enabled;
        if (next && !isOurs(getDragTargetItem())) {
            dragModeEnabled = false;
            refreshDragToggleButton();
            return false;
        }
        dragModeEnabled = next;
        if (!dragModeEnabled && dragSession) finishDirectDrag(true);
        refreshDragToggleButton();
        return dragModeEnabled;
    }

    function toggleDragMode() {
        return setDragMode(!dragModeEnabled);
    }

    function installDirectDragHandlers() {
        if (dragHandlersInstalled) return true;
        dragHandlersInstalled = true;

        document.addEventListener("pointerdown", event => {
            if (!dragModeEnabled || event.button !== 0 || nativeLayeringVisible()) return;
            const point = characterCanvasCoordinates(window.Player, event);
            if (!point || point.x >= 1000 || point.y < 0 || point.y > 1000) return;

            if (activeIdleAnimationSession) cancelIdleAnimation();
            if (activeBalanceHeadSession) restoreActiveBalanceHead("Easy Drag started");
            if (activeHideBehindSession) restoreActiveHideBehind("Easy Drag started");
            if (activeProtectSession) restoreActiveProtect("Easy Drag started");

            const groupName = getDragTargetGroup();
            const item = getInventoryItem(window.Player, groupName);
            if (!isOurs(item)) {
                setDragMode(false);
                return;
            }

            const layerName = getActivePlushLayerName(item);
            const base = readActivePlushLayerTransform(item);
            if (!layerName || !base) return;

            const overlayStartScreenBounds = plushScreenBounds(window.Player, item);
            const overlayStartMainBounds = screenBoundsToMainBounds(overlayStartScreenBounds);

            dragSession = {
                pointerId: event.pointerId,
                groupName,
                layerName,
                base: { ...base },
                startX: point.x,
                startY: point.y,
                startMainX: point.mainX,
                startMainY: point.mainY,
                overlayStartMainBounds,
                overlayCurrentMainBounds: cloneBounds(overlayStartMainBounds),
                lastPoint: point,
            };
            if (speechBubbleElement?.isConnected) speechBubbleGroupName = groupName;
            try { point.canvas.setPointerCapture?.(event.pointerId); } catch (_) {}
            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation();
        }, true);

        document.addEventListener("pointermove", event => {
            if (!dragSession || event.pointerId !== dragSession.pointerId) return;
            const point = characterCanvasCoordinates(window.Player, event);
            if (!point) return;
            dragSession.lastPoint = point;
            if (dragFrameRequest == null) {
                dragFrameRequest = requestAnimationFrame(() => {
                    dragFrameRequest = null;
                    if (dragSession?.lastPoint) applyDragFrame(dragSession.lastPoint);
                });
            }
            event.preventDefault();
        }, true);

        document.addEventListener("pointerup", event => {
            if (!dragSession || event.pointerId !== dragSession.pointerId) return;
            const point = characterCanvasCoordinates(window.Player, event);
            if (point) applyDragFrame(point);
            finishDirectDrag(false);
            event.preventDefault();
        }, true);

        document.addEventListener("pointercancel", event => {
            if (!dragSession || event.pointerId !== dragSession.pointerId) return;
            finishDirectDrag(true);
        }, true);
        return true;
    }

    function extensionsPreferenceScreenActive() {
        if (String(window.CurrentScreen || "") !== "Preference") return false;
        const candidates = [
            window.PreferenceSubscreen?.name,
            window.PreferenceSubscreen?.Name,
            window.PreferenceSubscreen,
            window.PreferenceSubScreen,
            window.PreferenceCurrentSubscreen,
            window.PreferenceCurrentSubScreen,
        ];
        return candidates.some(value => String(value || "").toLowerCase() === "extensions");
    }

