                for(let i=0;i<PIXELS;i++)result[i]=mode==="add"?(before[i]||incoming[i]?1:0):
                    mode==="subtract"?(before[i]&&!incoming[i]?1:0):(before[i]&&incoming[i]?1:0);
                selection=result;
